		runes := make([]rune, len(data))
		for i, b := range data {
			runes[i] = rune(b)
		}
		return Chars{runes: runes}
	}
	return Chars{runes: bytes.Runes(data)}
}

func RunesToChars(runes []rune) Chars {
	return Chars{runes: runes}
}

func (c *Chars) Length() int { return len(c.runes) }

func (c *Chars) Get(i int) rune { return c.runes[i] }

func (c *Chars) ToRunes() []rune { return c.runes }

func (c *Chars) ToString() string { return string(c.runes) }

func (c *Chars) Slice(b int, e int) Chars {
	return Chars{runes: c.runes[b:e]}
}

