	copy(dest, c.runes[from:])
}

func (c *Chars) Prepend(prefix string) {
	r := []rune(prefix)
	c.runes = append(r, c.runes...)
}

func (c *Chars) TrimLength() uint16 {
	i := 0
	for i < len(c.runes) && unicode.IsSpace(c.runes[i]) {
		i++
	}
	j := len(c.runes)
	for j > i && unicode.IsSpace(c.runes[j-1]) {
		j--
	}
	return asUint16(j - i)
}

func (c *Chars) LeadingWhitespaces() int {
	i := 0
	for i < len(c.runes) && unicode.IsSpace(c.runes[i]) {
		i++
	}
	return i
}

func (c *Chars) TrailingWhitespaces() int {
	n := 0
	for i := len(c.runes) - 1; i >= 0 && unicode.IsSpace(c.runes[i]); i-- {
		n++
	}
	return n
}

func (c *Chars) TrimTrailingWhitespaces() {
	n := c.TrailingWhitespaces()
	c.runes = c.runes[:len(c.runes)-n]
}

func (c *Chars) TrimSuffix(suffix []rune) {
	if len(suffix) > len(c.runes) {
		return
	}
	off := len(c.runes) - len(suffix)
	for i, r := range suffix {
		if c.runes[off+i] != r {
			return
		}
	}
	c.runes = c.runes[:off]
}

