	text := c.runes
	lines := [][]rune{}
	if multiLine {
		start := 0
		for i, r := range text {
			if r == '\n' {
				lines = append(lines, text[start:i+1])
				start = i + 1
			}
		}
		if start < len(text) || len(lines) == 0 {
			lines = append(lines, text[start:])
		}
	} else {
		lines = append(lines, text)
	}
	// Strip trailing newline from the last line... handled by caller
	overflow := false
	if wrapCols <= 0 {
		if maxLines > 0 && len(lines) > maxLines {
			lines = lines[:maxLines]
			overflow = true
		}
		return lines, overflow
	}
	wrapped := [][]rune{}
	for _, line := range lines {
		for {
			cols := wrapCols
			if len(wrapped) > 0 && wrapSignWidth > 0 && len(wrapped) > 0 {
				// subsequent wrapped lines
			}
			_ = cols
			w, _ := runesWidthLimit(line, 0, wrapCols, tabstop)
			if w >= len(line) {
				wrapped = append(wrapped, line)
				break
			}
			if w == 0 {
				w = 1
			}
			wrapped = append(wrapped, line[:w])
			line = line[w:]
			if maxLines > 0 && len(wrapped) >= maxLines {
				overflow = true
				break
			}
		}
		if overflow {
			break
		}
	}
	if maxLines > 0 && len(wrapped) > maxLines {
		wrapped = wrapped[:maxLines]
		overflow = true
	}
	return wrapped, overflow
}

// runesWidthLimit returns the number of runes that fit within limit columns and the width.
func runesWidthLimit(runes []rune, prefixWidth int, limit int, tabstop int) (int, int) {
	width := 0
	for i, r := range runes {
		w := runeWidthAt(r, prefixWidth+width, tabstop)
		if width+w > limit {
			return i, width
		}
		width += w
	}
	return len(runes), width
}

func runeWidthAt(r rune, pos int, tabstop int) int {
	if r == '\t' {
		return tabstop - pos%tabstop
	}
	return RuneWidth(r)
}

func asUint16(v int) uint16 {
	if v < 0 {
		return 0
	}
	if v > 65535 {
		return 65535
	}
	return uint16(v)
}

func trimLen(s string) int {
	return len(strings.TrimSpace(s))
}
