func exactMatchNaive(caseSensitive bool, normalize bool, forward bool, boundaryCheck bool, text *Chars, pattern []rune, withPos bool) (Result, *[]int) {
	if len(pattern) == 0 {
		return Result{0, 0, 0}, nil
	}

