	return nthRevisionCounter
}

var nthRevisionCounter = 0

func (p *Pattern) iter(pfun Algo, tokens []Token, caseSensitive bool, normalize bool, forward bool, pattern []rune, withPos bool) (Offset, int, *[]int) {
	for _, part := range tokens {
