cat > result.go <<'EOF'
package main

import (
	"math"
	"sort"
	"unicode"
)

type criterion int

const (
	byScore criterion = iota
	byChunk
	byLength
	byPathname
	byBegin
	byEnd
)

var sortCriteria = []criterion{byScore, byLength}

// Result2 holds the match result with ranking points
type Result2 struct {
	item   *Item
	points [4]uint16
}

func buildResult(item *Item, offsets []Offset, score int) Result2 {
	if len(offsets) > 1 {
		sortOffsets(offsets)
	}

	result := Result2{item: item}
	numChars := item.text.Length()
	minBegin := math.MaxUint16
	minEnd := math.MaxUint16
	maxEnd := 0
	validOffsetFound := false
	for _, offset := range offsets {
		b, e := int(offset[0]), int(offset[1])
		if b < e {
			minBegin = minInt(b, minBegin)
			minEnd = minInt(e, minEnd)
			maxEnd = maxInt(e, maxEnd)
			validOffsetFound = true
		}
	}

	for idx, criterion := range sortCriteria {
		val := uint16(math.MaxUint16)
		switch criterion {
		case byScore:
			// Higher is better
			val = math.MaxUint16 - asUint16(score)
		case byChunk:
			if validOffsetFound {
				b := minBegin
				e := maxEnd
				for ; b >= 1; b-- {
					if unicode.IsSpace(item.text.Get(b - 1)) {
						break
					}
				}
				for ; e < numChars; e++ {
					if unicode.IsSpace(item.text.Get(e)) {
						break
					}
				}
				val = asUint16(e - b)
			}
		case byLength:
			val = item.TrimLength()
		case byPathname:
			if validOffsetFound {
				// lastDelim: position after the last path separator
				lastDelim := -1
				for i := numChars - 1; i >= 0; i-- {
					if item.text.Get(i) == '/' {
						lastDelim = i
						break
					}
				}
				if lastDelim >= 0 && minBegin > lastDelim {
					val = 0
				} else {
					val = 1
				}
			}
		case byBegin, byEnd:
			if validOffsetFound {
				whitePrefixLen := 0
				for idx := 0; idx < numChars; idx++ {
					r := item.text.Get(idx)
					whitePrefixLen = idx
					if idx == minBegin || !unicode.IsSpace(r) {
						break
					}
				}
				if criterion == byBegin {
					val = asUint16(minEnd - whitePrefixLen)
				} else {
					val = asUint16(maxEnd - whitePrefixLen)
				}
			}
		}
		result.points[3-idx] = val
	}

	return result
}

// Index returns ordinal index of the Item
func (result *Result2) Index() int32 {
	if result.item == nil {
		return math.MaxInt32
	}
	return result.item.Index()
