		stateNone = iota
		state256
		state24
	)
	ptr := &state.fg
	st := stateNone
	for i := 0; i < len(codes); i++ {
		num := codes[i]
		switch st {
		case stateNone:
			switch num {
			case 0:
				state.fg = colDefault
				state.bg = colDefault
				state.attr = 0
			case 1:
				state.attr = state.attr | AttrBold
			case 2:
				state.attr = state.attr | AttrDim
			case 3:
				state.attr = state.attr | AttrItalic
			case 4:
				if subs[i] == "0" {
					state.attr = state.attr &^ AttrUnderline
				} else {
					state.attr = state.attr | AttrUnderline
				}
			case 5:
				state.attr = state.attr | AttrBlink
			case 7:
				state.attr = state.attr | AttrReverse
			case 9:
				state.attr = state.attr | AttrStrikeThrough
			case 22:
				state.attr = state.attr &^ AttrBold
				state.attr = state.attr &^ AttrDim
			case 23:
				state.attr = state.attr &^ AttrItalic
			case 24:
				state.attr = state.attr &^ AttrUnderline
			case 25:
				state.attr = state.attr &^ AttrBlink
			case 27:
				state.attr = state.attr &^ AttrReverse
			case 29:
				state.attr = state.attr &^ AttrStrikeThrough
			case 39:
				state.fg = colDefault
			case 49:
				state.bg = colDefault
			default:
				if num >= 30 && num <= 37 {
					state.fg = Color(num - 30)
				} else if num >= 40 && num <= 47 {
