package main

import (
	"strconv"
	"strings"
	"unicode/utf8"
)

type ansiOffset struct {
	offset [2]int32
	color  ansiState
}

type ansiState struct {
	fg   Color
	bg   Color
	attr Attr
	lbg  Color
	url  *url
}

type url struct {
	uri    string
	params string
}

func (s *ansiState) colored() bool {
	return s.fg != colDefault || s.bg != colDefault || s.attr != 0 || s.lbg >= 0 || s.url != nil
}

func (s *ansiState) equals(t *ansiState) bool {
	if t == nil {
		return !s.colored()
	}
	return s.fg == t.fg && s.bg == t.bg && s.attr == t.attr && s.lbg == t.lbg && s.url == t.url
}

func (s *ansiState) ToString() string {
	if !s.colored() {
		return ""
	}

	ret := ""
	if s.attr&AttrBold > 0 {
		ret += "1;"
	}
	if s.attr&AttrDim > 0 {
		ret += "2;"
	}
	if s.attr&AttrItalic > 0 {
		ret += "3;"
	}
	if s.attr&AttrUnderline > 0 {
		ret += "4;"
	}
	if s.attr&AttrBlink > 0 {
		ret += "5;"
	}
	if s.attr&AttrReverse > 0 {
		ret += "7;"
	}
	if s.attr&AttrStrikeThrough > 0 {
		ret += "9;"
	}
	ret += toAnsiString(s.fg, 30) + toAnsiString(s.bg, 40)

	return "\x1b[" + strings.TrimSuffix(ret, ";") + "m"
}

func toAnsiString(color Color, offset int) string {
	col := int(color)
	ret := ""
	if col == int(colDefault) {
		ret += strconv.Itoa(offset + 9)
	} else if col >= 0 && col < 8 {
		ret += strconv.Itoa(offset + col)
	} else if col >= 8 && col < 16 {
		ret += strconv.Itoa(offset + col + 52)
	} else if col >= 16 && col < 256 {
		ret += strconv.Itoa(offset+8) + ";5;" + strconv.Itoa(col)
	} else if col >= (1 << 24) {
		r := strconv.Itoa((col >> 16) & 0xff)
		g := strconv.Itoa((col >> 8) & 0xff)
		b := strconv.Itoa(col & 0xff)
		ret += strconv.Itoa(offset+8) + ";2;" + r + ";" + g + ";" + b
	}
	return ret + ";"
}

func isCsiParam(b byte) bool {
	return b >= '0' && b <= '9' || b == ';' || b == ':' || b == '?'
}

func isCsiFinal(b byte) bool {
	return b >= 'a' && b <= 'z' || b >= 'A' && b <= 'Z' || b == '@'
}

// nextAnsiEscapeSequence returns the ANSI escape sequence and is equivalent to
// calling FindStringIndex() on the following regex:
//   \x1b[\[()\\][0-9;:?]*[a-zA-Z@]|\x1b][^\x07\x1b]*(\x07|\x1b\\)|\x1b.|[\x0e\x0f]|.\x08
func nextAnsiEscapeSequence(s string) (int, int) {
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '\x0e', '\x0f':
			return i, i + 1
		case '\x1b':
			if i+1 >= len(s) {
				continue
			}
			switch s[i+1] {
			case '[', '(', ')', '\\':
				j := i + 2
				for j < len(s) && isCsiParam(s[j]) {
					j++
				}
				if j < len(s) && isCsiFinal(s[j]) {
					return i, j + 1
				}
				// fall through to \x1b. alternative
			case ']':
				j := i + 2
				for j < len(s) && s[j] != '\x07' && s[j] != '\x1b' {
					j++
				}
				if j < len(s) {
					if s[j] == '\x07' {
						return i, j + 1
					}
					if j+1 < len(s) && s[j+1] == '\\' {
						return i, j + 2
					}
				}
			}
			// \x1b.
			if s[i+1] == '\n' {
				continue
			}
			_, size := utf8.DecodeRuneInString(s[i+1:])
			return i, i + 1 + size
		case '\x08':
			continue
		default:
			// .\x08
			r, size := utf8.DecodeRuneInString(s[i:])
			if r == '\n' {
				continue
			}
			if i+size < len(s) && s[i+size] == '\x08' {
				return i, i + size + 1
			}
			i += size - 1
		}
	}
	return -1, -1
}

func stripAnsiCodes(s string) string {
	var out strings.Builder
	for {
		b, e := nextAnsiEscapeSequence(s)
		if b < 0 {
			out.WriteString(s)
			break
		}
		out.WriteString(s[:b])
		s = s[e:]
	}
	return out.String()
}

func extractColor(str string, state *ansiState, proc func(string, *ansiState) bool) (string, *[]ansiOffset, *ansiState) {
	var offsets []ansiOffset
	var output strings.Builder

	if state != nil {
		offsets = append(offsets, ansiOffset{[2]int32{0, 0}, *state})
	}

	prevIdx := 0
	runeCount := 0
	for idx := 0; idx < len(str); {
		b, e := nextAnsiEscapeSequence(str[idx:])
		if b < 0 {
			break
		}
		start := idx + b
		end := idx + e
		idx = end

		// Non-ANSI sequence: keep
		prev := str[prevIdx:start]
		output.WriteString(prev)
		if proc != nil && !proc(prev, state) {
			return "", nil, nil
		}
		prevIdx = end

		newLen := runeCount + utf8.RuneCountInString(prev)
		if newLen > runeCount {
			if state != nil && state.colored() {
				// Append offset
				if len(offsets) > 0 && offsets[len(offsets)-1].color.equals(state) &&
					int(offsets[len(offsets)-1].offset[1]) == runeCount {
					offsets[len(offsets)-1].offset[1] = int32(newLen)
				} else {
					offsets = append(offsets, ansiOffset{[2]int32{int32(runeCount), int32(newLen)}, *state})
				}
			}
			runeCount = newLen
		}

		seq := str[start:end]
		if len(seq) >= 3 && seq[0] == '\x1b' && seq[1] == '[' && seq[len(seq)-1] == 'm' {
			newState := interpretCode(seq, state)
			if state == nil || !newState.equals(state) {
				// Only create a copy when necessary
				st := newState
				state = &st
			}
		} else if seq == "\x1b[K" || (len(seq) > 3 && seq[0] == '\x1b' && seq[1] == '[' && seq[len(seq)-1] == 'K') {
			// Erase in line: line background
			if state != nil && state.bg >= 0 {
				st := *state
				st.lbg = state.bg
				state = &st
			}
		} else if strings.HasPrefix(seq, "\x1b]8;") {
			// Hyperlink
			newState := interpretHyperlink(seq, state)
			if state == nil || !newState.equals(state) {
				st := newState
				state = &st
			}
		}
	}

	var rest string
	var trimmed string

	if prevIdx == 0 {
		// No ANSI code found
		rest = str
		trimmed = str
	} else {
		rest = str[prevIdx:]
		output.WriteString(rest)
		trimmed = output.String()
	}
	if len(rest) > 0 && state != nil && state.colored() {
		// Update last offset
		newLen := runeCount + utf8.RuneCountInString(rest)
		if len(offsets) > 0 && offsets[len(offsets)-1].color.equals(state) &&
			int(offsets[len(offsets)-1].offset[1]) == runeCount {
			offsets[len(offsets)-1].offset[1] = int32(newLen)
		} else {
			offsets = append(offsets, ansiOffset{[2]int32{int32(runeCount), int32(newLen)}, *state})
		}
	}
	if proc != nil {
		proc(rest, state)
	}
	if len(offsets) == 0 {
		return trimmed, nil, state
	}
	return trimmed, &offsets, state
}

func interpretHyperlink(seq string, prevState *ansiState) ansiState {
	var state ansiState
	if prevState == nil {
		state = ansiState{colDefault, colDefault, 0, -1, nil}
	} else {
		state = *prevState
	}
	// \x1b]8;params;uri\x07 or \x1b]8;params;uri\x1b\\
	body := seq[4:]
	if strings.HasSuffix(body, "\x07") {
		body = body[:len(body)-1]
	} else if strings.HasSuffix(body, "\x1b\\") {
		body = body[:len(body)-2]
	}
	sep := strings.IndexByte(body, ';')
	if sep < 0 {
		return state
	}
	params := body[:sep]
	uri := body[sep+1:]
	if len(uri) == 0 {
		state.url = nil
	} else {
		state.url = &url{uri: uri, params: params}
	}
	return state
}

func interpretCode(seq string, prevState *ansiState) ansiState {
	var state ansiState
	if prevState == nil {
		state = ansiState{colDefault, colDefault, 0, -1, nil}
	} else {
		state = *prevState
	}
	if len(seq) <= 3 { // \x1b[m
		state.fg = colDefault
		state.bg = colDefault
		state.attr = 0
		return state
	}

	// Parse codes
	body := seq[2 : len(seq)-1]
	parts := strings.Split(body, ";")
	codes := make([]int, 0, len(parts))
	subs := make([]string, 0, len(parts))
	for _, p := range parts {
		sub := ""
		if ci := strings.IndexByte(p, ':'); ci >= 0 {
			sub = p[ci+1:]
			p = p[:ci]
		}
		if p == "" {
			codes = append(codes, 0)
			subs = append(subs, sub)
			continue
		}
		n, err := strconv.Atoi(p)
		if err != nil {
			// unknown: ignore the whole sequence
			return state
		}
		codes = append(codes, n)
		subs = append(subs, sub)
	}

	const (
		stateNone = iota
		state256
		state24
	)
	ptr := &state.fg
	st := stateNone
	for i := 0; i < len(codes); i++ {
		num := codes[i]
		switch st {
		case stateNone:
			switch num {
			case 0:
				state.fg = colDefault
				state.bg = colDefault
				state.attr = 0
			case 1:
				state.attr = state.attr | AttrBold
			case 2:
				state.attr = state.attr | AttrDim
			case 3:
				state.attr = state.attr | AttrItalic
			case 4:
				if subs[i] == "0" {
					state.attr = state.attr &^ AttrUnderline
				} else {
					state.attr = state.attr | AttrUnderline
				}
			case 5:
				state.attr = state.attr | AttrBlink
			case 7:
				state.attr = state.attr | AttrReverse
			case 9:
				state.attr = state.attr | AttrStrikeThrough
			case 22:
				state.attr = state.attr &^ AttrBold
				state.attr = state.attr &^ AttrDim
			case 23:
				state.attr = state.attr &^ AttrItalic
			case 24:
				state.attr = state.attr &^ AttrUnderline
			case 25:
				state.attr = state.attr &^ AttrBlink
			case 27:
				state.attr = state.attr &^ AttrReverse
			case 29:
				state.attr = state.attr &^ AttrStrikeThrough
			case 39:
				state.fg = colDefault
			case 49:
				state.bg = colDefault
			default:
				if num >= 30 && num <= 37 {
					state.fg = Color(num - 30)
				} else if num >= 40 && num <= 47 {
					state.bg = Color(num - 40)
				} else if num >= 90 && num <= 97 {
					state.fg = Color(num - 90 + 8)
				} else if num >= 100 && num <= 107 {
					state.bg = Color(num - 100 + 8)
				} else if num == 38 || num == 48 {
					if num == 38 {
						ptr = &state.fg
					} else {
						ptr = &state.bg
					}
					if subs[i] != "" {
						// colon-separated form: 38:5:n or 38:2:r:g:b
						sp := strings.Split(subs[i], ":")
						if len(sp) >= 2 && sp[0] == "5" {
							if n, err := strconv.Atoi(sp[1]); err == nil {
								*ptr = Color(n)
							}
						} else if len(sp) >= 4 && sp[0] == "2" {
							r, e1 := strconv.Atoi(sp[len(sp)-3])
							g, e2 := strconv.Atoi(sp[len(sp)-2])
							b, e3 := strconv.Atoi(sp[len(sp)-1])
							if e1 == nil && e2 == nil && e3 == nil {
								*ptr = Color((1 << 24) | (r << 16) | (g << 8) | b)
							}
						}
					} else if i+1 < len(codes) {
						i++
						switch codes[i] {
						case 5:
							st = state256
						case 2:
							st = state24
						}
					}
				}
			}
		case state256:
			*ptr = Color(num)
			st = stateNone
		case state24:
			if i+2 < len(codes) {
				r, g, b := codes[i], codes[i+1], codes[i+2]
				*ptr = Color((1 << 24) | (r << 16) | (g << 8) | b)
				i += 2
			}
			st = stateNone
		}
	}
	return state
}
