	"strconv"
	"strings"
)

var nthTemplateRegex = regexp.MustCompile(`\{(-?[0-9]+(\.\.(-?[0-9]+)?)?|\.\.(-?[0-9]+)?|n)\}`)
var nthRangeRegex = regexp.MustCompile("^[0-9,-.]+$")

type nthPart struct {
	literal string
	ranges  []Range
	index   bool
}

// parseNthTemplate parses --with-nth / --accept-nth expressions.
// Returns a function that given a delimiter returns a transformer.
func parseNthTemplate(str string) (func(Delimiter) func([]Token, int32) string, error) {
	if nthRangeRegex.MatchString(str) {
		ranges, err := splitNth(str)
		if err != nil {
			return nil, err
		}
		return func(delimiter Delimiter) func([]Token, int32) string {
			return func(tokens []Token, index int32) string {
				trans := Transform(tokens, ranges)
				return stripTrailingDelimiter(joinTokens(trans), delimiter)
			}
		}, nil
	}

	locs := nthTemplateRegex.FindAllStringIndex(str, -1)
	if len(locs) == 0 {
		return nil, errors.New("template should include at least 1 placeholder: " + str)
	}
	parts := []nthPart{}
	prev := 0
	for _, loc := range locs {
		if loc[0] > prev {
			parts = append(parts, nthPart{literal: str[prev:loc[0]]})
		}
		expr := str[loc[0]+1 : loc[1]-1]
		if expr == "n" {
			parts = append(parts, nthPart{index: true})
		} else {
