		}
		prev = loc[1]
	}
	if prev < len(str) {
		parts = append(parts, nthPart{literal: str[prev:]})
	}
	return func(delimiter Delimiter) func([]Token, int32) string {
		return func(tokens []Token, index int32) string {
			var sb strings.Builder
			for _, part := range parts {
				if part.index {
					sb.WriteString(strconv.Itoa(int(index)))
				} else if part.ranges != nil {
					trans := Transform(tokens, part.ranges)
					sb.WriteString(stripTrailingDelimiter(joinTokens(trans), delimiter))
				} else {
					sb.WriteString(part.literal)
				}
			}
			return sb.String()
		}
	}, nil
