package main

import (
	"sort"
	"unicode/utf8"
)

// eastAsianAmbiguousDouble makes ambiguous-width characters 2 columns wide (--ambidouble)
var eastAsianAmbiguousDouble = false

func lookupWidth(r rune) (int, int) {
	if r < 0 || r > 0x10FFFF {
		return 0, 0
	}
	t := widthRanges
	i := sort.Search(len(t), func(i int) bool { return t[i][1] >= int32(r) })
	if i < len(t) && t[i][0] <= int32(r) && int32(r) <= t[i][1] {
		return int(t[i][2]), int(t[i][3])
	}
	return 1, 1
}

// RuneWidth returns the number of terminal cells for the rune
func RuneWidth(r rune) int {
	if r < 0x20 {
		return 0
	}
	if r < 0x7F {
		return 1
	}
	w1, w2 := lookupWidth(r)
	if eastAsianAmbiguousDouble {
		return w2
	}
	return w1
}

func graphemeProperty(r rune) int {
	t := graphemeRanges
	i := sort.Search(len(t), func(i int) bool { return t[i][1] >= int32(r) })
	if i < len(t) && t[i][0] <= int32(r) && int32(r) <= t[i][1] {
		return int(t[i][2])
	}
	return gpAny
}

// graphemeBoundary determines whether there's a grapheme cluster boundary
// between the previous runes (tracked in state) and r.
type graphemeState struct {
	prevProp   int
	riCount    int
	inExtPict  bool // ExtPict (Extend)* seen, ZWJ may follow
	afterZWJ   bool // ExtPict Extend* ZWJ seen
	started    bool
}

func (s *graphemeState) next(r rune) bool {
	prop := graphemeProperty(r)
	if !s.started {
		s.started = true
		s.update(prop)
		return true
	}
	prev := s.prevProp
	boundary := true
	switch {
	case prev == gpCR && prop == gpLF:
		boundary = false // GB3
	case prev == gpControl || prev == gpCR || prev == gpLF:
		boundary = true // GB4
	case prop == gpControl || prop == gpCR || prop == gpLF:
		boundary = true // GB5
	case prev == gpL && (prop == gpL || prop == gpV || prop == gpLV || prop == gpLVT):
		boundary = false // GB6
	case (prev == gpLV || prev == gpV) && (prop == gpV || prop == gpT):
		boundary = false // GB7
	case (prev == gpLVT || prev == gpT) && prop == gpT:
		boundary = false // GB8
	case prop == gpExtend || prop == gpZWJ:
		boundary = false // GB9
	case prop == gpSpacingMark:
		boundary = false // GB9a
	case prev == gpPrepend:
		boundary = false // GB9b
	case s.afterZWJ && prop == gpExtendedPictographic:
		boundary = false // GB11
	case prev == gpRegionalIndicator && prop == gpRegionalIndicator && s.riCount%2 == 1:
		boundary = false // GB12/13
	}
	s.update(prop)
	return boundary
}

func (s *graphemeState) update(prop int) {
	// Track GB11 state
	if prop == gpExtendedPictographic {
		s.inExtPict = true
		s.afterZWJ = false
	} else if s.inExtPict && prop == gpExtend {
		// stay
		s.afterZWJ = false
	} else if s.inExtPict && prop == gpZWJ {
		s.afterZWJ = true
		s.inExtPict = false
	} else {
		s.inExtPict = false
		s.afterZWJ = false
	}
	if prop == gpRegionalIndicator {
		s.riCount++
	} else {
		s.riCount = 0
	}
	s.prevProp = prop
}

// Graphemes splits the string into grapheme clusters
func Graphemes(s string) []string {
	clusters := []string{}
	st := graphemeState{}
	start := 0
	for i, r := range s {
		if st.next(r) && i > 0 {
			clusters = append(clusters, s[start:i])
			start = i
		}
	}
	if start < len(s) {
		clusters = append(clusters, s[start:])
	}
	return clusters
}

// GraphemesRunes splits runes into grapheme clusters (as index boundaries)
func graphemeClusterRunes(runes []rune) [][]rune {
	clusters := [][]rune{}
	st := graphemeState{}
	start := 0
	for i, r := range runes {
		if st.next(r) && i > 0 {
			clusters = append(clusters, runes[start:i])
			start = i
		}
	}
	if start < len(runes) {
		clusters = append(clusters, runes[start:])
	}
	return clusters
}

func clusterWidth(rs []rune) int {
	for _, r := range rs {
		w := RuneWidth(r)
		if w > 0 {
			return w
		}
	}
	return 0
}

// StringWidth returns the display width of the string
func StringWidth(s string) int {
	if len(s) == 1 {
		b := s[0]
		if b < 0x20 || b == 0x7F {
			return 0
		}
		return 1
	}
	ascii := true
	for i := 0; i < len(s); i++ {
		if s[i] >= 0x80 {
			ascii = false
			break
		}
	}
	if ascii {
		w := 0
		for i := 0; i < len(s); i++ {
			b := s[i]
			if b >= 0x20 && b != 0x7F {
				w++
			}
		}
		return w
	}
	if utf8.RuneCountInString(s) == 1 {
		r, _ := utf8.DecodeRuneInString(s)
		return RuneWidth(r)
	}
	width := 0
	for _, g := range graphemeClusterRunes([]rune(s)) {
		width += clusterWidth(g)
	}
	return width
}

// RunesWidth returns the display width of the runes, taking tabs into account.
// If the width exceeds limit, returns the width and the index of the rune where it overflowed.
func RunesWidth(runes []rune, prefixWidth int, tabstop int, limit int) (int, int) {
	width := 0
	idx := 0
	for _, g := range graphemeClusterRunes(runes) {
		var w int
		if len(g) == 1 && g[0] == '\t' {
			w = tabstop - (prefixWidth+width)%tabstop
		} else {
			w = clusterWidth(g)
		}
		width += w
		if width > limit {
			return width, idx
		}
		idx += len(g)
	}
	return width, -1
}

// Truncate returns the runes that fit within the given width
func Truncate(input string, limit int) ([]rune, int) {
	runes := []rune{}
	width := 0
	for _, g := range graphemeClusterRunes([]rune(input)) {
		w := clusterWidth(g)
		if width+w > limit {
			return runes, width
		}
		width += w
		runes = append(runes, g...)
	}
	return runes, width
}
