		if st.next(r) && i > 0 {
			clusters = append(clusters, s[start:i])
			start = i
		}
	}
	if start < len(s) {
		clusters = append(clusters, s[start:])
	}
	return clusters
}

// GraphemesRunes splits runes into grapheme clusters (as index boundaries)
func graphemeClusterRunes(runes []rune) [][]rune {
	clusters := [][]rune{}
	st := graphemeState{}
	start := 0
	for i, r := range runes {
		if st.next(r) && i > 0 {
			clusters = append(clusters, runes[start:i])
			start = i
		}
	}
	if start < len(runes) {
		clusters = append(clusters, runes[start:])
	}
	return clusters
}

func clusterWidth(rs []rune) int {
	for _, r := range rs {
		w := RuneWidth(r)
		if w > 0 {
			return w
		}
	}
	return 0
}

// StringWidth returns the display width of the string
func StringWidth(s string) int {
	if len(s) == 1 {
		b := s[0]
		if b < 0x20 || b == 0x7F {
			return 0
		}
		return 1
	}
	ascii := true
	for i := 0; i < len(s); i++ {
		if s[i] >= 0x80 {
			ascii = false
			break
		}
	}
	if ascii {
		w := 0
		for i := 0; i < len(s); i++ {
			b := s[i]
			if b >= 0x20 && b != 0x7F {
				w++
			}
		}
		return w
	}
	if utf8.RuneCountInString(s) == 1 {
		r, _ := utf8.DecodeRuneInString(s)
		return RuneWidth(r)
	}
	width := 0
	for _, g := range graphemeClusterRunes([]rune(s)) {
		width += clusterWidth(g)
	}
	return width
}

// RunesWidth returns the display width of the runes, taking tabs into account.
// If the width exceeds limit, returns the width and the index of the rune where it overflowed.
func RunesWidth(runes []rune, prefixWidth int, tabstop int, limit int) (int, int) {
	width := 0
	idx := 0
	for _, g := range graphemeClusterRunes(runes) {
		var w int
		if len(g) == 1 && g[0] == '\t' {
			w = tabstop - (prefixWidth+width)%tabstop
		} else {
			w = clusterWidth(g)
		}
		width += w
		if width > limit {
			return width, idx
		}
		idx += len(g)
	}
	return width, -1
}

// Truncate returns the runes that fit within the given width
func Truncate(input string, limit int) ([]rune, int) {
	runes := []rune{}
	width := 0
	for _, g := range graphemeClusterRunes([]rune(input)) {
		w := clusterWidth(g)
		if width+w > limit {
			return runes, width
		}
		width += w
		runes = append(runes, g...)
	}
	return runes, width
}
