package main

import (
	"sync"
)

// ItemBuilder transforms raw input into an Item
type ItemBuilder func(*Item, []byte) bool

// ChunkList holds all items
type ChunkList struct {
	items    []*Item
	count    int
	mutex    sync.Mutex
	trans    ItemBuilder
	tail     int
	revision int
}

func NewChunkList(trans ItemBuilder) *ChunkList {
	return &ChunkList{
		items: []*Item{},
		count: 0,
		trans: trans}
}

// Push adds the item to the list
func (cl *ChunkList) Push(data []byte) bool {
	cl.mutex.Lock()
	defer cl.mutex.Unlock()
	item := &Item{}
	if cl.trans(item, data) {
		cl.items = append(cl.items, item)
		cl.count++
		return true
	}
	return false
}

// Clear clears the list
func (cl *ChunkList) Clear() {
	cl.mutex.Lock()
	cl.items = []*Item{}
	cl.count = 0
	cl.mutex.Unlock()
}

// Snapshot returns the copied slice of items
func (cl *ChunkList) Snapshot(tail int) ([]*Item, int, bool) {
	cl.mutex.Lock()
	defer cl.mutex.Unlock()
	changed := false
	if tail > 0 && cl.count > tail {
		cl.items = cl.items[len(cl.items)-tail:]
		cl.count = len(cl.items)
		changed = true
	}
	ret := make([]*Item, len(cl.items))
	copy(ret, cl.items)
	return ret, cl.count, changed
}

// Count returns the number of items
func (cl *ChunkList) Count() int {
	cl.mutex.Lock()
	defer cl.mutex.Unlock()
	return cl.count
}
