	return &Merger{results: []Result2{}, revision: revision}
}

// PassMerger returns a merger that passes all items
func PassMerger(items []*Item, tac bool, revision int) *Merger {
	mg := Merger{results: make([]Result2, 0, len(items)), tac: tac, pass: true, revision: revision}
	for _, item := range items {
		mg.results = append(mg.results, Result2{item: item})
	}
	mg.count = len(items)
	return &mg
}

func NewMerger(results []Result2, sorted bool, tac bool, revision int) *Merger {
	mg := Merger{results: results, tac: tac, revision: revision}
	mg.count = len(results)
	if sorted {
		sortResults(results, tac)
	} else if tac {
		// Reverse
		for i, j := 0, len(results)-1; i < j; i, j = i+1, j-1 {
			results[i], results[j] = results[j], results[i]
		}
	}
	return &mg
}

