package main

import (
	_ "embed"
	"fmt"
	"os"
	"os/exec"
	"strings"
)

const version = "0.68.0"
const revision = "89eaa04a"

//go:embed assets/help.txt
var helpText string

//go:embed assets/fzf.1
var manPage string

//go:embed assets/key-bindings.bash
var bashScript string

//go:embed assets/key-bindings.zsh
var zshScript string

//go:embed assets/key-bindings.fish
var fishScript string

func printHelp() {
	fmt.Print(helpText)
}

func printVersion() {
	fmt.Printf("%s (%s)\n", version, revision)
}

func printMan() {
	// Try to run man with a temporary file
	if _, err := exec.LookPath("man"); err == nil {
		f, err := os.CreateTemp("", "fzf-temp-*")
		if err == nil {
			f.WriteString(manPage + "\n")
			f.Close()
			defer os.Remove(f.Name())
			cmd := exec.Command("man", f.Name())
			cmd.Stdin = os.Stdin
			cmd.Stdout = os.Stdout
			cmd.Stderr = os.Stderr
			if err := cmd.Run(); err == nil {
				return
			}
		}
	}
	fmt.Print(manPage)
}

func parseAllOptions() (*Options, error) {
	opts := defaultOptions()

	// 1. Options file
	if optsFile := os.Getenv("FZF_DEFAULT_OPTS_FILE"); len(optsFile) > 0 {
		bytes, err := os.ReadFile(optsFile)
		if err != nil {
			return nil, fmt.Errorf("$FZF_DEFAULT_OPTS_FILE: %s", err.Error())
		}
		words, err := shellWords(string(bytes))
		if err != nil {
			return nil, fmt.Errorf("%s: %s", optsFile, err.Error())
		}
		if err := parseOptions(opts, words); err != nil {
			return nil, fmt.Errorf("%s: %s", optsFile, err.Error())
		}
	}

	// 2. FZF_DEFAULT_OPTS
	words, err := shellWords(os.Getenv("FZF_DEFAULT_OPTS"))
	if err != nil {
		return nil, fmt.Errorf("$FZF_DEFAULT_OPTS: %s", err.Error())
	}
	if len(words) > 0 {
		if err := parseOptions(opts, words); err != nil {
			return nil, fmt.Errorf("$FZF_DEFAULT_OPTS: %s", err.Error())
		}
	}

	// 3. Command-line arguments
	if err := parseOptions(opts, os.Args[1:]); err != nil {
		return nil, err
	}

	if err := postProcessOptions(opts); err != nil {
		return nil, err
	}
	return opts, nil
}

func main() {
	opts, err := parseAllOptions()
	if err != nil {
		os.Stderr.WriteString(err.Error() + "\n")
		os.Exit(exitError)
	}

	if opts.Bash {
		fmt.Print(bashScript)
		return
	}
	if opts.Zsh {
		fmt.Print(zshScript)
		return
	}
	if opts.Fish {
		fmt.Print(fishScript)
		return
	}
	if opts.Help {
		printHelp()
		return
	}
	if opts.Version {
		printVersion()
		return
	}
	if opts.Man {
		printMan()
		return
	}

	code, err := Run(opts)
	if err != nil {
		msg := err.Error()
		if len(msg) > 0 {
			os.Stderr.WriteString(msg + "\n")
		}
	}
	os.Exit(code)
}

func postProcessOptions(opts *Options) error {
	if !opts.Unicode {
		// ASCII fallbacks handled at render time
	}
	// Default actions for CTRL-N / CTRL-P when --history is set
	if opts.History != nil {
		if _, prs := opts.Keymap[CtrlP.AsEvent()]; !prs {
			opts.Keymap[CtrlP.AsEvent()] = toActions(actPrevHistory)
		}
		if _, prs := opts.Keymap[CtrlN.AsEvent()]; !prs {
			opts.Keymap[CtrlN.AsEvent()] = toActions(actNextHistory)
		}
	}

	// Extend the default key map
	keymap := defaultKeymap()
	for key, actions := range opts.Keymap {
		for _, act := range actions {
			if act.t == actToggleSort {
				opts.ToggleSort = true
			}
		}
		keymap[key] = actions
	}
	opts.Keymap = keymap

	if opts.Bold {
		// handled in theme init
	}
	if opts.Height.auto {
		for _, s := range []sizeSpec{opts.Margin[0], opts.Margin[2]} {
			if s.percent {
				return errorf("adaptive height is not compatible with top/bottom percent margin")
			}
		}
		for _, s := range []sizeSpec{opts.Padding[0], opts.Padding[2]} {
			if s.percent {
				return errorf("adaptive height is not compatible with top/bottom percent padding")
			}
		}
	}
	return nil
}

func defaultKeymap() map[Event][]*action {
	keymap := make(map[Event][]*action)
	add := func(e EventType, a ...actionType) {
		keymap[e.AsEvent()] = toActions(a...)
	}
	addEvent := func(e Event, a ...actionType) {
		keymap[e] = toActions(a...)
	}

	add(Fatal, actFatal)
	add(Invalid, actInvalid)
	add(CtrlA, actBeginningOfLine)
	add(CtrlB, actBackwardChar)
	add(CtrlC, actAbort)
	add(CtrlG, actAbort)
	add(CtrlQ, actAbort)
	add(Esc, actAbort)
	add(CtrlD, actDeleteCharEof)
	add(CtrlE, actEndOfLine)
	add(CtrlF, actForwardChar)
	add(CtrlH, actBackwardDeleteChar)
	add(Backspace, actBackwardDeleteChar)
	add(Tab, actToggleDown)
	add(ShiftTab, actToggleUp)
	add(CtrlJ, actDown)
	add(CtrlK, actUp)
	add(CtrlL, actClearScreen)
	add(CtrlN, actDownMatch)
	add(CtrlP, actUpMatch)
	add(Enter, actAccept)
	add(CtrlU, actUnixLineDiscard)
	add(CtrlW, actUnixWordRubout)
	add(CtrlY, actYank)
	add(CtrlSlash, actToggleWrap)
	addEvent(AltKey('/'), actToggleWrap)
	add(AltBackspace, actBackwardKillWord)
	add(AltUp, actUpMatch)
	add(AltDown, actDownMatch)
	addEvent(AltKey('b'), actBackwardWord)
	add(ShiftLeft, actBackwardWord)
	addEvent(AltKey('f'), actForwardWord)
	add(ShiftRight, actForwardWord)
	addEvent(AltKey('d'), actKillWord)
	add(ShiftUp, actPreviewUp)
	add(ShiftDown, actPreviewDown)

	add(Up, actUp)
	add(Down, actDown)
	add(Left, actBackwardChar)
	add(Right, actForwardChar)

	add(Home, actBeginningOfLine)
	add(End, actEndOfLine)
	add(Delete, actDeleteChar)
	add(PageUp, actPageUp)
	add(PageDown, actPageDown)

	add(Mouse, actMouse)
	add(LeftClick, actClick)
	add(RightClick, actToggle)
	add(DoubleClick, actAccept)
	add(SLeftClick, actToggle)
	add(SRightClick, actToggle)

	add(ScrollUp, actUp)
	add(ScrollDown, actDown)
	add(SScrollUp, actToggle, actUp)
	add(SScrollDown, actToggle, actDown)
	add(PreviewScrollUp, actPreviewUp)
	add(PreviewScrollDown, actPreviewDown)

	add(BracketedPasteBeginEvent(), actBracketedPasteBegin)
	add(BracketedPasteEndEvent(), actBracketedPasteEnd)
