const maxMulti = 1 << 30

func Run(opts *Options) (int, error) {
	if opts.Ambidouble {
		eastAsianAmbiguousDouble = true
	}
	if err := processScheme(opts); err != nil {
		return exitError, err
	}
	sortCriteria = opts.Criteria

	// ANSI code processor
	ansiProcessor := func(data []byte) (Chars, *[]ansiOffset) {
		return ToChars(data), nil
	}

	var lineAnsiState, prevLineAnsiState *ansiState
	if opts.Ansi {
		if opts.Theme.Colored {
			ansiProcessor = func(data []byte) (Chars, *[]ansiOffset) {
				prevLineAnsiState = lineAnsiState
				trimmed, offsets, newState := extractColor(byteString(data), lineAnsiState, nil)
				lineAnsiState = newState
				return ToChars(stringBytes(trimmed)), offsets
			}
		} else {
			// When color is disabled but ansi option is given,
			// we simply strip out ANSI codes from the input
			ansiProcessor = func(data []byte) (Chars, *[]ansiOffset) {
				trimmed, _, _ := extractColor(byteString(data), nil, nil)
				return ToChars(stringBytes(trimmed)), nil
			}
		}
	}

	// Chunk list
	var chunkList *ChunkList
	var itemIndex int32
	header := make([]string, 0, opts.HeaderLines)
	var headerMutex sync.Mutex
	headerEvent := make(chan bool, 1)
	notifyHeader := func() {
		select {
		case headerEvent <- true:
		default:
		}
	}
	if opts.WithNth == nil {
		chunkList = NewChunkList(func(item *Item, data []byte) bool {
			headerMutex.Lock()
			if len(header) < opts.HeaderLines {
				header = append(header, byteString(data))
				headerMutex.Unlock()
				notifyHeader()
				return false
			}
			headerMutex.Unlock()
			item.text, item.colors = ansiProcessor(data)
			item.text.Index = itemIndex
			itemIndex++
			return true
		})
	} else {
		nthTransformer := opts.WithNth(opts.Delimiter)
		chunkList = NewChunkList(func(item *Item, data []byte) bool {
			tokens := Tokenize(byteString(data), opts.Delimiter)
			if opts.Ansi && opts.Theme.Colored && len(tokens) > 1 {
				var ansiState *ansiState
				if prevLineAnsiState != nil {
					ansiStateDup := *prevLineAnsiState
					ansiState = &ansiStateDup
				}
				for _, token := range tokens {
					prevAnsiState := ansiState
					_, _, ansiState = extractColor(token.text.ToString(), ansiState, nil)
					if prevAnsiState != nil {
						token.text.Prepend("\x1b[m" + prevAnsiState.ToString())
					} else {
						token.text.Prepend("\x1b[m")
					}
				}
			}
			transformed := nthTransformer(tokens, itemIndex)
			headerMutex.Lock()
			if len(header) < opts.HeaderLines {
				header = append(header, transformed)
				headerMutex.Unlock()
				notifyHeader()
				return false
			}
			headerMutex.Unlock()
			item.text, item.colors = ansiProcessor(stringBytes(transformed))
			item.text.TrimTrailingWhitespaces()
			item.text.Index = itemIndex
			item.origText = &data
			itemIndex++
			return true
		})
	}

	// Pattern builder
	forward := true
	withPos := false
	for idx, cri := range opts.Criteria[1:] {
		if cri == byEnd {
			forward = false
			break
		}
		if cri == byBegin {
			withPos = true
			break
		}
		_ = idx
	}
	patternCache := make(map[string]*Pattern)
	patternBuilder := func(runes []rune) *Pattern {
		return BuildPattern(opts.Fuzzy, opts.FuzzyAlgo, opts.Extended, opts.Case, opts.Normalize, forward, withPos,
			true, opts.Nth, opts.Delimiter, runes)
	}
	_ = patternCache

	executor := NewExecutor(opts.WithShell)

	// Filtering mode
	if opts.Filter != nil {
		if opts.PrintQuery {
			opts.Printer(*opts.Filter)
		}

		pattern := patternBuilder([]rune(*opts.Filter))
		sort := opts.Sort > 0 && pattern.sortable

		found := false
		streamingFilter := !sort && !opts.Tac && !opts.Sync

		// start:reload binding
		initialCommand := ""
		if acts, ok := opts.Keymap[Start.AsEvent()]; ok {
			for _, act := range acts {
				if act.t == actReload || act.t == actReloadSync {
					initialCommand = act.a
					break
				}
			}
		}
		var initialEnv []string
		if initialCommand != "" {
			initialEnv = os.Environ()
		}

		printItem := func(item *Item) {
			if opts.AcceptNth != nil {
				opts.Printer(item.acceptNth(opts.Ansi, opts.Delimiter, opts.AcceptNth(opts.Delimiter)))
			} else {
				opts.Printer(item.AsString(opts.Ansi))
			}
		}

		if streamingFilter {
			var mutex sync.Mutex
			reader := NewReader(
				func(runes []byte) bool {
					item := Item{}
					if chunkList.trans(&item, runes) {
						mutex.Lock()
						if result, _, _ := pattern.MatchItem(&item, false); result != nil {
							printItem(&item)
							found = true
						}
						mutex.Unlock()
					}
					return false
				}, nil, executor, opts.ReadZero, false)
			reader.ReadSource(opts.Input, opts.WalkerRoot, opts.WalkerOpts, opts.WalkerSkip, initialCommand, initialEnv, nil)
		} else {
			reader := NewReader(func(data []byte) bool {
				return chunkList.Push(data)
			}, nil, executor, opts.ReadZero, true)
			reader.ReadSource(opts.Input, opts.WalkerRoot, opts.WalkerOpts, opts.WalkerSkip, initialCommand, initialEnv, nil)

			snapshot, _, _ := chunkList.Snapshot(opts.Tail)
			merger := matchItems(snapshot, pattern, sort, opts.Tac, 0)
			for i := 0; i < merger.Length(); i++ {
				printItem(merger.Get(i).item)
				found = true
			}
		}
		if found {
			return exitOk, nil
		}
		return exitNoMatch, nil
	}

	// Interactive mode
	return runInteractive(opts, chunkList, patternBuilder, executor, &header, &headerMutex, headerEvent)
}

func matchItems(items []*Item, pattern *Pattern, sort bool, tac bool, revision int) *Merger {
	if pattern.IsEmpty() {
		return PassMerger(items, tac, revision)
	}
	results := make([]Result2, 0, len(items))
	for _, item := range items {
		if result, _, _ := pattern.MatchItem(item, false); result != nil {
			results = append(results, *result)
		}
	}
	return NewMerger(results, sort && pattern.sortable, tac, revision)
}

