//go:embed assets/key-bindings.fish
var fishScript string

func printHelp() {
	fmt.Print(helpText)
}

func printVersion() {
	fmt.Printf("%s (%s)\n", version, revision)
}

func printMan() {
	// Try to run man with a temporary file
	if _, err := exec.LookPath("man"); err == nil {
		f, err := os.CreateTemp("", "fzf-temp-*")
		if err == nil {
			f.WriteString(manPage + "\n")
			f.Close()
			defer os.Remove(f.Name())
			cmd := exec.Command("man", f.Name())
			cmd.Stdin = os.Stdin
			cmd.Stdout = os.Stdout
			cmd.Stderr = os.Stderr
			if err := cmd.Run(); err == nil {
				return
			}
		}
	}
	fmt.Print(manPage)
}

func parseAllOptions() (*Options, error) {
	opts := defaultOptions()

	// 1. Options file
	if optsFile := os.Getenv("FZF_DEFAULT_OPTS_FILE"); len(optsFile) > 0 {
		bytes, err := os.ReadFile(optsFile)
		if err != nil {
			return nil, fmt.Errorf("$FZF_DEFAULT_OPTS_FILE: %s", err.Error())
		}
		words, err := shellWords(string(bytes))
		if err != nil {
			return nil, fmt.Errorf("%s: %s", optsFile, err.Error())
		}
		if err := parseOptions(opts, words); err != nil {
			return nil, fmt.Errorf("%s: %s", optsFile, err.Error())
		}
	}

	// 2. FZF_DEFAULT_OPTS
	words, err := shellWords(os.Getenv("FZF_DEFAULT_OPTS"))
	if err != nil {
		return nil, fmt.Errorf("$FZF_DEFAULT_OPTS: %s", err.Error())
	}
	if len(words) > 0 {
		if err := parseOptions(opts, words); err != nil {
			return nil, fmt.Errorf("$FZF_DEFAULT_OPTS: %s", err.Error())
		}
	}

	// 3. Command-line arguments
	if err := parseOptions(opts, os.Args[1:]); err != nil {
		return nil, err
	}

	if err := postProcessOptions(opts); err != nil {
		return nil, err
	}
	return opts, nil
}

func main() {
	opts, err := parseAllOptions()
	if err != nil {
		os.Stderr.WriteString(err.Error() + "\n")
		os.Exit(exitError)
	}

	if opts.Bash {
		fmt.Print(bashScript)
		return
	}
	if opts.Zsh {
		fmt.Print(zshScript)
		return
	}
	if opts.Fish {
		fmt.Print(fishScript)
		return
	}
	if opts.Help {
		printHelp()
		return
	}
	if opts.Version {
		printVersion()
		return
	}
	if opts.Man {
		printMan()
		return
	}

	code, err := Run(opts)
	if err != nil {
		msg := err.Error()
		if len(msg) > 0 {
			os.Stderr.WriteString(msg + "\n")
		}
	}
	os.Exit(code)
}

func postProcessOptions(opts *Options) error {
	if !opts.Unicode {
		// ASCII fallbacks handled at render time
	}
	// Default actions for CTRL-N / CTRL-P when --history is set
	if opts.History != nil {
		if _, prs := opts.Keymap[CtrlP.AsEvent()]; !prs {
			opts.Keymap[CtrlP.AsEvent()] = toActions(actPrevHistory)
		}
		if _, prs := opts.Keymap[CtrlN.AsEvent()]; !prs {
			opts.Keymap[CtrlN.AsEvent()] = toActions(actNextHistory)
		}
	}

	// Extend the default key map
	keymap := defaultKeymap()
	for key, actions := range opts.Keymap {
		for _, act := range actions {
			if act.t == actToggleSort {
				opts.ToggleSort = true
			}
		}
		keymap[key] = actions
	}
	opts.Keymap = keymap

	if opts.Bold {
		// handled in theme init
	}
	if opts.Height.auto {
		for _, s := range []sizeSpec{opts.Margin[0], opts.Margin[2]} {
