// Slab is a pre-allocated memory block reused across matches (not zeroed between uses)
type Slab struct {
	I16 []int16
	I32 []int32
}

func MakeSlab(size16 int, size32 int) *Slab {
	return &Slab{
		I16: make([]int16, size16),
		I32: make([]int32, size32)}
}

func alloc16(offset int, slab *Slab, size int) (int, []int16) {
	if slab != nil && cap(slab.I16) > offset+size {
		slab.I16 = slab.I16[:offset+size]
		return offset + size, slab.I16[offset : offset+size]
	}
	return offset, make([]int16, size)
}

func alloc32(offset int, slab *Slab, size int) (int, []int32) {
	if slab != nil && cap(slab.I32) > offset+size {
		slab.I32 = slab.I32[:offset+size]
		return offset + size, slab.I32[offset : offset+size]
	}
	return offset, make([]int32, size)
}

// asciiFuzzyIndex returns the index range where the pattern may be found (optimization)
func asciiFuzzyIndex(input *Chars, pattern []rune, caseSensitive bool) (int, int) {
	// Can't determine
	if !isAsciiChars(input) {
		return 0, input.Length()
	}

	// Not possible
	for _, r := range pattern {
		if r > unicode.MaxASCII {
			return -1, -1
		}
	}

	firstIdx, idx, lastIdx := 0, 0, 0
	var b byte
	for pidx := 0; pidx < len(pattern); pidx++ {
		b = byte(pattern[pidx])
		idx = indexByteFrom(input, idx, b, caseSensitive)
		if idx < 0 {
			return -1, -1
		}
		if pidx == 0 && idx > 0 {
			// Step back to find the right bonus point
			firstIdx = idx - 1
		}
		lastIdx = idx
		idx++
	}

	// Find the last appearance of the last character of the pattern to limit the search scope
	bu := b
	if !caseSensitive && b >= 'a' && b <= 'z' {
		bu = b - 32
	}
	scope := input.runes[lastIdx:]
	for i := len(scope) - 1; i >= 0; i-- {
		r := scope[i]
		if r == rune(b) || r == rune(bu) {
			return firstIdx, lastIdx + i + 1
		}
	}
	return firstIdx, lastIdx + 1
}

func isAsciiChars(input *Chars) bool {
	for _, r := range input.runes {
		if r > unicode.MaxASCII {
			return false
		}
	}
	return true
}

func indexByteFrom(input *Chars, from int, b byte, caseSensitive bool) int {
	bu := b
	if !caseSensitive && b >= 'a' && b <= 'z' {
		bu = b - 32
	}
	for i := from; i < len(input.runes); i++ {
		r := input.runes[i]
		if r == rune(b) || (!caseSensitive && r == rune(bu)) {
			return i
		}
	}
	return -1
}
