package main

import (
	"os"
	"syscall"
	"unsafe"
)

type ttyState struct {
	fd      int
	orig    syscall.Termios
	rawSet  bool
}

func ioctl(fd int, req uint, arg unsafe.Pointer) error {
	_, _, e := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), uintptr(req), uintptr(arg))
	if e != 0 {
		return e
	}
	return nil
}

func getTermios(fd int) (syscall.Termios, error) {
	var t syscall.Termios
	err := ioctl(fd, syscall.TCGETS, unsafe.Pointer(&t))
	return t, err
}

func setTermios(fd int, t *syscall.Termios) error {
	return ioctl(fd, syscall.TCSETS, unsafe.Pointer(t))
}

func (s *ttyState) makeRaw() error {
	orig, err := getTermios(s.fd)
	if err != nil {
		return err
	}
	s.orig = orig
	raw := orig
	raw.Iflag &^= syscall.IGNBRK | syscall.BRKINT | syscall.PARMRK | syscall.ISTRIP | syscall.INLCR | syscall.IGNCR | syscall.ICRNL | syscall.IXON
	raw.Lflag &^= syscall.ECHO | syscall.ECHONL | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
	raw.Cflag &^= syscall.CSIZE | syscall.PARENB
	raw.Cflag |= syscall.CS8
	raw.Cc[syscall.VMIN] = 1
	raw.Cc[syscall.VTIME] = 0
	if err := setTermios(s.fd, &raw); err != nil {
		return err
	}
	s.rawSet = true
	return nil
}

func (s *ttyState) restore() {
	if s.rawSet {
		setTermios(s.fd, &s.orig)
		s.rawSet = false
	}
}

type winsize struct {
	Row    uint16
	Col    uint16
	Xpixel uint16
	Ypixel uint16
}

func getWinSize(fd int) (int, int, error) {
	var ws winsize
	if err := ioctl(fd, syscall.TIOCGWINSZ, unsafe.Pointer(&ws)); err != nil {
		return 0, 0, err
	}
	return int(ws.Col), int(ws.Row), nil
}

// openTty opens the terminal device for both reading and writing
func openTty(ttyDefault string) (*os.File, error) {
	if ttyDefault != "" {
		f, err := os.OpenFile(ttyDefault, os.O_RDWR, 0)
		if err == nil {
			return f, nil
		}
	}
	// Fall back to stderr/stdin if they are terminals
	for _, f := range []*os.File{os.Stderr, os.Stdin, os.Stdout} {
		if IsTty(f) {
			return f, nil
		}
	}
	return nil, errorf("failed to open %s", ttyDefault)
}
