		for x := range s.cells[y] {
			s.cells[y][x] = cell{}
		}
	}
}

// Invalidate forces a full redraw on the next flush
func (s *Screen) Invalidate() {
	for y := range s.prev {
		for x := range s.prev[y] {
			s.prev[y][x] = cell{set: true, r: -1}
		}
	}
}

func (s *Screen) Put(y, x int, r rune, w int, pair ColorPair) {
	if y < 0 || y >= s.height || x < 0 || x >= s.width {
		return
	}
	// Clear a wide char that would be split
	if s.cells[y][x].cont && x > 0 {
		s.cells[y][x-1] = cell{r: ' ', w: 1, pair: s.cells[y][x-1].pair, set: true}
	}
	if w == 2 && x+1 >= s.width {
		// Doesn't fit
		s.cells[y][x] = cell{r: ' ', w: 1, pair: pair, set: true}
		return
	}
	if s.cells[y][x].w == 2 && x+1 < s.width {
		s.cells[y][x+1] = cell{r: ' ', w: 1, pair: s.cells[y][x+1].pair, set: true}
	}
	s.cells[y][x] = cell{r: r, w: w, pair: pair, set: true}
	if w == 2 && x+1 < s.width {
		s.cells[y][x+1] = cell{r: 0, w: 0, pair: pair, cont: true, set: true}
	}
}

func (s *Screen) write(str string) {
	s.buf.WriteString(str)
}

func (s *Screen) csi(code string) {
	s.buf.WriteString("\x1b[" + code)
}

func (s *Screen) flushBuf() {
	if s.buf.Len() > 0 {
		s.tty.Write(s.buf.Bytes())
		s.buf.Reset()
	}
}

func (s *Screen) moveTo(y, x int) {
	if s.fullscreen || s.yoffset >= 0 {
		s.csi(fmt.Sprintf("%d;%dH", s.yoffset+y+1, x+1))
	} else {
		// Relative positioning from the saved cursor position (top of the region)
		s.csi("u")
		if y > 0 {
			s.csi(fmt.Sprintf("%dB", y))
		}
		s.csi(fmt.Sprintf("%dG", x+1))
	}
}

func colorCode(c Color, fg bool, maxColors int) string {
	if c == colDefault || c == colUndefined {
		if fg {
			return "39"
		}
		return "49"
	}
	if c.is24() {
		r := (int(c) >> 16) & 0xff
		g := (int(c) >> 8) & 0xff
		b := int(c) & 0xff
		if fg {
			return fmt.Sprintf("38;2;%d;%d;%d", r, g, b)
		}
		return fmt.Sprintf("48;2;%d;%d;%d", r, g, b)
	}
	if c < 8 {
		if fg {
			return strconv.Itoa(30 + int(c))
		}
		return strconv.Itoa(40 + int(c))
	}
	if c < 16 {
		if fg {
			return strconv.Itoa(90 + int(c) - 8)
		}
		return strconv.Itoa(100 + int(c) - 8)
	}
	if fg {
		return "38;5;" + strconv.Itoa(int(c))
	}
	return "48;5;" + strconv.Itoa(int(c))
}

func (s *Screen) sgr(pair ColorPair) string {
	var sb strings.Builder
	sb.WriteString("\x1b[0")
	attr := pair.attr
	if attr&AttrBold > 0 {
		sb.WriteString(";1")
	}
	if attr&AttrDim > 0 {
		sb.WriteString(";2")
	}
	if attr&AttrItalic > 0 {
		sb.WriteString(";3")
	}
	if attr&AttrUnderline > 0 {
		sb.WriteString(";4")
	}
	if attr&AttrBlink > 0 {
		sb.WriteString(";5")
	}
	if attr&AttrReverse > 0 {
		sb.WriteString(";7")
	}
	if attr&AttrStrikeThrough > 0 {
		sb.WriteString(";9")
	}
	fg := pair.fg
	bg := pair.bg
	if fg != colDefault && fg != colUndefined {
		sb.WriteString(";" + colorCode(fg, true, s.maxColors))
	}
	if bg != colDefault && bg != colUndefined {
		sb.WriteString(";" + colorCode(bg, false, s.maxColors))
	}
	sb.WriteString("m")
	return sb.String()
}

func samePair(a, b ColorPair) bool {
	return a.fg == b.fg && a.bg == b.bg && a.attr == b.attr
}

func rowChanged(a, b []cell) bool {
	for i := range a {
		if a[i] != b[i] {
			return true
		}
	}
	return false
}

// Flush writes the changed rows to the terminal
func (s *Screen) Flush(cursorY, cursorX int, showCursor bool) {
	s.csi("?25l")
	for y := 0; y < s.height; y++ {
		if !rowChanged(s.cells[y], s.prev[y]) {
			continue
		}
		s.moveTo(y, 0)
		var cur ColorPair
		curSet := false
		lastX := s.width - 1
		// Avoid writing to the very last cell of the last row to prevent scrolling
		for x := 0; x <= lastX; x++ {
			c := s.cells[y][x]
			if c.cont {
				continue
			}
			pair := c.pair
			if !c.set {
				pair = s.bgPair
			}
			if !curSet || !samePair(cur, pair) {
				s.write(s.sgr(pair))
				cur = pair
				curSet = true
			}
			if !c.set || c.r == 0 {
				s.write(" ")
			} else {
				s.write(string(c.r))
			}
		}
		s.write("\x1b[0m")
		copy(s.prev[y], s.cells[y])
	}
	if showCursor {
		s.moveTo(cursorY, cursorX)
		s.csi("?25h")
	}
	s.flushBuf()
}

// Init prepares the terminal
func (s *Screen) Init(mouse bool) {
	if s.fullscreen {
		s.csi("?1049h")
		s.csi("H")
		s.csi("2J")
		s.yoffset = 0
	} else {
		// Reserve lines
		s.csi("G")
		for i := 1; i < s.height; i++ {
			s.write("\n")
		}
		if s.height > 1 {
			s.csi(fmt.Sprintf("%dA", s.height-1))
		}
		s.csi("G")
		s.csi("s")
		s.flushBuf()
		s.yoffset = s.queryRow()
	}
	s.csi("?7l")
	if mouse {
		s.csi("?1000h")
		s.csi("?1002h")
		s.csi("?1006h")
		s.mouse = true
	}
	s.flushBuf()
	s.Invalidate()
}

// queryRow asks the terminal for the current cursor row (0-based), -1 on failure
func (s *Screen) queryRow() int {
	return -1
}

// Close restores the terminal
func (s *Screen) Close(clear bool) {
	s.csi("?25h")
	if s.mouse {
		s.csi("?1006l")
		s.csi("?1002l")
		s.csi("?1000l")
	}
	s.csi("?7h")
	s.write("\x1b[0m")
	if s.fullscreen {
		if clear {
			s.csi("?1049l")
		} else {
			s.moveTo(s.height-1, 0)
			s.write("\n")
		}
	} else {
		if clear {
			s.moveTo(0, 0)
			s.csi("J")
		} else {
			s.moveTo(s.height-1, 0)
			s.write("\n")
		}
	}
	s.flushBuf()
}

// Window is a rectangular region of the screen
type Window struct {
	screen        *Screen
	top           int
	left          int
	width         int
	height        int
	y             int
	x             int
	border        BorderStyle
	preview       bool
	bg            ColorPair
	wrapSign      string
	wrapSignWidth int
	tabstop       int
	fill          bool
}

func (s *Screen) NewWindow(top, left, width, height int, border BorderStyle, bg ColorPair, preview bool) *Window {
	w := &Window{screen: s, top: top, left: left, width: width, height: height, border: border, bg: bg, preview: preview, tabstop: 8}
	if w.width < 0 {
		w.width = 0
	}
	if w.height < 0 {
		w.height = 0
	}
	return w
}

func (w *Window) Top() int    { return w.top }
func (w *Window) Left() int   { return w.left }
func (w *Window) Width() int  { return w.width }
func (w *Window) Height() int { return w.height }
func (w *Window) Y() int      { return w.y }
func (w *Window) X() int      { return w.x }

func (w *Window) Enclose(y, x int) bool {
	return y >= w.top && y < w.top+w.height && x >= w.left && x < w.left+w.width
}

func (w *Window) Move(y, x int) {
	w.y = y
	w.x = x
}

func (w *Window) MoveAndClear(y, x int) {
	w.Move(y, x)
	for i := x; i < w.width; i++ {
		w.screen.Put(w.top+y, w.left+i, ' ', 1, w.bg)
	}
}

func (w *Window) Erase() {
	for y := 0; y < w.height; y++ {
		for x := 0; x < w.width; x++ {
			w.screen.Put(w.top+y, w.left+x, ' ', 1, w.bg)
		}
	}
	w.drawBorder()
}

func (w *Window) EraseMaybe() {
	w.Erase()
}

func (w *Window) drawBorder() {
	// Borders are drawn by the terminal using the border windows
}

func (w *Window) Print(text string) {
	w.CPrint(w.bg, text)
}

func (w *Window) effective(pair ColorPair) ColorPair {
	if pair.bg == colDefault || pair.bg == colUndefined {
		pair.bg = w.bg.bg
	}
	if pair.fg == colUndefined {
		pair.fg = w.bg.fg
	}
	return pair
}

// CPrint prints the text at the current position without wrapping
func (w *Window) CPrint(pair ColorPair, text string) {
	pair = w.effective(pair)
	for _, g := range graphemeClusterRunes([]rune(text)) {
		if w.y >= w.height {
			return
		}
		cw := clusterWidth(g)
		if len(g) == 1 && g[0] == '\t' {
			cw = w.tabstop - w.x%w.tabstop
			for i := 0; i < cw && w.x < w.width; i++ {
				w.screen.Put(w.top+w.y, w.left+w.x, ' ', 1, pair)
				w.x++
			}
			continue
		}
		if cw == 0 {
			// Combine with previous cell: append rune (approximation: ignore)
			continue
		}
		if w.x+cw > w.width {
			return
		}
		r := g[0]
		if len(g) > 1 {
			// Use the first non-zero-width rune for display; keep the full cluster if printable
			r = clusterRune(g)
		}
		w.screen.Put(w.top+w.y, w.left+w.x, r, cw, pair)
		w.x += cw
	}
}

func clusterRune(g []rune) rune {
	for _, r := range g {
		if RuneWidth(r) > 0 {
			return r
		}
	}
	return g[0]
}

type FillReturn int

const (
	FillContinue FillReturn = iota
	FillNextLine
	FillSuspend
)

// CFill prints text with wrapping within the window
func (w *Window) CFill(fg Color, bg Color, attr Attr, text string) FillReturn {
	pair := ColorPair{fg, bg, attr}
	return w.fillString(text, pair)
}

func (w *Window) Fill(text string) FillReturn {
	return w.fillString(text, w.bg)
}

func (w *Window) fillString(text string, pair ColorPair) FillReturn {
	pair = w.effective(pair)
	lines := strings.Split(text, "\n")
	for i, line := range lines {
		if i > 0 {
			w.y++
			w.x = 0
			if w.y >= w.height {
				return FillSuspend
			}
		}
		for _, g := range graphemeClusterRunes([]rune(line)) {
			cw := clusterWidth(g)
			if len(g) == 1 && g[0] == '\t' {
				cw = w.tabstop - w.x%w.tabstop
				if w.x+cw > w.width {
					w.y++
					w.x = 0
					if w.y >= w.height {
						return FillSuspend
					}
					cw = w.tabstop
				}
				for i := 0; i < cw && w.x < w.width; i++ {
					w.screen.Put(w.top+w.y, w.left+w.x, ' ', 1, pair)
					w.x++
				}
				continue
			}
			if cw == 0 {
				continue
			}
			if w.x+cw > w.width {
				w.y++
				w.x = 0
				if w.y >= w.height {
					return FillSuspend
				}
			}
			w.screen.Put(w.top+w.y, w.left+w.x, clusterRune(g), cw, pair)
			w.x += cw
		}
	}
	if w.x >= w.width {
		w.y++
		w.x = 0
		if w.y >= w.height {
			return FillSuspend
		}
		return FillNextLine
	}
	return FillContinue
}

func (w *Window) FillRow(y int, pair ColorPair) {
	for x := 0; x < w.width; x++ {
		w.screen.Put(w.top+y, w.left+x, ' ', 1, w.effective(pair))
	}
}
