func modify(base EventType, ctrl, alt, shift bool) EventType {
	type key struct{ ctrl, alt, shift bool }
	idx := 0
	switch base {
	case Up:
		idx = 0
	case Down:
		idx = 1
	case Left:
		idx = 2
	case Right:
		idx = 3
	case Home:
		idx = 4
	case End:
		idx = 5
	case Delete:
		idx = 6
	case PageUp:
		idx = 7
	case PageDown:
		idx = 8
	default:
		return base
	}
	var table []EventType
	switch key{ctrl, alt, shift} {
	case key{false, false, false}:
		return base
	case key{false, false, true}:
		table = []EventType{ShiftUp, ShiftDown, ShiftLeft, ShiftRight, ShiftHome, ShiftEnd, ShiftDelete, ShiftPageUp, ShiftPageDown}
	case key{false, true, false}:
		table = []EventType{AltUp, AltDown, AltLeft, AltRight, AltHome, AltEnd, AltDelete, AltPageUp, AltPageDown}
	case key{false, true, true}:
		table = []EventType{AltShiftUp, AltShiftDown, AltShiftLeft, AltShiftRight, AltShiftHome, AltShiftEnd, AltShiftDelete, AltShiftPageUp, AltShiftPageDown}
	case key{true, false, false}:
		table = []EventType{CtrlUp, CtrlDown, CtrlLeft, CtrlRight, CtrlHome, CtrlEnd, CtrlDelete, CtrlPageUp, CtrlPageDown}
	case key{true, false, true}:
		table = []EventType{CtrlShiftUp, CtrlShiftDown, CtrlShiftLeft, CtrlShiftRight, CtrlShiftHome, CtrlShiftEnd, CtrlShiftDelete, CtrlShiftPageUp, CtrlShiftPageDown}
	case key{true, true, false}:
		table = []EventType{CtrlAltUp, CtrlAltDown, CtrlAltLeft, CtrlAltRight, CtrlAltHome, CtrlAltEnd, CtrlAltDelete, CtrlAltPageUp, CtrlAltPageDown}
	case key{true, true, true}:
		table = []EventType{CtrlAltShiftUp, CtrlAltShiftDown, CtrlAltShiftLeft, CtrlAltShiftRight, CtrlAltShiftHome, CtrlAltShiftEnd, CtrlAltShiftDelete, CtrlAltShiftPageUp, CtrlAltShiftPageDown}
	}
	return table[idx]
}

func parseMouse(s string) Event {
	// <b;x;yM or <b;x;ym
	body := s[1 : len(s)-1]
	release := s[len(s)-1] == 'm'
	parts := strings.Split(body, ";")
	if len(parts) != 3 {
		return Event{Invalid, 0, nil}
	}
	b, _ := strconv.Atoi(parts[0])
	x, _ := strconv.Atoi(parts[1])
	y, _ := strconv.Atoi(parts[2])
	x--
	y--
	shift := b&4 > 0
	alt := b&8 > 0
	ctrl := b&16 > 0
	button := b & 3
	motion := b&32 > 0
	if b&64 > 0 {
		// scroll
		s := 1
		if button == 0 {
			s = 1 // up
		} else {
			s = -1
		}
		return Event{Mouse, 0, &MouseEvent{Y: y, X: x, S: s, Left: false, Down: false, Double: false, Ctrl: ctrl, Alt: alt, Shift: shift}}
	}
	if motion {
		return Event{Mouse, 0, &MouseEvent{Y: y, X: x, S: 0, Left: button == 0, Down: !release, Double: false, Ctrl: ctrl, Alt: alt, Shift: shift}}
	}
	if button == 3 {
		release = true
	}
	return Event{Mouse, 0, &MouseEvent{Y: y, X: x, S: 0, Left: button == 0, Down: !release, Double: false, Ctrl: ctrl, Alt: alt, Shift: shift}}
}
