			return Event{F3, 0, nil}
		case "S":
			return Event{F4, 0, nil}
		}
		return Event{Invalid, 0, nil}
	}
	// Mouse: ESC [ < b ; x ; y M/m
	if strings.HasPrefix(s, "<") {
		return parseMouse(s)
	}
	final := s[len(s)-1]
	params := s[:len(s)-1]
	parts := strings.Split(params, ";")
	num := func(i int, def int) int {
		if i < len(parts) && parts[i] != "" {
			n, err := strconv.Atoi(parts[i])
			if err == nil {
				return n
			}
		}
		return def
	}
	mod := num(1, 1)
	// modifier: 2=shift 3=alt 4=alt+shift 5=ctrl 6=ctrl+shift 7=ctrl+alt 8=ctrl+alt+shift
	shift := mod == 2 || mod == 4 || mod == 6 || mod == 8
	alt := mod == 3 || mod == 4 || mod == 7 || mod == 8
	ctrl := mod >= 5 && mod <= 8
	withMods := func(base EventType) Event {
		return Event{modify(base, ctrl, alt, shift), 0, nil}
	}
	switch final {
	case 'A':
		return withMods(Up)
	case 'B':
		return withMods(Down)
	case 'C':
		return withMods(Right)
	case 'D':
		return withMods(Left)
	case 'H':
		return withMods(Home)
	case 'F':
		return withMods(End)
	case 'Z':
		return Event{ShiftTab, 0, nil}
	case 'P':
		return Event{F1, 0, nil}
	case 'Q':
		return Event{F2, 0, nil}
	case 'R':
		return Event{F3, 0, nil}
	case 'S':
		return Event{F4, 0, nil}
	case '~', '$', '^', '@':
		code := num(0, 0)
		if final == '$' {
			shift = true
		} else if final == '^' {
			ctrl = true
		} else if final == '@' {
			ctrl, shift = true, true
		}
		switch code {
		case 1, 7:
			return withMods(Home)
		case 2:
			return Event{Insert, 0, nil}
		case 3:
			return withMods(Delete)
		case 4, 8:
			return withMods(End)
		case 5:
			return withMods(PageUp)
		case 6:
			return withMods(PageDown)
		case 11, 12, 13, 14, 15:
			return Event{EventType(int(F1) + code - 11), 0, nil}
		case 17, 18, 19, 20, 21:
			return Event{EventType(int(F6) + code - 17), 0, nil}
		case 23, 24:
			return Event{EventType(int(F11) + code - 23), 0, nil}
		case 200:
			return Event{BracketedPasteBeginEvent(), 0, nil}
		case 201:
			return Event{BracketedPasteEndEvent(), 0, nil}
		}
	case 'M':
		// X10 mouse (not supported in detail)
		return Event{Invalid, 0, nil}
	}
	return Event{Invalid, 0, nil}
}

func modify(base EventType, ctrl, alt, shift bool) EventType {
	type key struct{ ctrl, alt, shift bool }
	idx := 0
	switch base {
	case Up:
		idx = 0
	case Down:
		idx = 1
	case Left:
		idx = 2
	case Right:
		idx = 3
	case Home:
		idx = 4
	case End:
		idx = 5
	case Delete:
		idx = 6
	case PageUp:
		idx = 7
	case PageDown:
		idx = 8
	default:
		return base
	}
	var table []EventType
	switch key{ctrl, alt, shift} {
	case key{false, false, false}:
		return base
	case key{false, false, true}:
		table = []EventType{ShiftUp, ShiftDown, ShiftLeft, ShiftRight, ShiftHome, ShiftEnd, ShiftDelete, ShiftPageUp, ShiftPageDown}
	case key{false, true, false}:
		table = []EventType{AltUp, AltDown, AltLeft, AltRight, AltHome, AltEnd, AltDelete, AltPageUp, AltPageDown}
	case key{false, true, true}:
		table = []EventType{AltShiftUp, AltShiftDown, AltShiftLeft, AltShiftRight, AltShiftHome, AltShiftEnd, AltShiftDelete, AltShiftPageUp, AltShiftPageDown}
	case key{true, false, false}:
		table = []EventType{CtrlUp, CtrlDown, CtrlLeft, CtrlRight, CtrlHome, CtrlEnd, CtrlDelete, CtrlPageUp, CtrlPageDown}
	case key{true, false, true}:
		table = []EventType{CtrlShiftUp, CtrlShiftDown, CtrlShiftLeft, CtrlShiftRight, CtrlShiftHome, CtrlShiftEnd, CtrlShiftDelete, CtrlShiftPageUp, CtrlShiftPageDown}
	case key{true, true, false}:
		table = []EventType{CtrlAltUp, CtrlAltDown, CtrlAltLeft, CtrlAltRight, CtrlAltHome, CtrlAltEnd, CtrlAltDelete, CtrlAltPageUp, CtrlAltPageDown}
	case key{true, true, true}:
		table = []EventType{CtrlAltShiftUp, CtrlAltShiftDown, CtrlAltShiftLeft, CtrlAltShiftRight, CtrlAltShiftHome, CtrlAltShiftEnd, CtrlAltShiftDelete, CtrlAltShiftPageUp, CtrlAltShiftPageDown}
	}
	return table[idx]
}

func parseMouse(s string) Event {
	// <b;x;yM or <b;x;ym
	body := s[1 : len(s)-1]
	release := s[len(s)-1] == 'm'
	parts := strings.Split(body, ";")
	if len(parts) != 3 {
		return Event{Invalid, 0, nil}
	}
	b, _ := strconv.Atoi(parts[0])
	x, _ := strconv.Atoi(parts[1])
	y, _ := strconv.Atoi(parts[2])
	x--
	y--
	shift := b&4 > 0
	alt := b&8 > 0
	ctrl := b&16 > 0
	button := b & 3
	motion := b&32 > 0
	if b&64 > 0 {
		// scroll
		s := 1
		if button == 0 {
			s = 1 // up
		} else {
			s = -1
		}
		return Event{Mouse, 0, &MouseEvent{Y: y, X: x, S: s, Left: false, Down: false, Double: false, Ctrl: ctrl, Alt: alt, Shift: shift}}
	}
	if motion {
		return Event{Mouse, 0, &MouseEvent{Y: y, X: x, S: 0, Left: button == 0, Down: !release, Double: false, Ctrl: ctrl, Alt: alt, Shift: shift}}
	}
	if button == 3 {
		release = true
	}
	return Event{Mouse, 0, &MouseEvent{Y: y, X: x, S: 0, Left: button == 0, Down: !release, Double: false, Ctrl: ctrl, Alt: alt, Shift: shift}}
}
