				t.previewScrollbar = string(runes[1])
			}
		}
	}
	if opts.WrapSign == nil {
		if opts.Unicode {
			t.wrapSign = "↳ "
		} else {
			t.wrapSign = "> "
		}
	} else {
		t.wrapSign = *opts.WrapSign
	}
	t.wrapSignWidth = StringWidth(t.wrapSign)
	if opts.GapLine == nil {
		if opts.Unicode {
			t.gapLine = "┈"
		} else {
			t.gapLine = "-"
		}
	} else {
		t.gapLine = *opts.GapLine
	}
	if opts.FileWord {
		sep := regexpQuoteMeta(string(os.PathSeparator))
		t.wordRubout = fmt.Sprintf(`%s[^%s]*`, sep, sep)
		t.wordNext = fmt.Sprintf(`[^%s]*%s`, sep, sep)
	} else {
		t.wordRubout = `[^\pL\pN][\pL\pN]*`
		t.wordNext = `[\pL\pN][^\pL\pN]*|(.$)`
	}
	t.promptLen = StringWidth(t.prompt)

	// Keymap: check actions
	for key, actions := range t.keymap {
		for _, act := range actions {
			switch key.Type {
			case Start:
				t.hasStartActions = true
			case ResultEvent:
				t.hasResultActions = true
			case Focus:
				t.hasFocusActions = true
			case Load:
				t.hasLoadActions = true
			}
			_ = act
		}
	}
	return t
}

func hasPreviewAction(opts *Options) bool {
	for _, actions := range opts.Keymap {
		for _, action := range actions {
			if action.t == actPreview || action.t == actChangePreview {
				return true
			}
		}
	}
	return false
}

func reverseStringArray(input []string) []string {
	size := len(input)
	reversed := make([]string, size)
	for idx, str := range input {
		reversed[size-idx-1] = str
	}
	return reversed
}

func regexpQuoteMeta(s string) string {
	return strings.NewReplacer(`\`, `\\`, `.`, `\.`, `/`, `/`).Replace(s)
}

// Visible header lines
func (t *Terminal) visibleHeaderLines() int {
	if !t.headerVisible {
		return 0
	}
	return len(t.header0) + t.headerLines
}

func (t *Terminal) visibleHeaderLinesInList() int {
	if !t.headerVisible {
		return 0
	}
	if t.headerWindow != nil || t.headerBorderShape.Visible() {
		return 0
	}
	n := len(t.header0)
	if t.headerLinesWindow == nil && !t.headerLinesShape.Visible() {
		n += t.headerLines
	}
	return n
}

func (t *Terminal) noSeparatorLine() bool {
	return noSeparatorLine(t.infoStyle, t.separatorLen > 0)
}

func noSeparatorLine(style infoStyle, separator bool) bool {
	switch style {
	case infoInline:
		return true
	case infoHidden, infoInlineRight:
		return !separator
	}
	return false
}

// Lines used by UI elements other than the list
func (t *Terminal) extraLines() int {
	extra := 0
	if !t.inputless {
		extra++ // prompt
		if !t.noSeparatorLine() {
			extra++ // info/separator
		}
	}
	extra += t.visibleHeaderLines()
	extra += len(t.footer)
	// Section borders
	if t.listBorderShape.Visible() {
		extra += borderLines(t.listBorderShape)
	}
	if !t.inputless && t.inputBorderShape.Visible() {
		extra += borderLines(t.inputBorderShape)
	}
	if len(t.header0) > 0 && t.headerBorderShape.Visible() {
		extra += borderLines(t.headerBorderShape)
	}
	if t.headerLines > 0 && t.headerLinesShape.Visible() {
		extra += borderLines(t.headerLinesShape)
	}
	if len(t.footer) > 0 && t.footerBorderShape.Visible() {
		extra += borderLines(t.footerBorderShape)
	}
	return extra
}

func (t *Terminal) sizeSpecToInt(spec sizeSpec, base int) int {
	if spec.percent {
		return int(spec.size * float64(base) / 100.0)
	}
	return int(spec.size)
}

// Compute margins and paddings in integer
func (t *Terminal) computeMargins(screenWidth, screenHeight int) ([4]int, [4]int) {
	marginInt := [4]int{}
	paddingInt := [4]int{}
	for idx, sizeSpec := range t.margin {
		base := screenHeight
		if idx%2 == 1 {
			base = screenWidth
		}
		marginInt[idx] = t.sizeSpecToInt(sizeSpec, base)
	}
	for idx, sizeSpec := range t.padding {
		base := screenHeight
		if idx%2 == 1 {
			base = screenWidth
		}
		paddingInt[idx] = t.sizeSpecToInt(sizeSpec, base)
	}
	return marginInt, paddingInt
}

func (t *Terminal) needPreviewWindow() bool {
	return t.hasPreviewer && t.activePreviewOpts.Visible() && !t.activePreviewOpts.hidden
}

func (t *Terminal) hasPreviewWindow() bool {
	return t.pwindow != nil
}

func (t *Terminal) listWidthForItems() int {
	if t.window == nil {
		return 0
	}
	return t.window.Width() - (t.pointerLen + t.markerLen) - 1
}

// Determine the height of the terminal region for --height
func (t *Terminal) calculateHeight(termHeight int, itemCount int) int {
	if t.fullscreen {
		return termHeight
	}
	h := 0
	if t.height.percent {
		h = int(float64(termHeight) * t.height.size / 100.0)
	} else {
		h = int(t.height.size)
	}
	if t.height.inverse {
		h = termHeight - h
	}
	if t.height.auto {
		// Adaptive height: fit to the content
		content := itemCount + t.extraLines()
		marginInt, paddingInt := t.computeMargins(t.termWidth, termHeight)
		content += marginInt[0] + marginInt[2] + paddingInt[0] + paddingInt[2]
		content += borderLines(t.borderShape)
		if t.needPreviewWindow() {
			if t.activePreviewOpts.aboveOrBelow() {
				if t.activePreviewOpts.size.percent {
					newContentHeight := int(float64(content) * 100. / (100. - t.activePreviewOpts.size.size))
					content = maxInt(content+1+borderLines(t.activePreviewOpts.border), newContentHeight)
				} else {
					content += int(t.activePreviewOpts.size.size) + borderLines(t.activePreviewOpts.border)
				}
			} else {
				content = maxInt(content, 1+borderLines(t.activePreviewOpts.border))
			}
		}
		if h <= 0 || h > content {
			h = content
		}
	}
	if t.height.percent || t.height.auto {
		minHeight := t.minHeight
		if t.minHeightAdd {
			minHeight += t.extraLines() + borderLines(t.borderShape)
			marginInt, paddingInt := t.computeMargins(t.termWidth, termHeight)
			minHeight += marginInt[0] + marginInt[2] + paddingInt[0] + paddingInt[2]
			if t.needPreviewWindow() && t.activePreviewOpts.aboveOrBelow() {
				minHeight += borderLines(t.activePreviewOpts.border) + 1
			}
		}
		if h < minHeight {
			h = minHeight
		}
	}
	if h > termHeight {
		h = termHeight
	}
	if h < 1 {
		h = 1
	}
	return h
}

func (t *Terminal) sortSelected() []selectedItem {
	sels := make([]selectedItem, 0, len(t.selected))
	for _, sel := range t.selected {
		sels = append(sels, sel)
	}
	sort.Sort(byTimeOrder(sels))
	return sels
}

func (t *Terminal) currentItem() *Item {
	cnt := t.merger.Length()
	if cnt > 0 && cnt > t.cy {
		return t.merger.Get(t.cy).item
	}
	return nil
}

func (t *Terminal) currentIndex() int32 {
	if item := t.currentItem(); item != nil {
		return item.Index()
	}
	return minItem.Index()
}

func (t *Terminal) itemAsString(item *Item) string {
	if t.acceptNth != nil {
		return item.acceptNth(t.ansi, t.delimiter, t.acceptNth)
	}
	return item.AsString(t.ansi)
}

func (t *Terminal) output() bool {
	if t.printQuery {
		t.printer(string(t.input))
	}
	if len(t.expect) > 0 {
		t.printer(t.pressed)
	}
	for _, s := range t.printQueue {
		t.printer(s)
	}
	found := len(t.selected) > 0
	if !found {
		current := t.currentItem()
		if current != nil {
			t.printer(t.itemAsString(current))
			found = true
		}
	} else {
		for _, sel := range t.sortSelected() {
			t.printer(t.itemAsString(sel.item))
		}
	}
	return found
}

func (t *Terminal) setupSignals() {
	t.resizeChan = make(chan os.Signal, 1)
	signal.Notify(t.resizeChan, syscall.SIGWINCH)
	intChan := make(chan os.Signal, 1)
	signal.Notify(intChan, syscall.SIGINT, syscall.SIGTERM)
	go func() {
		<-intChan
		t.eventChan <- Event{Fatal, 0, nil}
	}()
}
