// resizeWindows computes the layout of all windows
func (t *Terminal) resizeWindows(forcePreview bool) {
	t.forcePreview = forcePreview
	screenWidth := t.screen.width
	screenHeight := t.screen.height
	marginInt, paddingInt := t.computeMargins(screenWidth, screenHeight)

	// Border takes space from the margin area
	extraMargin := [4]int{}
	if t.borderShape.HasTop() {
		extraMargin[0] = 1
	}
	if t.borderShape.HasBottom() {
		extraMargin[2] = 1
	}
	if t.borderShape.HasLeft() {
		extraMargin[3] = 2
	}
	if t.borderShape.HasRight() {
		extraMargin[1] = 2
	}
	for i := range marginInt {
		marginInt[i] += extraMargin[i]
	}

	// Adjust margins and paddings so that the area satisfies the minimum size
	adjust := func(idx1 int, idx2 int, max int, min int) {
		if max >= min {
			margin := marginInt[idx1] + marginInt[idx2] + paddingInt[idx1] + paddingInt[idx2]
			if max-margin < min && margin > 0 {
				desired := max - min
				paddingInt[idx1] = desired * paddingInt[idx1] / margin
				paddingInt[idx2] = desired * paddingInt[idx2] / margin
				marginInt[idx1] = maxInt(extraMargin[idx1], desired*marginInt[idx1]/margin)
				marginInt[idx2] = maxInt(extraMargin[idx2], desired*marginInt[idx2]/margin)
			}
		}
	}

	previewVisible := t.needPreviewWindow() || forcePreview
	minAreaWidth := minWidth
	minAreaHeight := minHeight
	if previewVisible {
		switch t.activePreviewOpts.position {
		case posUp, posDown:
			minAreaHeight *= 2
		case posLeft, posRight:
			minAreaWidth *= 2
		}
	}
	adjust(1, 3, screenWidth, minAreaWidth)
	adjust(0, 2, screenHeight, minAreaHeight)

	width := screenWidth - marginInt[1] - marginInt[3]
	height := screenHeight - marginInt[0] - marginInt[2]

	t.border = nil
	t.pborder = nil
	t.pwindow = nil
	t.listBorder = nil
	t.inputWindow = nil
	t.inputBorder = nil
	t.headerWindow = nil
	t.headerBorder = nil
	t.headerLinesWindow = nil
	t.headerLinesBorder = nil
	t.footerWindow = nil
	t.footerBorder = nil

	// Outer border window
	if t.borderShape.Visible() {
		btop := marginInt[0] - extraMargin[0]
		bleft := marginInt[3] - extraMargin[3]
		bwidth := width + extraMargin[1] + extraMargin[3]
		bheight := height + extraMargin[0] + extraMargin[2]
		t.border = t.screen.NewWindow(btop, bleft, bwidth, bheight, MakeBorderStyle(t.borderShape, t.unicode), ColBorder, false)
	}

	// Apply padding
	innerTop := marginInt[0] + paddingInt[0]
	innerLeft := marginInt[3] + paddingInt[3]
	innerWidth := width - paddingInt[1] - paddingInt[3]
	innerHeight := height - paddingInt[0] - paddingInt[2]
	if innerWidth < 1 {
		innerWidth = 1
	}
	if innerHeight < 1 {
		innerHeight = 1
	}

	// Preview window
	mainTop, mainLeft, mainWidth, mainHeight := innerTop, innerLeft, innerWidth, innerHeight
	if previewVisible {
		po := t.activePreviewOpts
		pborderShape := po.border
		createPreviewWindow := func(y int, x int, w int, h int) {
			pwidth := w
			pheight := h
			pbw := 0
			if pborderShape.HasLeft() {
				pbw += 2
			}
			if pborderShape.HasRight() {
				pbw += 2
			}
			if pborderShape == BorderLine {
				// Single separator line between the preview window and the rest
				var bstyle BorderStyle
				switch po.position {
				case posUp:
					bstyle = MakeBorderStyle(BorderBottom, t.unicode)
				case posDown:
					bstyle = MakeBorderStyle(BorderTop, t.unicode)
				case posLeft:
					bstyle = MakeBorderStyle(BorderRight, t.unicode)
				case posRight:
					bstyle = MakeBorderStyle(BorderLeft, t.unicode)
				}
				t.pborder = t.screen.NewWindow(y, x, w, h, bstyle, ColPreviewBorder, true)
				switch po.position {
				case posUp:
					pheight = h - 1
				case posDown:
					y++
					pheight = h - 1
				case posLeft:
					pwidth = w - 2
				case posRight:
					x += 2
					pwidth = w - 2
				}
			} else {
				t.pborder = t.screen.NewWindow(y, x, w, h, MakeBorderStyle(pborderShape, t.unicode), ColPreviewBorder, true)
				if pborderShape.HasTop() {
					y++
					pheight--
				}
				if pborderShape.HasBottom() {
					pheight--
				}
				if pborderShape.HasLeft() {
					x += 2
					pwidth -= 2
				}
				if pborderShape.HasRight() {
					pwidth -= 2
				}
			}
			if pwidth < 0 {
				pwidth = 0
			}
			if pheight < 0 {
				pheight = 0
			}
			t.pwindow = t.screen.NewWindow(y, x, pwidth, pheight, BorderStyle{shape: BorderNone}, ColPreview, true)
			t.pwindow.tabstop = t.tabstop
		}
		var pw, ph int
		switch po.position {
		case posUp, posDown:
			if po.size.percent {
				ph = int(float64(innerHeight) * po.size.size / 100.0)
			} else {
				ph = int(po.size.size) + borderLines(pborderShape)
				if pborderShape == BorderLine {
					ph = int(po.size.size) + 1
				}
			}
			ph = constrain(ph, 1, innerHeight-1)
			if po.position == posUp {
				createPreviewWindow(innerTop, innerLeft, innerWidth, ph)
				mainTop = innerTop + ph
			} else {
				createPreviewWindow(innerTop+innerHeight-ph, innerLeft, innerWidth, ph)
			}
			mainHeight = innerHeight - ph
		case posLeft, posRight:
			if po.size.percent {
				pw = int(float64(innerWidth) * po.size.size / 100.0)
			} else {
				pw = int(po.size.size) + borderColumns(pborderShape, 1)
				if pborderShape == BorderLine {
					pw = int(po.size.size) + 2
				}
			}
			pw = constrain(pw, 1, innerWidth-1)
			if po.position == posLeft {
				createPreviewWindow(innerTop, innerLeft, pw, innerHeight)
				mainLeft = innerLeft + pw
			} else {
				createPreviewWindow(innerTop, innerLeft+innerWidth-pw, pw, innerHeight)
			}
			mainWidth = innerWidth - pw
		}
	}

	// Main area: split into sections
	t.layoutSections(mainTop, mainLeft, mainWidth, mainHeight)
	t.screen.Clear()
}

type section struct {
	kind   string
	height int
	shape  BorderShape
}

func (t *Terminal) layoutSections(top, left, width, height int) {
	hasInput := !t.inputless
	infoLine := hasInput && !t.noSeparatorLine()
	headerLines := 0
	if t.headerVisible {
		headerLines = len(t.header0)
	}
	hlLines := 0
	if t.headerVisible {
		hlLines = t.headerLines
	}
	footerLines := len(t.footer)

	// Decide which sections have their own windows
	inputSep := hasInput && t.inputBorderShape.Visible()
	headerSep := headerLines > 0 && t.headerBorderShape.Visible()
	hlSep := hlLines > 0 && (t.headerLinesShape.Visible() || t.headerLinesBorderSet)
	footerSep := footerLines > 0 && t.footerBorderShape.Visible()
	listSep := t.listBorderShape.Visible()

	// When header lines have their own section but the normal header doesn't,
	// the header lines are still separated.
	sections := []section{}
	inputHeight := 0
	if hasInput {
		inputHeight = 1
		if infoLine {
			inputHeight++
		}
	}
	addInput := func() {
		if inputSep {
			sections = append(sections, section{"input", inputHeight + borderLines(t.inputBorderShape), t.inputBorderShape})
		}
	}
	addHeader := func() {
		if headerSep {
			sections = append(sections, section{"header", headerLines + borderLines(t.headerBorderShape), t.headerBorderShape})
		}
	}
	addHeaderLines := func() {
		if hlSep {
			sections = append(sections, section{"headerLines", hlLines + borderLines(t.headerLinesShape), t.headerLinesShape})
		}
	}
	addFooter := func() {
		if footerSep {
			sections = append(sections, section{"footer", footerLines + borderLines(t.footerBorderShape), t.footerBorderShape})
		}
	}
	// The order of sections from top to bottom
	switch t.layout {
	case layoutReverse:
		if t.headerFirst {
			addHeader()
			addInput()
		} else {
			addInput()
			addHeader()
		}
		addHeaderLines()
		sections = append(sections, section{"list", -1, t.listBorderShape})
		addFooter()
	case layoutReverseList:
		sections = append(sections, section{"list", -1, t.listBorderShape})
		addHeaderLines()
		if t.headerFirst {
			addInput()
			addHeader()
		} else {
			addHeader()
			addInput()
		}
		addFooter()
	default:
		sections = append(sections, section{"list", -1, t.listBorderShape})
		addHeaderLines()
		if t.headerFirst {
			addInput()
			addHeader()
		} else {
			addHeader()
			addInput()
		}
		addFooter()
	}

	// Compute heights
	fixed := 0
	for _, s := range sections {
		if s.height > 0 {
			fixed += s.height
		}
	}
	listHeight := height - fixed
	if listHeight < 1 {
		listHeight = 1
	}
	y := top
	for _, s := range sections {
		h := s.height
		if s.kind == "list" {
			h = listHeight
		}
		if y+h > top+height {
			h = top + height - y
		}
		if h < 0 {
			h = 0
		}
		switch s.kind {
		case "list":
			if listSep {
				t.listBorder = t.screen.NewWindow(y, left, width, h, MakeBorderStyle(t.listBorderShape, t.unicode), ColListBorder, false)
				iy, ix, iw, ih := innerRect(y, left, width, h, t.listBorderShape)
				t.window = t.screen.NewWindow(iy, ix, iw, ih, BorderStyle{shape: BorderNone}, ColList, false)
			} else {
				t.window = t.screen.NewWindow(y, left, width, h, BorderStyle{shape: BorderNone}, ColList, false)
			}
			t.window.tabstop = t.tabstop
		case "input":
			t.inputBorder = t.screen.NewWindow(y, left, width, h, MakeBorderStyle(t.inputBorderShape, t.unicode), ColInputBorder, false)
			iy, ix, iw, ih := innerRect(y, left, width, h, t.inputBorderShape)
			t.inputWindow = t.screen.NewWindow(iy, ix, iw, ih, BorderStyle{shape: BorderNone}, ColInputBg, false)
		case "header":
			t.headerBorder = t.screen.NewWindow(y, left, width, h, MakeBorderStyle(t.headerBorderShape, t.unicode), ColHeaderBorder, false)
			iy, ix, iw, ih := innerRect(y, left, width, h, t.headerBorderShape)
			t.headerWindow = t.screen.NewWindow(iy, ix, iw, ih, BorderStyle{shape: BorderNone}, ColHeaderBg, false)
		case "headerLines":
			t.headerLinesBorder = t.screen.NewWindow(y, left, width, h, MakeBorderStyle(t.headerLinesShape, t.unicode), ColHeaderBorder, false)
			iy, ix, iw, ih := innerRect(y, left, width, h, t.headerLinesShape)
			t.headerLinesWindow = t.screen.NewWindow(iy, ix, iw, ih, BorderStyle{shape: BorderNone}, ColHeaderBg, false)
		case "footer":
			t.footerBorder = t.screen.NewWindow(y, left, width, h, MakeBorderStyle(t.footerBorderShape, t.unicode), ColFooterBorder, false)
			iy, ix, iw, ih := innerRect(y, left, width, h, t.footerBorderShape)
			t.footerWindow = t.screen.NewWindow(iy, ix, iw, ih, BorderStyle{shape: BorderNone}, ColFooterBg, false)
		}
		y += h
	}
}

func innerRect(y, x, w, h int, shape BorderShape) (int, int, int, int) {
	if shape.HasTop() {
		y++
		h--
	}
	if shape.HasBottom() {
		h--
	}
	if shape.HasLeft() {
		x += 2
		w -= 2
	}
	if shape.HasRight() {
		w -= 2
	}
	if w < 0 {
		w = 0
	}
	if h < 0 {
		h = 0
	}
	return y, x, w, h
}

func constrain(val, min, max int) int {
	if val < min {
		return min
	}
	if val > max {
		return max
	}
	return val
}

// drawBorder draws the border of the window with an optional label
func (t *Terminal) drawBorder(w *Window, label labelOpts, labelColor ColorPair) {
	if w == nil || w.border.shape == BorderNone || w.border.shape == BorderUndefined {
		return
	}
	shape := w.border.shape
	style := w.border
	color := w.bg
	width := w.width
	height := w.height
	hasTop := shape.HasTop() || (shape == BorderLine && style.top != 0 && false)
	hasBottom := shape.HasBottom()
	hasLeft := shape.HasLeft()
	hasRight := shape.HasRight()
	if shape == BorderLine {
		// handled by the specific line border style assigned
		return
	}
	put := func(y, x int, r rune) {
		t.screen.Put(w.top+y, w.left+x, r, 1, color)
	}
	if hasTop {
		for x := 0; x < width; x++ {
			put(0, x, style.top)
		}
	}
	if hasBottom {
		for x := 0; x < width; x++ {
			put(height-1, x, style.bottom)
		}
	}
	if hasLeft {
		for y := 0; y < height; y++ {
			put(y, 0, style.left)
		}
	}
	if hasRight {
		for y := 0; y < height; y++ {
			put(y, width-1, style.right)
		}
	}
	if hasTop && hasLeft {
		put(0, 0, style.topLeft)
	}
	if hasTop && hasRight {
		put(0, width-1, style.topRight)
	}
	if hasBottom && hasLeft {
		put(height-1, 0, style.bottomLeft)
	}
	if hasBottom && hasRight {
		put(height-1, width-1, style.bottomRight)
	}
	// Label
	if len(label.label) > 0 {
		t.printLabel(w, label, labelColor, hasTop, hasBottom)
	}
}

func (t *Terminal) printLabel(w *Window, label labelOpts, color ColorPair, hasTop, hasBottom bool) {
	text, colors, _ := extractColor(label.label, nil, nil)
	runes := []rune(text)
	labelWidth := StringWidth(text)
	width := w.width
	var row int
	if label.bottom {
		if !hasBottom {
			return
		}
		row = w.height - 1
	} else {
		if !hasTop {
			return
		}
		row = 0
	}
	// Available width: exclude corners
	avail := width - 2
	if avail < 0 {
		avail = 0
	}
	if labelWidth > avail {
		runes, labelWidth = Truncate(text, avail)
	}
	var col int
	if label.column == 0 {
		col = 1 + (avail-labelWidth)/2
	} else if label.column > 0 {
		col = label.column
	} else {
		col = width + label.column - labelWidth + 1
	}
	if col+labelWidth > width-1 {
		col = width - 1 - labelWidth
	}
	if col < 1 {
		col = 1
	}
	x := col
	var offsets []ansiOffset
	if colors != nil {
		offsets = *colors
	}
	for i, r := range runes {
		pair := color
		for _, o := range offsets {
			if int32(i) >= o.offset[0] && int32(i) < o.offset[1] {
				pair = ansiToPair(o.color, color)
			}
		}
		rw := RuneWidth(r)
		if rw == 0 {
			continue
		}
		t.screen.Put(w.top+row, w.left+x, r, rw, pair)
		x += rw
	}
}

func ansiToPair(state ansiState, base ColorPair) ColorPair {
	fg := state.fg
	bg := state.bg
	if fg == colDefault {
		fg = base.fg
	}
	if bg == colDefault {
		bg = base.bg
	}
	return ColorPair{fg, bg, state.attr | base.attr}
}

func (t *Terminal) drawLineBorder(w *Window) {
	// For BorderLine style windows: draw single line at the appropriate side
	if w == nil || w.border.shape == BorderNone || w.border.shape == BorderUndefined {
		return
	}
	shape := w.border.shape
	style := w.border
	color := w.bg
	put := func(y, x int, r rune) {
		t.screen.Put(w.top+y, w.left+x, r, 1, color)
	}
	if shape.HasTop() {
		for x := 0; x < w.width; x++ {
			put(0, x, style.top)
		}
	}
	if shape.HasBottom() {
		for x := 0; x < w.width; x++ {
			put(w.height-1, x, style.bottom)
		}
	}
	if shape.HasLeft() {
		for y := 0; y < w.height; y++ {
			put(y, 0, style.left)
		}
	}
	if shape.HasRight() {
		for y := 0; y < w.height; y++ {
			put(y, w.width-1, style.right)
		}
	}
}

// ---- Rendering of components ----

func (t *Terminal) promptLine() int {
	// Returns the row (within t.window or inputWindow) of the prompt
	if t.inputWindow != nil {
		if t.layout == layoutReverse {
			return 0
		}
		if t.noSeparatorLine() {
			return 0
		}
		return 1
	}
	switch t.layout {
	case layoutReverse:
		return 0
	default:
		return t.window.Height() - 1
	}
}

func (t *Terminal) inputWin() *Window {
	if t.inputWindow != nil {
		return t.inputWindow
	}
	return t.window
}

func (t *Terminal) infoLine() int {
	w := t.inputWin()
	if t.inputWindow != nil {
		if t.layout == layoutReverse {
			return 1
		}
		return 0
	}
	switch t.layout {
	case layoutReverse:
		return 1
	default:
		return w.Height() - 2
	}
}

// headerArea returns the rows for the header in the main window
func (t *Terminal) headerStartLine() int {
	// Only used when header is drawn in the main list window
	switch t.layout {
	case layoutReverse:
		line := 0
		if !t.inputless && t.inputWindow == nil {
			line = 1
			if !t.noSeparatorLine() {
				line = 2
			}
		}
		if t.headerFirst && !t.inputless && t.inputWindow == nil {
			return 0
		}
		return line
	default:
		// From the bottom: prompt, info, then header
		line := t.window.Height()
		if !t.inputless && t.inputWindow == nil {
			line--
			if !t.noSeparatorLine() {
				line--
			}
		}
		return line - t.visibleHeaderLinesInList()
	}
}

func (t *Terminal) maxItems() int {
	if t.window == nil {
		return 0
	}
	max := t.window.Height()
	if t.inputWindow == nil && !t.inputless {
		max--
		if !t.noSeparatorLine() {
			max--
		}
	}
	max -= t.visibleHeaderLinesInList()
	if t.footerWindow == nil && len(t.footer) > 0 {
		max -= len(t.footer)
	}
	if max < 0 {
		return 0
	}
	return max
}

func (t *Terminal) listStartLine() int {
	// Row within t.window where the list begins (for reverse layouts top; default bottom)
	switch t.layout {
	case layoutReverse:
		line := 0
		if t.inputWindow == nil && !t.inputless {
			line++
			if !t.noSeparatorLine() {
				line++
			}
		}
		line += t.visibleHeaderLinesInList()
		return line
	case layoutReverseList:
		return 0
	default:
		return 0
	}
}

func (t *Terminal) displayWidth(runes []rune) int {
	width, _ := RunesWidth(runes, 0, t.tabstop, math.MaxInt32)
	return width
}

func (t *Terminal) printPrompt() {
	if t.inputless {
		return
	}
	w := t.inputWin()
	line := t.promptLine()
	w.MoveAndClear(line, 0)
	if t.headerFirst && t.inputWindow == nil && t.layout == layoutReverse {
		// header drawn first
		line = len(t.header0)
		if !t.headerVisible {
			line = 0
		}
		w.MoveAndClear(line, 0)
	}
	w.CPrint(ColPrompt, t.prompt)
	before, after := t.updatePromptOffset()
	color := ColInput
	if t.disabled {
		color = ColDisabled
	}
	if len(t.input) == 0 && len(t.ghost) > 0 {
		w.CPrint(ColGhost, t.ghost)
	} else {
		w.CPrint(color, string(before))
		w.CPrint(color, string(after))
	}
}

func (t *Terminal) updatePromptOffset() ([]rune, []rune) {
	w := t.inputWin()
	maxWidth := maxInt(1, w.Width()-t.promptLen-1)

	_, overflow := t.trimLeft(t.input[:t.cx], maxWidth)
	minOffset := int(overflow)
	maxOffset := minInt(minInt(len(t.input), maxWidth), t.cx)
	t.xoffset = constrain(t.xoffset, minOffset, maxOffset)
	before, _ := t.trimLeft(t.input[t.xoffset:t.cx], maxWidth)
	beforeLen := t.displayWidth(before)
	after, _ := t.trimRight(t.input[t.cx:], maxWidth-beforeLen)
	afterLen := t.displayWidth(after)
	t.queryLen = [2]int{beforeLen, afterLen}
	return before, after
}

func (t *Terminal) trimLeft(runes []rune, width int) ([]rune, int32) {
	width = maxInt(0, width)
	var trimmed int32
	// Assume that each rune takes at least one column on screen
	if len(runes) > width+2 {
		diff := len(runes) - width - 2
		trimmed = int32(diff)
		runes = runes[diff:]
	}

	currentWidth := t.displayWidth(runes)

	for currentWidth > width && len(runes) > 0 {
		runes = runes[1:]
		trimmed++
		currentWidth, _ = RunesWidth(runes, 2, t.tabstop, width)
	}
	return runes, trimmed
}

func (t *Terminal) trimRight(runes []rune, width int) ([]rune, int) {
	// We start from the beginning to handle tab characters
	_, overflowIdx := RunesWidth(runes, 0, t.tabstop, width)
	if overflowIdx >= 0 {
		return runes[:overflowIdx], len(runes) - overflowIdx
	}
	return runes, 0
}

func (t *Terminal) overflow(runes []rune, max int) bool {
	_, overflowIdx := RunesWidth(runes, 0, t.tabstop, max)
	return overflowIdx >= 0
}

func (t *Terminal) infoText() string {
	found := t.merger.Length()
	total := maxInt(found, t.count)
	output := fmt.Sprintf("%d/%d", found, total)
	if t.toggleSort {
		if t.sort {
			output += " +S"
		} else {
			output += " -S"
		}
	}
	if t.track != trackDisabled {
		output += " +T"
	}
	if t.multi > 0 {
		if t.multi == maxMulti {
			output += fmt.Sprintf(" (%d)", len(t.selected))
		} else {
			output += fmt.Sprintf(" (%d/%d)", len(t.selected), t.multi)
		}
	}
	if t.progress > 0 && t.progress < 100 {
		output += fmt.Sprintf(" (%d%%)", t.progress)
	}
	if t.failed != nil && t.count == 0 {
		output = fmt.Sprintf("[Command failed: %s]", *t.failed)
	}
	return output
}

func (t *Terminal) spinnerChar() string {
	duration := int64(200 * time.Millisecond)
	idx := (time.Now().UnixNano() % (duration * int64(len(t.spinner)))) / duration
	return t.spinner[idx]
}

func (t *Terminal) printInfo() {
	if t.inputless {
		return
	}
	w := t.inputWin()
	pos := 0
	line := t.infoLine()
	if t.headerFirst && t.inputWindow == nil && t.layout == layoutReverse && t.headerVisible {
		line += len(t.header0)
	}
	printSeparator := func(fillLength int, pad bool) {
		if t.separatorLen > 0 && fillLength > 0 {
			sep := repeatToWidth(t.separator, t.separatorLen, fillLength)
			w.CPrint(ColSeparator, sep)
			if pad {
				w.Print(" ")
			}
		}
	}
	output := t.infoText()
	if t.infoCommand != "" {
		output = t.executeInfoCommand(output)
	}
	switch t.infoStyle {
	case infoDefault:
		w.MoveAndClear(line, 0)
		if t.reading {
			w.CPrint(ColSpinner, t.spinnerChar())
		} else {
			w.Print(" ")
		}
		w.Move(line, 2)
		pos = 2
		maxWidth := w.Width() - pos
		output = t.trimMessage(output, maxWidth)
		w.CPrint(ColInfo, output)
		fillLength := maxWidth - StringWidth(output) - 2
		if fillLength > 0 {
			w.CPrint(ColSeparator, " ")
			printSeparator(fillLength, false)
		}
	case infoRight:
		w.MoveAndClear(line, 0)
		maxWidth := w.Width()
		if t.reading {
			maxWidth -= 2
		}
		output = t.trimMessage(output, maxWidth)
		fillLength := w.Width() - StringWidth(output) - 2
		if t.reading {
			if fillLength >= 2 {
				printSeparator(fillLength-2, true)
			}
			w.CPrint(ColSpinner, t.spinnerChar())
			w.Print(" ")
		} else if fillLength >= 0 {
			printSeparator(fillLength, true)
		}
		w.CPrint(ColInfo, output)
		w.Print(" ")
	case infoInline, infoInlineRight:
		pline := t.promptLine()
		if t.headerFirst && t.inputWindow == nil && t.layout == layoutReverse && t.headerVisible {
			pline = len(t.header0)
		}
		pos = t.promptLen + t.queryLen[0] + t.queryLen[1]
		if len(t.input) == 0 && len(t.ghost) > 0 {
			pos = t.promptLen + StringWidth(t.ghost)
		}
		str := t.infoPrefix
		spinner := ""
		if t.reading {
			spinner = t.spinnerChar()
		}
		if t.infoStyle == infoInlineRight {
			outputWidth := StringWidth(output)
			if t.reading {
				outputWidth += 2
			}
			if len(str) > 0 {
				outputWidth += StringWidth(str)
			}
			rpos := w.Width() - outputWidth - 1
			if rpos > pos {
				// Fill with separator between
				w.Move(pline, pos)
				fillLength := rpos - pos - 1
				if fillLength > 0 && t.separatorLen > 0 {
					w.Print(" ")
					printSeparator(fillLength, false)
				}
				w.Move(pline, rpos)
				if t.reading {
					w.CPrint(ColSpinner, spinner)
					w.Print(" ")
				}
				if len(str) > 0 {
					w.CPrint(ColPrompt, str)
				}
				w.CPrint(ColInfo, output)
			}
		} else {
			if t.reading {
				str = " " + spinner + " "
			}
			w.Move(pline, pos)
			w.CPrint(ColPrompt, str)
			w.CPrint(ColInfo, output)
			pos += StringWidth(str) + StringWidth(output)
			fillLength := w.Width() - pos - 2
			if fillLength > 0 && t.separatorLen > 0 {
				w.CPrint(ColSeparator, " ")
				printSeparator(fillLength, false)
			}
		}
	case infoHidden:
		if !t.noSeparatorLine() {
			w.MoveAndClear(line, 0)
			if t.separatorLen > 0 {
				printSeparator(w.Width()-1, false)
			}
		}
	}
}

func repeatToWidth(s string, sw int, width int) string {
	if sw <= 0 || width <= 0 {
		return ""
	}
	n := width / sw
	str := strings.Repeat(s, n)
	rem := width - n*sw
	if rem > 0 {
		str += strings.Repeat(" ", rem)
	}
	return str
}

func (t *Terminal) trimMessage(message string, maxWidth int) string {
	if StringWidth(message) <= maxWidth {
		return message
	}
	if maxWidth <= 2 {
		return strings.Repeat(".", maxInt(0, maxWidth))
	}
	runes, _ := Truncate(message, maxWidth-2)
	return string(runes) + strings.Repeat(".", 2)
}

func (t *Terminal) printHeader() {
	if !t.headerVisible {
		return
	}
	// Header lines from --header-lines (within list window or separate window)
	indent := t.pointerLen + t.markerLen
	indentStr := strings.Repeat(" ", indent)

	printLines := func(w *Window, lines []string, startLine int, wrapColor ColorPair) {
		for idx, lineStr := range lines {
			line := startLine + idx
			if line < 0 || line >= w.Height() {
				continue
			}
			text, colors, _ := extractColor(lineStr, nil, nil)
			runes := []rune(text)
			trimmed, _ := t.trimRight(runes, w.Width()-indent-1)
			w.MoveAndClear(line, 0)
			w.Print(indentStr)
			t.printColoredRunes(w, trimmed, colors, wrapColor)
		}
	}

	// Normal header
	if t.headerWindow != nil {
		printLines(t.headerWindow, t.header0, 0, ColHeader)
	}
	if t.headerLinesWindow != nil {
		hl := t.headerLinesOnly()
		printLines(t.headerLinesWindow, hl, 0, ColHeader)
	}
	if t.headerWindow == nil || t.headerLinesWindow == nil {
		// Draw in the main window
		var lines []string
		if t.headerWindow == nil && t.headerLinesWindow == nil {
			lines = t.combinedHeader()
		} else if t.headerWindow == nil {
			lines = t.header0
		} else {
			lines = t.headerLinesOnly()
		}
		if len(lines) == 0 {
			return
		}
		start := t.headerStartLine()
		if t.layout == layoutReverse && t.headerFirst && !t.inputless && t.inputWindow == nil && t.headerWindow == nil {
			// Header before prompt: header lines (from --header-lines) still go after the input
			hdr := t.header0
			printLines(t.window, hdr, 0, ColHeader)
			if t.headerLinesWindow == nil && t.headerLines > 0 {
				hl := t.headerLinesOnly()
				promptLines := 1
				if !t.noSeparatorLine() {
					promptLines = 2
				}
				printLines(t.window, hl, len(hdr)+promptLines, ColHeader)
			}
			return
		}
		if t.layout != layoutReverse && t.headerFirst && !t.inputless && t.inputWindow == nil && t.headerWindow == nil {
			// Header after the prompt (at the bottom)
			hdr := t.header0
			printLines(t.window, hdr, t.window.Height()-len(hdr), ColHeader)
			if t.headerLinesWindow == nil && t.headerLines > 0 {
				hl := t.headerLinesOnly()
				promptLines := 1
				if !t.noSeparatorLine() {
					promptLines = 2
				}
				printLines(t.window, hl, t.window.Height()-len(hdr)-promptLines-len(hl), ColHeader)
			}
			return
		}
		printLines(t.window, lines, start, ColHeader)
	}
}

// headerLinesOnly returns the header lines read from the input
func (t *Terminal) headerLinesOnly() []string {
	t.headerMutex.Lock()
	hl := make([]string, 0, t.headerLines)
	hl = append(hl, (*t.headerPtr)...)
	t.headerMutex.Unlock()
	for len(hl) < t.headerLines {
		hl = append(hl, "")
	}
	return hl
}

// combinedHeader returns the header lines in display order (top to bottom)
func (t *Terminal) combinedHeader() []string {
	hl := t.headerLinesOnly()
	switch t.layout {
	case layoutDefault, layoutReverseList:
		// header lines closest to the list: header lines on top, normal header below
		// (t.header0 is already reversed for these layouts)
		return append(reverseStringArray(hl), reverseStringArray(t.header0)...)
	default:
		return append(t.header0, hl...)
	}
}

func (t *Terminal) printFooter() {
	if len(t.footer) == 0 {
		return
	}
	indent := t.pointerLen + t.markerLen
	indentStr := strings.Repeat(" ", indent)
	w := t.footerWindow
	start := 0
	if w == nil {
		w = t.window
		start = w.Height() - len(t.footer)
	}
	for idx, lineStr := range t.footer {
		line := start + idx
		if line < 0 || line >= w.Height() {
			continue
		}
		text, colors, _ := extractColor(lineStr, nil, nil)
		runes := []rune(text)
		trimmed, _ := t.trimRight(runes, w.Width()-indent-1)
		w.MoveAndClear(line, 0)
		w.Print(indentStr)
		t.printColoredRunes(w, trimmed, colors, ColFooter)
	}
}

func (t *Terminal) printColoredRunes(w *Window, runes []rune, colors *[]ansiOffset, base ColorPair) {
	if colors == nil {
		w.CPrint(base, string(runes))
		return
	}
	idx := 0
	for _, off := range *colors {
		b := constrain(int(off.offset[0]), idx, len(runes))
		e := constrain(int(off.offset[1]), idx, len(runes))
		if b > idx {
			w.CPrint(base, string(runes[idx:b]))
		}
		if e > b {
			w.CPrint(ansiToPair(off.color, base), string(runes[b:e]))
		}
		idx = e
	}
	if idx < len(runes) {
		w.CPrint(base, string(runes[idx:]))
	}
}

func getScrollbar(total int, height int, offset int) (int, int) {
	if total == 0 || total <= height {
		return 0, 0
	}
	barLength := maxInt(1, height*height/total)
	var barStart int
	if total == height {
		barStart = 0
	} else {
		barStart = (height - barLength) * offset / (total - height)
	}
	return barLength, barStart
}

func (t *Terminal) printList() {
	t.constrain()
	maxy := t.maxItems()
	count := t.merger.Length() - t.offset
	barLength, barStart := getScrollbar(t.merger.Length(), maxy, t.offset)
	start := t.listStartLine()
	for j := 0; j < maxy; j++ {
		i := j
		if t.layout == layoutDefault {
			i = maxy - 1 - j
		}
		line := start + i
		if line >= t.window.Height() {
			continue
		}
		t.window.MoveAndClear(line, 0)
		hasBar := barLength > 0 && j >= barStart && j < barStart+barLength
		if j < count {
			itemIdx := t.offset + j
			t.printItem(t.merger.Get(itemIdx), line, itemIdx, itemIdx == t.cy)
		}
		if hasBar && len(t.scrollbar) > 0 {
			t.window.Move(line, t.window.Width()-1)
			t.window.CPrint(ColScrollbar, t.scrollbar)
		}
	}
}

func (t *Terminal) printItem(result Result2, line int, index int, current bool) {
	item := result.item
	_, selected := t.selected[item.Index()]
	label := ""
	if t.jumping != jumpDisabled {
		if index-t.offset < len(t.jumpLabels) {
			// Striped
			current = (index-t.offset)%2 == 0
			label = t.jumpLabels[index-t.offset:index-t.offset+1] + strings.Repeat(" ", t.pointerLen-1)
		}
	} else if current {
		label = t.pointer
	} else {
		if t.raw {
			label = t.gutterRaw
		} else {
			label = t.gutter
		}
	}

	t.window.Move(line, 0)
	if current {
		if len(label) == 0 {
			t.window.CPrint(ColCurrentCursorEmpty, t.pointerEmpty)
		} else {
			t.window.CPrint(ColCurrentCursor, label)
		}
		if selected {
			t.window.CPrint(ColCurrentMarker, t.marker)
		} else {
			t.window.CPrint(ColCurrentSelectedEmpty, t.markerEmpty)
		}
		colBase := ColCurrent
		colMatch := ColCurrentMatch
		t.printHighlighted(result, colBase, colMatch, true, true, line)
		if t.highlightLine {
			// Fill the rest of the line
			for x := t.window.X(); x < t.window.Width()-1; x++ {
				t.screen.Put(t.window.top+line, t.window.left+x, ' ', 1, t.window.effective(ColCurrent))
			}
		}
	} else {
		if len(label) == 0 {
			t.window.CPrint(ColCursorEmpty, t.pointerEmpty)
		} else {
			if t.jumping != jumpDisabled {
				t.window.CPrint(ColCursor, label)
			} else {
				t.window.CPrint(ColCursor.WithFg(ColorPair{fg: t.theme.Gutter.Color}), label)
			}
		}
		colBase := ColNormal
		colMatch := ColMatch
		if selected {
			t.window.CPrint(ColMarker, t.marker)
			colBase = ColSelected
			colMatch = ColSelectedMatch
		} else {
			t.window.Print(t.markerEmpty)
		}
		t.printHighlighted(result, colBase, colMatch, false, true, line)
	}
}

func (t *Terminal) printHighlighted(result Result2, colBase ColorPair, colMatch ColorPair, current bool, match bool, line int) int {
	item := result.item
	matchOffsets := []Offset{}
	var pos *[]int
	if match && t.pattern != nil && !t.pattern.IsEmpty() {
		_, matchOffsets, pos = t.pattern.MatchItem(item, true, t.slab)
	}
	charOffsets := matchOffsets
	if pos != nil {
		charOffsets = make([]Offset, len(*pos))
		for idx, p := range *pos {
			charOffsets[idx] = Offset{int32(p), int32(p + 1)}
		}
		sortOffsets(charOffsets)
	}
	allOffsets := t.colorOffsets(result, charOffsets, colBase, colMatch, current)

	maxWidth := t.window.Width() - (t.pointerLen + t.markerLen) - 1
	if maxWidth < 1 {
		return 0
	}
	text := make([]rune, item.text.Length())
	copy(text, item.text.ToRunes())
	// Strip trailing newline for display
	if !t.multiLine {
		for i, r := range text {
			if r == '\n' {
				text[i] = ' '
			}
		}
	} else {
		if idx := indexRune(text, '\n'); idx >= 0 {
			text = text[:idx]
		}
	}
	offsets := allOffsets

	var maxe int
	for _, offset := range offsets {
		if offset.match {
			maxe = maxInt(maxe, int(offset.offset[1]))
		}
	}

	displayWidth := t.displayWidthWithLimit(text, 0, maxWidth)
	if displayWidth > maxWidth {
		ellipsis, ellipsisWidth := Truncate(t.ellipsis, maxWidth/2)
		maxe = constrain(maxe+minInt(maxWidth/2-ellipsisWidth, t.hscrollOff), 0, len(text))
		transformOffsets := func(diff int32, rightTrim bool) {
			for idx, offset := range offsets {
				b, e := offset.offset[0], offset.offset[1]
				el := int32(len(ellipsis))
				b += el - diff
				e += el - diff
				b = maxInt32(b, el)
				if rightTrim {
					e = minInt32(e, int32(maxWidth-ellipsisWidth))
				}
				offsets[idx].offset[0] = b
				offsets[idx].offset[1] = maxInt32(b, e)
			}
		}
		if t.hscroll {
			if t.keepRight && pos == nil {
				trimmed, diff := t.trimLeft(text, maxWidth-ellipsisWidth)
				transformOffsets(diff, false)
				text = append(ellipsis, trimmed...)
			} else if !t.overflow(text[:maxe], maxWidth-ellipsisWidth) {
				// Stri..
				text, _ = t.trimRight(text, maxWidth-ellipsisWidth)
				text = append(text, ellipsis...)
			} else {
				// Stri..
				rightTrim := false
				if t.overflow(text[maxe:], t.hscrollOff) {
					text = append(text[:maxe], ellipsis...)
					rightTrim = true
				}
				// ..ri..
				var diff int32
				text, diff = t.trimLeft(text, maxWidth-ellipsisWidth)

				// Transform offsets
				transformOffsets(diff, rightTrim)
				text = append(ellipsis, text...)
			}
		} else {
			text, _ = t.trimRight(text, maxWidth-ellipsisWidth)
			text = append(text, ellipsis...)

			for idx, offset := range offsets {
				offsets[idx].offset[0] = minInt32(offset.offset[0], int32(maxWidth-len(ellipsis)))
				offsets[idx].offset[1] = minInt32(offset.offset[1], int32(maxWidth))
			}
		}
		displayWidth = t.displayWidthWithLimit(text, 0, displayWidth)
	}

	t.printColoredString(t.window, text, offsets, colBase)
	return displayWidth
}

func indexRune(runes []rune, r rune) int {
	for i, c := range runes {
		if c == r {
			return i
		}
	}
	return -1
}

func maxInt32(a, b int32) int32 {
	if a > b {
		return a
	}
	return b
}

func minInt32(a, b int32) int32 {
	if a < b {
		return a
	}
	return b
}

func (t *Terminal) displayWidthWithLimit(runes []rune, prefixWidth int, limit int) int {
	width, _ := RunesWidth(runes, prefixWidth, t.tabstop, limit)
	return width
}

func (t *Terminal) processTabs(runes []rune, prefixWidth int) (string, int) {
	var strbuf strings.Builder
	l := prefixWidth
	gr := graphemeClusterRunes(runes)
	for _, g := range gr {
		str := string(g)
		var w int
		if len(g) == 1 && g[0] == '\t' {
			w = t.tabstop - l%t.tabstop
			strbuf.WriteString(strings.Repeat(" ", w))
		} else {
			w = clusterWidth(g)
			strbuf.WriteString(str)
		}
		l += w
	}
	return strbuf.String(), l
}

func (t *Terminal) printColoredString(window *Window, text []rune, offsets []colorOffset, colBase ColorPair) {
	var index int32
	var substr string
	var prefixWidth int
	maxOffset := int32(len(text))
	for _, offset := range offsets {
		b := constrain32(offset.offset[0], index, maxOffset)
		e := constrain32(offset.offset[1], index, maxOffset)

		substr, prefixWidth = t.processTabs(text[index:b], prefixWidth)
		window.CPrint(colBase, substr)

		if b < e {
			substr, prefixWidth = t.processTabs(text[b:e], prefixWidth)
			window.CPrint(offset.color, substr)
		}

		index = e
		if index >= maxOffset {
			break
		}
	}
	if index < maxOffset {
		substr, _ = t.processTabs(text[index:], prefixWidth)
		window.CPrint(colBase, substr)
	}
}

func constrain32(val, min, max int32) int32 {
	if val < min {
		return min
	}
	if val > max {
		return max
	}
	return val
}

func (t *Terminal) colorOffsets(result Result2, matchOffsets []Offset, colBase ColorPair, colMatch ColorPair, current bool) []colorOffset {
	itemColors := result.item.Colors()
	theme := t.theme

	// No ANSI codes
	if len(itemColors) == 0 {
		var offsets []colorOffset
		for _, off := range matchOffsets {
			offsets = append(offsets, colorOffset{offset: [2]int32{off[0], off[1]}, color: colMatch, match: true})
		}
		return offsets
	}

	// Find max column
	var maxCol int32
	for _, off := range matchOffsets {
		if off[1] > maxCol {
			maxCol = off[1]
		}
	}
	for _, ansi := range itemColors {
		if ansi.offset[1] > maxCol {
			maxCol = ansi.offset[1]
		}
	}

	cols := make([]int, maxCol)
	for colorIndex, ansi := range itemColors {
		for i := ansi.offset[0]; i < ansi.offset[1]; i++ {
			cols[i] = colorIndex + 1
		}
	}
	for _, off := range matchOffsets {
		for i := off[0]; i < off[1]; i++ {
			cols[i] = cols[i]*-1 - 1
		}
	}

	curr := 0
	start := 0
	ansiToColorPair := func(ansi ansiOffset, base ColorPair) ColorPair {
		fg := ansi.color.fg
		bg := ansi.color.bg
		if fg == colDefault {
			if current {
				fg = theme.Current.Color
			} else {
				fg = base.fg
			}
		}
		if bg == colDefault {
			if current {
				bg = theme.DarkBg.Color
			} else {
				bg = base.bg
			}
		}
		return NewColorPair(fg, bg, ansi.color.attr).MergeAttr(base)
	}
	var colors []colorOffset
	add := func(idx int) {
		if curr != 0 && idx > start {
			if curr < 0 {
				color := colMatch
				if curr < -1 && theme.Colored {
					origColor := ansiToColorPair(itemColors[-curr-2], colMatch)
					if color.Fg().IsDefault() && origColor.HasBg() {
						color = origColor
					} else {
						color = origColor.MergeNonDefault(color)
					}
				}
				colors = append(colors, colorOffset{offset: [2]int32{int32(start), int32(idx)}, color: color, match: true})
			} else {
				ansi := itemColors[curr-1]
				colors = append(colors, colorOffset{offset: [2]int32{int32(start), int32(idx)}, color: ansiToColorPair(ansi, colBase), match: false, url: ansi.color.url})
			}
		}
	}
	for idx, col := range cols {
		if col != curr {
			add(idx)
			start = idx
			curr = col
		}
	}
	add(int(maxCol))
	return colors
}

// constrain adjusts the cursor and the offset
func (t *Terminal) constrain() {
	count := t.merger.Length()
	maxLines := t.maxItems()

	if count > 0 {
		t.cy = constrain(t.cy, 0, count-1)
	} else {
		t.cy = 0
	}

	minOffset := maxInt(t.cy-maxLines+1, 0)
	maxOffset := maxInt(minInt(count-maxLines, t.cy), 0)
	t.offset = constrain(t.offset, minOffset, maxOffset)
	if t.scrollOff > 0 && maxLines > 0 {
		scrollOff := minInt(maxLines/2, t.scrollOff)
		newOffset := t.offset
		for {
			prevOffset := newOffset
			if t.cy-newOffset < scrollOff {
				newOffset = maxInt(minOffset, newOffset-1)
			}
			if t.cy-newOffset >= maxLines-scrollOff {
				newOffset = minInt(maxOffset, newOffset+1)
			}
			if newOffset == prevOffset {
				break
			}
		}
		t.offset = newOffset
	}
}

func (t *Terminal) vmove(o int, allowCycle bool) {
	if t.layout != layoutDefault {
		o *= -1
	}
	dest := t.cy + o
	if t.cycle && allowCycle {
		max := t.merger.Length() - 1
		if dest > max {
			if t.cy == max {
				dest = 0
			}
		} else if dest < 0 {
			if t.cy == 0 {
				dest = max
			}
		}
	}
	t.vset(dest)
}

func (t *Terminal) vset(o int) bool {
	t.cy = constrain(o, 0, t.merger.Length()-1)
	return t.cy == o
}

// printAll renders everything
func (t *Terminal) printAll() {
	t.screen.Clear()
	t.resizeWindows(t.forcePreview)
	// Borders
	if t.border != nil {
		t.drawBorder(t.border, t.borderLabel, ColBorderLabel)
	}
	if t.listBorder != nil {
		t.drawBorder(t.listBorder, t.listLabel, ColListLabel)
	}
	if t.inputBorder != nil {
		if t.inputBorderShape == BorderLine {
			t.drawLineBorderFor(t.inputBorder, t.inputBorderShape, "input")
		} else {
			t.drawBorder(t.inputBorder, t.inputLabel, ColInputLabel)
		}
	}
	if t.headerBorder != nil {
		if t.headerBorderShape == BorderLine {
			t.drawLineBorderFor(t.headerBorder, t.headerBorderShape, "header")
		} else {
			t.drawBorder(t.headerBorder, t.headerLabel, ColHeaderLabel)
		}
	}
	if t.headerLinesBorder != nil {
		if t.headerLinesShape == BorderLine {
			t.drawLineBorderFor(t.headerLinesBorder, t.headerLinesShape, "headerLines")
		} else {
			t.drawBorder(t.headerLinesBorder, labelOpts{}, ColHeaderLabel)
		}
	}
	if t.footerBorder != nil {
		if t.footerBorderShape == BorderLine {
			t.drawLineBorderFor(t.footerBorder, t.footerBorderShape, "footer")
		} else {
			t.drawBorder(t.footerBorder, t.footerLabel, ColFooterLabel)
		}
	}
	if t.window != nil {
		t.window.Erase()
	}
	t.printList()
	t.printPrompt()
	t.printInfo()
	t.printHeader()
	t.printFooter()
	t.printPreview()
}

// drawLineBorderFor draws a single separator line for 'line' border style
func (t *Terminal) drawLineBorderFor(w *Window, shape BorderShape, kind string) {
	// Determine the side: the line is drawn between the section and the list
	var side BorderShape
	switch kind {
	case "input":
		if t.layout == layoutReverse {
			side = BorderBottom
		} else {
			side = BorderTop
		}
	case "header":
		if t.layout == layoutReverse {
			side = BorderBottom
		} else {
			side = BorderTop
		}
	case "headerLines":
		if t.layout == layoutReverse {
			side = BorderBottom
		} else {
			side = BorderTop
		}
	case "footer":
		side = BorderTop
	}
	w.border = MakeBorderStyle(side, t.unicode)
	w.border.shape = side
	t.drawLineBorder(w)
}

func (t *Terminal) cursorPosition() (int, int) {
	if t.inputless {
		return -1, -1
	}
	w := t.inputWin()
	line := t.promptLine()
	if t.headerFirst && t.inputWindow == nil && t.layout == layoutReverse && t.headerVisible {
		line = len(t.header0)
	}
	x := t.promptLen + t.queryLen[0]
	if x >= w.Width() {
		x = w.Width() - 1
	}
	return w.top + line, w.left + x
}

func (t *Terminal) refresh() {
	if t.suppressRender {
		return
	}
	t.printAll()
	cy, cx := t.cursorPosition()
	showCursor := cy >= 0
	if t.inputless {
		showCursor = false
	}
	t.screen.Flush(cy, cx, showCursor)
}

func (t *Terminal) executeInfoCommand(info string) string {
	cmd := t.executor.ExecCommand(t.infoCommand, false)
	cmd.Env = append(t.environ(), "FZF_INFO="+info)
	out, err := cmd.Output()
	if err != nil {
		return info
	}
	s := strings.TrimRight(string(out), "\r\n")
	return s
}

func itoa(i int) string { return strconv.Itoa(i) }

func isSpace(r rune) bool { return unicode.IsSpace(r) }
