// environ returns the environment variables for child processes
func (t *Terminal) environ() []string {
	env := os.Environ()
	if t.listenAddr != nil && t.listenPort > 0 {
		env = append(env, fmt.Sprintf("FZF_PORT=%d", t.listenPort))
	}
	env = append(env, "FZF_QUERY="+string(t.input))
	env = append(env, "FZF_ACTION="+t.lastAction.Name())
	env = append(env, "FZF_KEY="+t.lastKey)
	env = append(env, "FZF_PROMPT="+t.prompt)
	env = append(env, "FZF_GHOST="+t.ghost)
	env = append(env, "FZF_POINTER="+t.pointer)
	env = append(env, "FZF_PREVIEW_LABEL="+t.previewLabel.label)
	env = append(env, "FZF_BORDER_LABEL="+t.borderLabel.label)
	env = append(env, "FZF_LIST_LABEL="+t.listLabel.label)
	env = append(env, "FZF_INPUT_LABEL="+t.inputLabel.label)
	env = append(env, "FZF_HEADER_LABEL="+t.headerLabel.label)
	env = append(env, fmt.Sprintf("FZF_TOTAL_COUNT=%d", t.count))
	env = append(env, fmt.Sprintf("FZF_MATCH_COUNT=%d", t.merger.Length()))
	env = append(env, fmt.Sprintf("FZF_SELECT_COUNT=%d", len(t.selected)))
	env = append(env, fmt.Sprintf("FZF_LINES=%d", t.areaLines))
	env = append(env, fmt.Sprintf("FZF_COLUMNS=%d", t.areaColumns))
	env = append(env, fmt.Sprintf("FZF_POS=%d", minInt(t.merger.Length(), t.cy+1)))
	inputState := "enabled"
	if t.inputless {
		inputState = "hidden"
	} else if t.disabled {
		inputState = "disabled"
	}
	env = append(env, "FZF_INPUT_STATE="+inputState)
	nth := []string{}
	for _, r := range t.nthCurrent {
		nth = append(nth, rangeString(r))
	}
	env = append(env, "FZF_NTH="+strings.Join(nth, ","))
	direction := "down"
	if t.layout == layoutDefault {
		direction = "up"
	}
	env = append(env, "FZF_DIRECTION="+direction)
	if t.pwindow != nil {
		env = append(env, fmt.Sprintf("FZF_PREVIEW_TOP=%d", t.pwindow.Top()))
		env = append(env, fmt.Sprintf("FZF_PREVIEW_LEFT=%d", t.pwindow.Left()))
		env = append(env, fmt.Sprintf("FZF_PREVIEW_LINES=%d", t.pwindow.Height()))
		env = append(env, fmt.Sprintf("FZF_PREVIEW_COLUMNS=%d", t.pwindow.Width()))
		env = append(env, fmt.Sprintf("LINES=%d", t.pwindow.Height()))
		env = append(env, fmt.Sprintf("COLUMNS=%d", t.pwindow.Width()))
	}
	return env
}

func rangeString(r Range) string {
	b := r.begin
	e := r.end
	if b == rangeEllipsis && e == rangeEllipsis {
		return ".."
	}
	bs := ""
	if b != rangeEllipsis {
		bs = strconv.Itoa(b)
	}
	es := ""
	if e != rangeEllipsis {
		es = strconv.Itoa(e)
	}
	if b == e {
		return bs
	}
	return bs + ".." + es
}

// ---- Preview execution ----

type previewOutput struct {
	version int64
	lines   []string
	final   bool
	offset  int
	err     error
}

func (t *Terminal) previewList() []*Item {
	current := t.currentItem()
	list := []*Item{current}
	if t.multi > 0 {
		for _, sel := range t.sortSelected() {
			list = append(list, sel.item)
		}
	} else if current != nil {
		list = append(list, current)
	}
	return list
}

func (t *Terminal) evaluateScrollOffset() int {
	if t.pwindow == nil {
		return 0
	}
	// We only need the current item to calculate the scroll offset
	replaced, tempFiles := t.replacePlaceholder(t.activePreviewOpts.scroll, false, "", []*Item{t.currentItem(), nil})
	cleanTemporaryFiles(tempFiles)
	offsetExpr := strings.TrimSpace(replaced)
	offsetExpr = strings.Trim(offsetExpr, "'")

	atoi := func(s string) int {
		n, e := strconv.Atoi(s)
		if e != nil {
			return 0
		}
		return n
	}

	base := -1
	height := maxInt(0, t.pwindow.Height()-t.activePreviewOpts.headerLines)
	for _, component := range strings.Split(offsetExpr, "/") {
		if component == "" {
			continue
		}
		if component[0] == '-' {
			if base == -1 {
				base = height - atoi(component[1:])
			} else {
				base -= atoi(component[1:])
			}
		} else if component[0] == '+' {
			if base == -1 {
				base = atoi(component[1:])
			} else {
				base += atoi(component[1:])
			}
		} else {
			if base == -1 {
				base = atoi(component)
			} else {
				base = base * 0 // denominator
			}
		}
	}
	// Handle /DENOM
	parts := strings.Split(offsetExpr, "/")
	result := 0
	if len(parts) > 0 {
		expr := parts[0]
		// sum signed integers
		sum := 0
		re := regexp.MustCompile(`[+-]?[0-9]+`)
		for _, m := range re.FindAllString(expr, -1) {
			sum += atoi(m)
		}
		result = sum
		if len(parts) > 1 {
			denom := atoi(parts[1])
			if denom > 0 {
				result -= height / denom
			}
		}
	}
	return maxInt(0, result)
}

func (t *Terminal) startPreview(req previewRequest) {
	t.previewMutex.Lock()
	t.killPreviewLocked()
	version := atomic.AddInt64(&t.previewVersion, 1)
	t.previewMutex.Unlock()

	replaced := req.template
	cmd := t.executor.ExecCommand(replaced, true)
	cmd.Env = req.env
	// Stdin from the tty would block; use /dev/null
	cmd.Stdin = nil
	out, err := cmd.StdoutPipe()
	if err != nil {
		return
	}
	cmd.Stderr = cmd.Stdout
	if err := cmd.Start(); err != nil {
		t.previewOutChan <- previewOutput{version: version, lines: []string{}, final: true, err: err}
		return
	}
	t.previewMutex.Lock()
	t.previewCmd = cmd.Process
	t.previewMutex.Unlock()
	go func() {
		reader := bufio.NewReader(out)
		lines := []string{}
		lastSend := time.Now()
		eofChan := make(chan bool)
		for {
			line, err := reader.ReadString('\n')
			if len(line) > 0 {
				line = strings.TrimRight(line, "\r\n")
				lines = append(lines, line)
			}
			if err != nil {
				break
			}
			if time.Since(lastSend) > 100*time.Millisecond {
				cp := make([]string, len(lines))
				copy(cp, lines)
				t.previewOutChan <- previewOutput{version: version, lines: cp, final: false, offset: req.scrollOffset}
				lastSend = time.Now()
			}
		}
		_ = eofChan
		cmd.Wait()
		t.previewOutChan <- previewOutput{version: version, lines: lines, final: true, offset: req.scrollOffset}
	}()
}

func (t *Terminal) killPreviewLocked() {
	if t.previewCmd != nil {
		syscall.Kill(-t.previewCmd.Pid, syscall.SIGKILL)
		t.previewCmd = nil
	}
}

func (t *Terminal) killPreview() {
	t.previewMutex.Lock()
	t.killPreviewLocked()
	t.previewMutex.Unlock()
}

func (t *Terminal) printPreview() {
	if t.pwindow == nil {
		return
	}
	// Border
	if t.pborder != nil {
		if t.activePreviewOpts.border == BorderLine {
			t.drawLineBorder(t.pborder)
		} else {
			t.drawBorder(t.pborder, t.previewLabel, ColPreviewLabel)
		}
	}
	w := t.pwindow
	w.Erase()
	lines := t.previewer.lines
	height := w.Height()
	if height == 0 || w.Width() == 0 {
		return
	}
	headerLines := t.activePreviewOpts.headerLines
	// Constrain offset
	maxOffset := maxInt(0, len(lines)-height)
	if t.previewer.following {
		t.previewer.offset = maxOffset
	}
	t.previewer.offset = constrain(t.previewer.offset, headerLines, maxInt(headerLines, maxOffset+headerLines))
	if len(lines) <= headerLines {
		t.previewer.offset = headerLines
	}
	t.previewer.scrollable = len(lines) > height

	var ansiState *ansiState
	y := 0
	printLine := func(lineStr string) bool {
		if y >= height {
			return false
		}
		w.Move(y, 0)
		text, offsets, newState := extractColor(lineStr, ansiState, nil)
		ansiState = newState
		runes := []rune(text)
		if t.activePreviewOpts.wrap {
			startY := y
			idx := 0
			var colorIdx int
			var offs []ansiOffset
			if offsets != nil {
				offs = *offsets
			}
			prefixWidth := 0
			for idx < len(runes) {
				pair := ColPreview
				end := len(runes)
				for ci := colorIdx; ci < len(offs); ci++ {
					o := offs[ci]
					if int32(idx) >= o.offset[0] && int32(idx) < o.offset[1] {
						pair = ansiToPair(o.color, ColPreview)
						end = int(o.offset[1])
						break
					} else if int32(idx) < o.offset[0] {
						end = int(o.offset[0])
						break
					} else {
						colorIdx = ci + 1
					}
				}
				seg, pw := t.processTabs(runes[idx:end], prefixWidth)
				prefixWidth = pw
				ret := w.fillString(seg, pair)
				idx = end
				if ret == FillSuspend {
					y = height
					return false
				}
			}
			_ = startY
			y = w.Y() + 1
			if w.X() == 0 && w.Y() > startY {
				y = w.Y()
			}
			return true
		}
		// No wrap: truncate
		maxWidth := w.Width()
		if t.previewer.scrollable && len(t.previewScrollbar) > 0 {
			maxWidth--
		}
		trimmed, _ := t.trimRight(runes, maxWidth)
		var offs *[]ansiOffset
		if offsets != nil {
			offs = offsets
		}
		expanded, _ := t.processTabsWithOffsets(trimmed, offs)
		_ = expanded
		t.printColoredRunes(w, trimmed, offs, ColPreview)
		y++
		return true
	}
	// Header lines
	for i := 0; i < headerLines && i < len(lines); i++ {
		if !printLine(lines[i]) {
			break
		}
	}
	for i := t.previewer.offset; i < len(lines) && y < height; i++ {
		if !printLine(lines[i]) {
			break
		}
	}
	// Scroll info
	if t.activePreviewOpts.info && t.previewer.scrollable && len(lines) > 0 {
		offset := fmt.Sprintf("%d/%d", t.previewer.offset+1, len(lines))
		pos := w.Width() - len(offset)
		if t.previewer.scrollable && len(t.previewScrollbar) > 0 {
			pos--
		}
		if pos >= 0 {
			w.Move(0, pos)
			w.CPrint(ColInfo.WithAttr(AttrReverse), offset)
		}
	}
	// Scrollbar
	if t.previewer.scrollable && len(t.previewScrollbar) > 0 {
		effectiveHeight := height - headerLines
		barLength, barStart := getScrollbar(len(lines)-headerLines, effectiveHeight, t.previewer.offset-headerLines)
		for i := 0; i < effectiveHeight; i++ {
			yy := headerLines + i
			if i >= barStart && i < barStart+barLength {
				w.Move(yy, w.Width()-1)
				w.CPrint(ColPreviewScrollbar, t.previewScrollbar)
			}
		}
	}
}

func (t *Terminal) processTabsWithOffsets(runes []rune, offsets *[]ansiOffset) (string, int) {
	return t.processTabs(runes, 0)
}

func (t *Terminal) runPreviewCommand() {
	if !t.hasPreviewer || len(t.previewOpts.command) == 0 {
		return
	}
	if !t.needPreviewWindow() && t.previewOpts.hidden {
		// Still run in background? Only when the window is visible
		return
	}
	list := t.previewList()
	_, _, forceUpdate := hasPreviewFlags(t.previewOpts.command)
	if list[0] == nil && !forceUpdate {
		// No current item: clear the preview
		t.previewer.lines = []string{}
		t.previewer.offset = 0
		t.killPreview()
		return
	}
	replaced, tempFiles := t.replacePlaceholder(t.previewOpts.command, false, string(t.input), list)
	t.previewTempFiles = append(t.previewTempFiles, tempFiles...)
	offset := 0
	if len(t.activePreviewOpts.scroll) > 0 {
		offset = t.evaluateScrollOffset()
	}
	req := previewRequest{template: replaced, scrollOffset: offset, list: list, env: t.environ(), query: string(t.input)}
	t.previewer.following = t.activePreviewOpts.follow
	t.startPreview(req)
}

func execCommandExists(x *Executor) bool {
	_, err := exec.LookPath(x.shell)
	return err == nil
}
