func copySlice(slice []rune) []rune {
	ret := make([]rune, len(slice))
	copy(ret, slice)
	return ret
}

func findLastMatch(pattern string, str string) int {
	rx, err := regexp.Compile(pattern)
	if err != nil {
		return -1
	}
	locs := rx.FindAllStringIndex(str, -1)
	if locs == nil {
		return -1
	}
	prefix := []rune(str[:locs[len(locs)-1][0]])
	return len(prefix)
}

func findFirstMatch(pattern string, str string) int {
	rx, err := regexp.Compile(pattern)
	if err != nil {
		return -1
	}
	loc := rx.FindStringIndex(str)
	if loc == nil {
		return -1
	}
	prefix := []rune(str[:loc[0]])
	return len(prefix)
}

type readerState struct {
	mutex    sync.Mutex
	finished bool
	failed   *string
	reader   *Reader
	command  *string
}

// runInteractive starts the interactive finder
func runInteractive(opts *Options, chunkList *ChunkList, patternBuilder func([]rune) *Pattern, executor *Executor, header *[]string, headerMutex *sync.Mutex, headerEvent chan bool) (int, error) {
	t := NewTerminal(opts, chunkList, patternBuilder, executor, header, headerMutex)
	t.headerEvent = headerEvent
	t.executorRef = executor

	// Initial command from start:reload
	initialCommand := ""
	initialEnv := []string(nil)
	if acts, ok := opts.Keymap[Start.AsEvent()]; ok {
		for _, act := range acts {
			if act.t == actReload || act.t == actReloadSync {
				initialCommand = act.a
				break
			}
		}
	}
	if initialCommand != "" {
		initialEnv = t.environ()
		// Replace placeholders (no current item)
		replaced, _ := t.replacePlaceholder(initialCommand, false, string(t.input), []*Item{nil, nil})
		initialCommand = replaced
		t.startReloadHandled = true
	}

	// Default scheme: path scheme when the input is a TTY and there's no reload on start
	t.startReader(opts.Input, initialCommand, initialEnv)

	deferred := opts.Select1 || opts.Exit0 || opts.Sync
	if deferred {
		// Wait for the reader to finish
		for !t.readerDone() {
			select {
			case <-t.readerChan:
			case <-time.After(50 * time.Millisecond):
			}
		}
		t.drainReaderChan()
		t.reading = false
		t.rematch(true)
		count := t.merger.Length()
		if opts.Exit0 && count == 0 || opts.Select1 && count == 1 {
			if opts.PrintQuery {
				opts.Printer(opts.Query)
			}
			if len(opts.Expect) > 0 {
				opts.Printer("")
			}
			for i := 0; i < count; i++ {
				opts.Printer(t.itemAsString(t.merger.Get(i).item))
			}
			if count == 0 {
				return exitNoMatch, nil
			}
			return exitOk, nil
		}
	}

	return t.Loop()
}

func (t *Terminal) readerDone() bool {
	t.readerMutex.Lock()
	defer t.readerMutex.Unlock()
	return t.readerFinished
}

func (t *Terminal) drainReaderChan() {
	for {
		select {
		case <-t.readerChan:
		default:
			return
		}
	}
}

func (t *Terminal) notifyReader() {
	select {
	case t.readerChan <- true:
	default:
	}
}

// startReader launches the reader goroutine
func (t *Terminal) startReader(inputChan chan string, command string, env []string) {
	t.readerMutex.Lock()
	t.readerFinished = false
	t.readerMutex.Unlock()
	t.reading = true
	gen := t.readerGeneration + 1
	t.readerGeneration = gen
	var lastNotify time.Time
	var mu sync.Mutex
	reader := NewReader(func(data []byte) bool {
		t.readerMutex.Lock()
		stale := gen != t.readerGeneration
		t.readerMutex.Unlock()
		if stale {
			return false
		}
		t.chunkList.Push(data)
		mu.Lock()
		if time.Since(lastNotify) > 30*time.Millisecond {
			lastNotify = time.Now()
			t.notifyReader()
		}
		mu.Unlock()
		return true
	}, func(success bool) {
		t.readerMutex.Lock()
		if gen == t.readerGeneration {
			t.readerFinished = true
			if !success && command != "" {
				cmd := command
				t.readerFailed = &cmd
			} else {
				t.readerFailed = nil
			}
		}
		t.readerMutex.Unlock()
		t.notifyReader()
	}, t.executor, t.opts.ReadZero, false)
	t.readerMutex.Lock()
	if t.currentReader != nil {
		t.currentReader.terminate()
	}
	t.currentReader = reader
	t.readerMutex.Unlock()
	go reader.ReadSource(inputChan, t.opts.WalkerRoot, t.opts.WalkerOpts, t.opts.WalkerSkip, command, env, nil)
}

// rematch runs the matcher against the current snapshot
func (t *Terminal) rematch(final bool) {
	snapshot, count, _ := t.chunkList.Snapshot(t.opts.Tail)
	t.count = count
	t.readerMutex.Lock()
	t.failed = t.readerFailed
	t.readerMutex.Unlock()
	var pattern *Pattern
	if t.disabled {
		pattern = t.patternBuilder([]rune{})
	} else {
		pattern = t.patternBuilder(t.input)
	}
	// Apply nth override
	if t.nthChanged {
		pattern.nth = t.nthCurrent
	}
	t.pattern = pattern
	t.revision++
	// Exclusions
	items := snapshot
	if len(t.denylist) > 0 {
		filtered := make([]*Item, 0, len(items))
		for _, item := range items {
			if !t.denied(item.Index()) {
				filtered = append(filtered, item)
			}
		}
		items = filtered
	}
	prevIdx := t.currentIndex()
	t.merger = matchItems(items, pattern, t.sort, t.opts.Tac, t.revision, t.slab)
	t.merger.final = final
	// Tracking
	if t.track != trackDisabled && prevIdx >= 0 {
		if idx := t.merger.FindIndex(prevIdx); idx >= 0 {
			t.cy = idx
		} else if t.track == trackCurrent {
			t.track = trackDisabled
		}
	}
	t.needMatch = false
}

func (t *Terminal) denied(idx int32) bool {
	for _, d := range t.denylist {
		if d == idx {
			return true
		}
	}
	return false
}

func (t *Terminal) initScreen() error {
	tty, err := openTty(t.opts.TtyDefault)
	if err != nil {
		return errorf("failed to open %s", t.opts.TtyDefault)
	}
	t.tty = tty
	t.ttyState = ttyState{fd: int(tty.Fd())}
	if err := t.ttyState.makeRaw(); err != nil {
		return errorf("inappropriate ioctl for device")
	}
	w, h, err := getWinSize(t.ttyState.fd)
	if err != nil || w <= 0 || h <= 0 {
		t.ttyState.restore()
		return errorf("inappropriate ioctl for device")
	}
	t.termWidth = w
	t.termHeight = h

	baseTheme := defaultBaseTheme()
	InitTheme(t.theme, baseTheme, t.opts.Black, t.opts.Bold)
	maxColors := maxColorsForTerm()

	height := t.calculateHeight(h, t.chunkList.Count())
	t.screen = NewScreen(tty, t.fullscreen, w, height, t.theme, maxColors)
	t.screen.bgPair = ColorPair{fg: t.theme.Fg.Color, bg: t.theme.Bg.Color}
	t.screen.Init(t.mouse)
	t.ttyin = newKeyReader(tty)
	go func() {
		for {
			ev := t.ttyin.GetChar()
			t.eventChan <- ev
		}
	}()
	t.setupSignals()
	return nil
}

func (t *Terminal) handleResize() {
	w, h, err := getWinSize(t.ttyState.fd)
	if err != nil || w <= 0 || h <= 0 {
		return
	}
	t.termWidth = w
	t.termHeight = h
	height := t.calculateHeight(h, t.chunkList.Count())
	if t.fullscreen {
		t.screen.Resize(w, h)
		t.screen.write("\x1b[H\x1b[2J")
	} else {
		if height != t.screen.height {
			// Re-reserve lines
			t.screen.moveTo(0, 0)
			t.screen.csi("J")
			t.screen.flushBuf()
			t.screen.Resize(w, height)
			t.screen.Init(false)
		} else {
			t.screen.Resize(w, height)
		}
	}
	t.screen.Invalidate()
}

func (t *Terminal) exit(code int) {
	t.done = true
	t.exitCode = code
}

// Loop is the main event loop
func (t *Terminal) Loop() (int, error) {
	if err := t.initScreen(); err != nil {
		return exitError, err
	}
	defer func() {
		t.killPreview()
		cleanTemporaryFiles(t.previewTempFiles)
	}()

	// Initial render
	t.rematch(t.readerDone())
	if t.readerDone() {
		t.reading = false
	}
	t.refresh()
	if t.hasPreviewer {
		t.runPreviewCommand()
	}
	t.lastFocus = t.currentIndex()

	// start event
	if acts, ok := t.keymap[Start.AsEvent()]; ok {
		t.executeActions(acts, Start.AsEvent())
	}
	t.resultEventPending = true
	t.focusEventPending = true

	ticker := time.NewTicker(100 * time.Millisecond)
	defer ticker.Stop()
	loadFired := false
	lastMatch := time.Now()

	for !t.done {
		t.processPendingEvents()
		if t.done {
			break
		}
		t.refresh()
		select {
		case ev := <-t.eventChan:
			t.handleEvent(ev)
		case <-t.readerChan:
			if t.readerDone() {
				t.reading = false
				t.rematch(true)
				if !loadFired {
					loadFired = true
					t.loadEventPending = true
				}
				t.resultEventPending = true
			} else if time.Since(lastMatch) > 50*time.Millisecond {
				t.rematch(false)
				t.resultEventPending = true
				lastMatch = time.Now()
			}
			t.afterListChange()
		case out := <-t.previewOutChan:
			if out.version == t.previewVersion {
				t.previewer.lines = out.lines
				t.previewer.final = out.final
				if out.version != t.previewer.version {
					t.previewer.version = out.version
					t.previewer.offset = out.offset + t.activePreviewOpts.headerLines
				}
			}
		case <-t.resizeChan:
			t.handleResize()
			if acts, ok := t.keymap[Resize.AsEvent()]; ok {
				t.executeActions(acts, Resize.AsEvent())
			}
		case <-ticker.C:
			if t.reading && !t.readerDone() {
				if time.Since(lastMatch) > 100*time.Millisecond {
					t.rematch(false)
					lastMatch = time.Now()
					t.afterListChange()
				}
			} else if t.reading && t.readerDone() {
				t.reading = false
				t.rematch(true)
				if !loadFired {
					loadFired = true
					t.loadEventPending = true
				}
				t.resultEventPending = true
				t.afterListChange()
			}
			if t.reloadPending != nil && t.readerDone() {
				// reload-sync completion handled in afterListChange
			}
		}
	}
	// Exit
	t.screen.Close(t.clearOnExit)
	t.ttyState.restore()
	if t.exitCode <= exitNoMatch && t.history != nil {
		t.history.append(string(t.input))
	}
	if t.becomeCommand != "" {
		t.executor.Become(t.tty, t.becomeEnv, t.becomeCommand)
	}
	return t.exitCode, nil
}

func (t *Terminal) afterListChange() {
	// Focus change
	idx := t.currentIndex()
	if idx != t.lastFocus {
		t.lastFocus = idx
		t.focusEventPending = true
		if t.hasPreviewer {
			t.previewPending = true
		}
	}
}

func (t *Terminal) processPendingEvents() {
	if t.loadEventPending {
		t.loadEventPending = false
		if acts, ok := t.keymap[Load.AsEvent()]; ok {
			t.executeActions(acts, Load.AsEvent())
		}
	}
	if t.resultEventPending {
		t.resultEventPending = false
		if acts, ok := t.keymap[ResultEvent.AsEvent()]; ok {
			t.executeActions(acts, ResultEvent.AsEvent())
		}
		if !t.reading || true {
			count := t.merger.Length()
			if count == 1 {
				if acts, ok := t.keymap[One.AsEvent()]; ok {
					t.executeActions(acts, One.AsEvent())
				}
			} else if count == 0 {
				if acts, ok := t.keymap[Zero.AsEvent()]; ok {
					t.executeActions(acts, Zero.AsEvent())
				}
			}
		}
	}
	if t.focusEventPending {
		t.focusEventPending = false
		if acts, ok := t.keymap[Focus.AsEvent()]; ok {
			t.executeActions(acts, Focus.AsEvent())
		}
	}
	if t.previewPending && t.hasPreviewer {
		t.previewPending = false
		t.runPreviewCommand()
	}
	if t.multiEventPending {
		t.multiEventPending = false
		if acts, ok := t.keymap[Multi.AsEvent()]; ok {
			t.executeActions(acts, Multi.AsEvent())
		}
	}
}

func (t *Terminal) handleEvent(event Event) {
	if event.Type == Fatal {
		t.exit(exitInterrupt)
		return
	}
	if t.jumping != jumpDisabled {
		if event.Type == Rune {
			if idx := strings.IndexRune(t.jumpLabels, event.Char); idx >= 0 && idx < t.maxItems() && idx < t.merger.Length()-t.offset {
				t.cy = idx + t.offset
				t.jumping = jumpDisabled
				t.afterListChange()
				if acts, ok := t.keymap[Jump.AsEvent()]; ok {
					t.executeActions(acts, Jump.AsEvent())
				}
				return
			}
		}
		t.jumping = jumpDisabled
		if acts, ok := t.keymap[JumpCancel.AsEvent()]; ok {
			t.executeActions(acts, JumpCancel.AsEvent())
		}
		return
	}
	// Expect keys
	if pressed, ok := t.expect[event.Comparable()]; ok {
		t.pressed = pressed
		t.lastKey = event.KeyName()
		t.doAccept(false)
		return
	}
	if event.Type == Mouse {
		t.handleMouse(event)
		return
	}
	actions, found := t.keymap[event.Comparable()]
	if !found {
		if event.Type == Rune {
			actions = []*action{{t: actChar}}
		} else {
			return
		}
	}
	t.lastKey = event.KeyName()
	t.executeActions(actions, event)
}

func (t *Terminal) handleMouse(event Event) {
	me := event.MouseEvent
	if me == nil {
		return
	}
	if me.S != 0 {
		// Scroll
		if t.window != nil && t.window.Enclose(me.Y, me.X) {
			if me.S > 0 {
				t.vmove(1, false)
			} else {
				t.vmove(-1, false)
			}
			t.afterListChange()
		} else if t.pwindow != nil && t.pwindow.Enclose(me.Y, me.X) {
			if me.S > 0 {
				t.previewer.offset -= 1
			} else {
				t.previewer.offset += 1
			}
		}
		return
	}
	if me.Down && me.Left && t.window != nil && t.window.Enclose(me.Y, me.X) {
		// Click on an item
		my := me.Y - t.window.top
		start := t.listStartLine()
		maxy := t.maxItems()
		var idx int
		if t.layout == layoutDefault {
			idx = maxy - 1 - (my - start)
		} else {
			idx = my - start
		}
		if idx >= 0 && idx < maxy && t.offset+idx < t.merger.Length() {
			t.cy = t.offset + idx
			t.afterListChange()
		}
	}
}

func (t *Terminal) doAccept(nonEmpty bool) {
	if nonEmpty && t.merger.Length() == 0 && len(t.selected) == 0 {
		return
	}
	t.screen.Close(t.clearOnExit)
	t.ttyState.restore()
	t.closed = true
	if t.output() {
		t.exit(exitOk)
	} else {
		t.exit(exitNoMatch)
	}
}

func (t *Terminal) toggleItem(item *Item) bool {
	if _, found := t.selected[item.Index()]; !found {
		return t.selectItem(item)
	}
	t.deselectItem(item)
	return true
}

func (t *Terminal) selectItem(item *Item) bool {
	if len(t.selected) >= t.multi {
		return false
	}
	if _, found := t.selected[item.Index()]; found {
		return true
	}
	t.selected[item.Index()] = selectedItem{time.Now(), item}
	t.version++
	t.multiEventPending = true
	return true
}

func (t *Terminal) deselectItem(item *Item) {
	delete(t.selected, item.Index())
	t.version++
	t.multiEventPending = true
}

func (t *Terminal) rubout(pattern string) {
	pcx := t.cx
	after := t.input[t.cx:]
	t.cx = findLastMatch(pattern, string(t.input[:t.cx])) + 1
	t.yanked = copySlice(t.input[t.cx:pcx])
	t.input = append(t.input[:t.cx], after...)
}

func (t *Terminal) delChar() bool {
	if len(t.input) > 0 && t.cx < len(t.input) {
		t.input = append(t.input[:t.cx], t.input[t.cx+1:]...)
		return true
	}
	return false
}

func (t *Terminal) queryChanged() {
	t.rematch(t.readerDone())
	t.resultEventPending = true
	if acts, ok := t.keymap[Change.AsEvent()]; ok {
		t.executeActions(acts, Change.AsEvent())
	}
	t.afterListChange()
	// {q} in preview: refresh
	if t.hasPreviewer {
		_, _, forceUpdate := hasPreviewFlags(t.previewOpts.command)
		if forceUpdate {
			t.previewPending = true
		}
	}
}

// executeActions runs the list of actions
func (t *Terminal) executeActions(actions []*action, event Event) {
	for _, act := range actions {
		if t.done {
			return
		}
		if !t.doAction(act, event) {
			return
		}
	}
}

func (t *Terminal) updateHeaderLinesNth(nth []Range) {
	nthRevisionCounter++
	t.nthCurrent = nth
	t.nthChanged = true
}

func (t *Terminal) doAction(a *action, event Event) bool {
	t.lastAction = a.t
	prevInput := copySlice(t.input)
	prevCy := t.cy
	queryChanged := false
	beof := false
	switch a.t {
	case actIgnore, actStart, actClick, actBracketedPasteBegin, actBracketedPasteEnd:
	case actBecome:
		list := t.previewList()
		command, tempFiles := t.replacePlaceholder(a.a, false, string(t.input), list)
		t.previewTempFiles = append(t.previewTempFiles, tempFiles...)
		t.becomeCommand = command
		t.becomeEnv = t.environ()
		t.exit(exitOk)
		return false
	case actExecute, actExecuteSilent, actExecuteMulti:
		t.executeCommand(a.a, false, a.t == actExecuteSilent, false, false)
	case actInvalid:
		return false
	case actBell:
		t.tty.WriteString("\a")
	case actTogglePreview, actShowPreview, actHidePreview:
		if t.hasPreviewer {
			switch a.t {
			case actTogglePreview:
				t.activePreviewOpts.hidden = !t.activePreviewOpts.hidden
			case actShowPreview:
				t.activePreviewOpts.hidden = false
			case actHidePreview:
				t.activePreviewOpts.hidden = true
			}
			t.previewOpts.hidden = t.activePreviewOpts.hidden
			if !t.activePreviewOpts.hidden {
				t.previewPending = true
			}
			t.screen.Invalidate()
		}
	case actTogglePreviewWrap:
		if t.hasPreviewer {
			t.activePreviewOpts.wrap = !t.activePreviewOpts.wrap
		}
	case actTransformPrompt, actBgTransformPrompt:
		out := t.captureCommand(a.a, true)
		t.prompt = out
		t.promptLen = StringWidth(out)
	case actTransformQuery, actBgTransformQuery:
		out := t.captureCommand(a.a, true)
		t.input = []rune(out)
		t.cx = len(t.input)
		queryChanged = true
	case actToggleSort:
		t.sort = !t.sort
		t.rematch(t.readerDone())
	case actPreviewTop:
		if t.hasPreviewWindow() {
			t.previewer.offset = 0
			t.previewer.following = false
		}
	case actPreviewBottom:
		if t.hasPreviewWindow() {
			t.previewer.offset = len(t.previewer.lines) - t.pwindow.Height()
			t.previewer.following = false
		}
	case actPreviewUp:
		if t.hasPreviewWindow() {
			t.previewer.offset -= 1
			t.previewer.following = false
		}
	case actPreviewDown:
		if t.hasPreviewWindow() {
			t.previewer.offset += 1
			t.previewer.following = false
		}
	case actPreviewPageUp:
		if t.hasPreviewWindow() {
			t.previewer.offset -= t.pwindow.Height()
			t.previewer.following = false
		}
	case actPreviewPageDown:
		if t.hasPreviewWindow() {
			t.previewer.offset += t.pwindow.Height()
			t.previewer.following = false
		}
	case actPreviewHalfPageUp:
		if t.hasPreviewWindow() {
			t.previewer.offset -= t.pwindow.Height() / 2
			t.previewer.following = false
		}
	case actPreviewHalfPageDown:
		if t.hasPreviewWindow() {
			t.previewer.offset += t.pwindow.Height() / 2
			t.previewer.following = false
		}
	case actBeginningOfLine:
		t.cx = 0
		t.xoffset = 0
	case actBackwardChar:
		if t.cx > 0 {
			t.cx--
		}
	case actPrintQuery:
		t.printQuery = true
		t.doAccept(false)
		return false
	case actChangeMulti:
		multi := maxMulti
		if a.a == "" {
			multi = maxMulti
		} else if n, err := strconv.Atoi(a.a); err == nil {
			multi = n
		}
		if multi < 0 {
			multi = 0
		}
		if multi == 0 {
			t.selected = make(map[int32]selectedItem)
		} else if multi < len(t.selected) {
			// Truncate
			sels := t.sortSelected()
			t.selected = make(map[int32]selectedItem)
			for _, sel := range sels[:multi] {
				t.selected[sel.item.Index()] = sel
			}
		}
		t.multi = multi
	case actChangeNth, actTransformNth, actBgTransformNth:
		arg := a.a
		if a.t != actChangeNth {
			arg = t.captureCommand(a.a, true)
		}
		options := strings.Split(arg, "|")
		if len(options) == 0 {
			break
		}
		// Rotate
		t.nthRotation = (t.nthRotation + 1) % (len(options) + 1)
		var nth []Range
		idx := t.nthRotation - 1
		if idx < 0 || idx >= len(options) {
			nth = t.nth
			t.nthRotation = 0
		} else if ranges, err := splitNth(options[idx]); err == nil {
			nth = ranges
		} else {
			nth = t.nth
		}
		t.updateHeaderLinesNth(nth)
		t.rematch(t.readerDone())
	case actChangeQuery:
		t.input = []rune(a.a)
		t.cx = len(t.input)
		queryChanged = true
	case actChangeHeader, actTransformHeader, actBgTransformHeader:
		hdr := a.a
		if a.t != actChangeHeader {
			hdr = t.captureCommand(a.a, false)
		}
		if len(hdr) == 0 {
			t.header0 = []string{}
		} else {
			lines := strLines(hdr)
			if t.layout == layoutDefault || t.layout == layoutReverseList {
				lines = reverseStringArray(lines)
			}
			t.header0 = lines
		}
		t.screen.Invalidate()
	case actChangeFooter, actTransformFooter, actBgTransformFooter:
		ftr := a.a
		if a.t != actChangeFooter {
			ftr = t.captureCommand(a.a, false)
		}
		if len(ftr) == 0 {
			t.footer = []string{}
		} else {
			t.footer = strLines(ftr)
		}
		t.screen.Invalidate()
	case actChangeBorderLabel, actTransformBorderLabel, actBgTransformBorderLabel:
		if a.t == actChangeBorderLabel {
			t.borderLabel.label = a.a
		} else {
			t.borderLabel.label = t.captureCommand(a.a, true)
		}
	case actChangeListLabel, actTransformListLabel, actBgTransformListLabel:
		if a.t == actChangeListLabel {
			t.listLabel.label = a.a
		} else {
			t.listLabel.label = t.captureCommand(a.a, true)
		}
	case actChangeInputLabel, actTransformInputLabel, actBgTransformInputLabel:
		if a.t == actChangeInputLabel {
			t.inputLabel.label = a.a
		} else {
			t.inputLabel.label = t.captureCommand(a.a, true)
		}
	case actChangeHeaderLabel, actTransformHeaderLabel, actBgTransformHeaderLabel:
		if a.t == actChangeHeaderLabel {
			t.headerLabel.label = a.a
		} else {
			t.headerLabel.label = t.captureCommand(a.a, true)
		}
	case actChangeFooterLabel, actTransformFooterLabel, actBgTransformFooterLabel:
		if a.t == actChangeFooterLabel {
			t.footerLabel.label = a.a
		} else {
			t.footerLabel.label = t.captureCommand(a.a, true)
		}
	case actChangePreviewLabel, actTransformPreviewLabel, actBgTransformPreviewLabel:
		if a.t == actChangePreviewLabel {
			t.previewLabel.label = a.a
		} else {
			t.previewLabel.label = t.captureCommand(a.a, true)
		}
	case actChangeGhost, actTransformGhost, actBgTransformGhost:
		if a.t == actChangeGhost {
			t.ghost = a.a
		} else {
			t.ghost = t.captureCommand(a.a, true)
		}
	case actChangePointer, actTransformPointer, actBgTransformPointer:
		ptr := a.a
		if a.t != actChangePointer {
			ptr = t.captureCommand(a.a, true)
		}
		if StringWidth(ptr) <= 2 {
			t.pointer = ptr
			t.pointerLen = StringWidth(ptr)
			t.pointerEmpty = strings.Repeat(" ", t.pointerLen)
		}
	case actChangePrompt:
		t.prompt = a.a
		t.promptLen = StringWidth(a.a)
	case actChangePreviewWindow:
		if t.hasPreviewer {
			t.previewOptsRotate(a.a)
			t.screen.Invalidate()
		}
	case actChangePreview:
		if t.previewOpts.command != a.a {
			t.previewOpts.command = a.a
			t.hasPreviewer = true
			t.previewPending = true
		}
	case actPreview:
		t.hasPreviewer = true
		if t.activePreviewOpts.hidden {
			t.activePreviewOpts.hidden = false
		}
		t.screen.Invalidate()
		list := t.previewList()
		replaced, tempFiles := t.replacePlaceholder(a.a, false, string(t.input), list)
		t.previewTempFiles = append(t.previewTempFiles, tempFiles...)
		t.resizeWindows(false)
		t.startPreview(previewRequest{template: replaced, env: t.environ(), list: list})
	case actRefreshPreview:
		if t.hasPreviewer {
			t.previewPending = true
		}
	case actReplaceQuery:
		if t.merger.Length() > 0 {
			t.input = []rune(t.currentItem().text.ToString())
			t.cx = len(t.input)
			queryChanged = true
		}
	case actFatal:
		t.exit(exitInterrupt)
		return false
	case actAbort:
		t.exit(exitInterrupt)
		return false
	case actDeleteChar:
		t.delChar()
	case actDeleteCharEof:
		if !t.delChar() && t.cx == 0 {
			t.exit(exitInterrupt)
			return false
		}
	case actEndOfLine:
		t.cx = len(t.input)
	case actCancel:
		if len(t.input) == 0 {
			t.exit(exitInterrupt)
			return false
		}
		t.yanked = t.input
		t.input = []rune{}
		t.cx = 0
	case actClose:
		if t.hasPreviewer && !t.activePreviewOpts.hidden {
			t.activePreviewOpts.hidden = true
			t.previewOpts.hidden = true
			t.screen.Invalidate()
		} else {
			t.exit(exitInterrupt)
			return false
		}
	case actBackwardDeleteCharEof:
		if len(t.input) == 0 {
			t.exit(exitInterrupt)
			return false
		}
		if t.cx > 0 {
			t.input = append(t.input[:t.cx-1], t.input[t.cx:]...)
			t.cx--
		}
	case actForwardChar:
		if t.cx < len(t.input) {
			t.cx++
		}
	case actBackwardDeleteChar:
		beof = len(t.input) == 0
		if t.cx > 0 {
			t.input = append(t.input[:t.cx-1], t.input[t.cx:]...)
			t.cx--
		}
	case actSelectAll:
		if t.multi > 0 {
			for i := 0; i < t.merger.Length(); i++ {
				if !t.selectItem(t.merger.Get(i).item) {
					break
				}
			}
		}
	case actDeselectAll:
		if t.multi > 0 {
			for i := 0; i < t.merger.Length() && len(t.selected) > 0; i++ {
				t.deselectItem(t.merger.Get(i).item)
			}
		}
	case actClearSelection:
		if t.multi > 0 && len(t.selected) > 0 {
			t.selected = make(map[int32]selectedItem)
			t.version++
			t.multiEventPending = true
		}
	case actSelect:
		if t.multi > 0 && t.merger.Length() > 0 {
			t.selectItem(t.currentItem())
		}
	case actDeselect:
		if t.multi > 0 && t.merger.Length() > 0 {
			t.deselectItem(t.currentItem())
		}
	case actToggle:
		if t.multi > 0 && t.merger.Length() > 0 {
			t.toggleItem(t.currentItem())
		}
	case actToggleAll:
		if t.multi > 0 {
			prevIndexes := make(map[int]struct{})
			for i := 0; i < t.merger.Length() && len(t.selected) > 0; i++ {
				item := t.merger.Get(i).item
				if _, found := t.selected[item.Index()]; found {
					prevIndexes[i] = struct{}{}
					t.deselectItem(item)
				}
			}
			for i := 0; i < t.merger.Length(); i++ {
				if _, found := prevIndexes[i]; !found {
					item := t.merger.Get(i).item
					if !t.selectItem(item) {
						break
					}
				}
			}
		}
	case actToggleIn:
		if t.layout != layoutDefault {
			return t.doAction(&action{t: actToggleUp}, event)
		}
		return t.doAction(&action{t: actToggleDown}, event)
	case actToggleOut:
		if t.layout != layoutDefault {
			return t.doAction(&action{t: actToggleDown}, event)
		}
		return t.doAction(&action{t: actToggleUp}, event)
	case actToggleDown:
		if t.multi > 0 && t.merger.Length() > 0 && t.toggleItem(t.currentItem()) {
			t.vmove(-1, true)
		}
	case actToggleUp:
		if t.multi > 0 && t.merger.Length() > 0 && t.toggleItem(t.currentItem()) {
			t.vmove(1, true)
		}
	case actDown:
		t.vmove(-1, true)
	case actUp:
		t.vmove(1, true)
	case actDownMatch, actUpMatch:
		// Same as down/up in non-raw mode
		if a.t == actDownMatch {
			t.vmove(-1, true)
		} else {
			t.vmove(1, true)
		}
	case actAccept:
		t.doAccept(false)
		return false
	case actAcceptNonEmpty:
		if len(t.selected) > 0 || t.merger.Length() > 0 {
			t.doAccept(false)
			return false
		}
	case actAcceptOrPrintQuery:
		if len(t.selected) == 0 && t.merger.Length() == 0 {
			t.printQueueQuery = true
		}
		t.doAcceptOrPrintQuery()
		return false
	case actClearScreen:
		t.screen.Invalidate()
		if t.fullscreen {
			t.screen.write("\x1b[H\x1b[2J")
		}
	case actClearQuery:
		t.input = []rune{}
		t.cx = 0
	case actFirst:
		t.vset(0)
		t.constrain()
	case actLast:
		t.vset(t.merger.Length() - 1)
		t.constrain()
	case actBest:
		t.vset(0)
	case actPosition:
		if n, e := strconv.Atoi(a.a); e == nil {
			if n > 0 {
				n--
			} else if n < 0 {
				n += t.merger.Length()
			}
			t.vset(n)
			t.constrain()
		}
	case actPut:
		str := []rune(a.a)
		suffix := copySlice(t.input[t.cx:])
		t.input = append(append(t.input[:t.cx], str...), suffix...)
		t.cx += len(str)
	case actPrint:
		t.printQueue = append(t.printQueue, a.a)
	case actUnixLineDiscard:
		beof = len(t.input) == 0
		if t.cx > 0 {
			t.yanked = copySlice(t.input[:t.cx])
			t.input = t.input[t.cx:]
			t.cx = 0
		}
	case actUnixWordRubout:
		beof = len(t.input) == 0
		if t.cx > 0 {
			t.rubout("\\s\\S")
		}
	case actBackwardKillWord:
		beof = len(t.input) == 0
		if t.cx > 0 {
			t.rubout(t.wordRubout)
		}
	case actBackwardKillSubword:
		beof = len(t.input) == 0
		if t.cx > 0 {
			t.rubout(`[^\pL\pN_][\pL\pN_]*|_[\pL\pN]*`)
		}
	case actYank:
		suffix := copySlice(t.input[t.cx:])
		t.input = append(append(t.input[:t.cx], t.yanked...), suffix...)
		t.cx += len(t.yanked)
	case actPageUp:
		t.vmove(t.maxItems()-1, false)
	case actPageDown:
		t.vmove(-(t.maxItems() - 1), false)
	case actHalfPageUp:
		t.vmove(t.maxItems()/2, false)
	case actHalfPageDown:
		t.vmove(-(t.maxItems() / 2), false)
	case actOffsetUp, actOffsetDown:
		diff := 1
		if a.t == actOffsetDown {
			diff = -1
		}
		if t.layout == layoutReverse {
			diff *= -1
		}
		t.offset += diff
		before := t.offset
		t.constrain()
		if before != t.offset {
			t.offset = before
			if t.layout == layoutReverse {
				diff *= -1
			}
			t.vmove(diff, false)
		}
	case actOffsetMiddle:
		soff := t.scrollOff
		t.scrollOff = t.window.Height()
		t.constrain()
		t.scrollOff = soff
	case actJump:
		t.jumping = jumpEnabled
	case actJumpAccept:
		t.jumping = jumpAcceptEnabled
	case actBackwardWord:
		t.cx = findLastMatch(t.wordRubout, string(t.input[:t.cx])) + 1
	case actBackwardSubword:
		t.cx = findLastMatch(`[^\pL\pN_][\pL\pN_]*|_[\pL\pN]*`, string(t.input[:t.cx])) + 1
	case actForwardWord:
		t.cx += findFirstMatch(t.wordNext, string(t.input[t.cx:])) + 1
	case actForwardSubword:
		t.cx += findFirstMatch(`[\pL\pN][^\pL\pN_]*|_[^\pL\pN_]*|(.$)`, string(t.input[t.cx:])) + 1
	case actKillWord:
		ncx := t.cx + findFirstMatch(t.wordNext, string(t.input[t.cx:])) + 1
		if ncx > t.cx {
			t.yanked = copySlice(t.input[t.cx:ncx])
			t.input = append(t.input[:t.cx], t.input[ncx:]...)
		}
	case actKillSubword:
		ncx := t.cx + findFirstMatch(`[\pL\pN][^\pL\pN_]*|_[^\pL\pN_]*|(.$)`, string(t.input[t.cx:])) + 1
		if ncx > t.cx {
			t.yanked = copySlice(t.input[t.cx:ncx])
			t.input = append(t.input[:t.cx], t.input[ncx:]...)
		}
	case actKillLine:
		if t.cx < len(t.input) {
			t.yanked = copySlice(t.input[t.cx:])
			t.input = t.input[:t.cx]
		}
	case actChar:
		if event.Type == Rune && !t.inputless {
			prefix := copySlice(t.input[:t.cx])
			t.input = append(append(prefix, event.Char), t.input[t.cx:]...)
			t.cx++
		}
	case actPrevHistory:
		if t.history != nil {
			t.history.override(string(t.input))
			t.input = []rune(t.history.previous())
			t.cx = len(t.input)
		}
	case actNextHistory:
		if t.history != nil {
			t.history.override(string(t.input))
			t.input = []rune(t.history.next())
			t.cx = len(t.input)
		}
	case actToggleSearch:
		t.disabled = !t.disabled
		t.rematch(t.readerDone())
	case actEnableSearch:
		t.disabled = false
		t.rematch(t.readerDone())
	case actDisableSearch:
		t.disabled = true
		t.rematch(t.readerDone())
	case actSigStop:
	case actMouse:
	case actToggleTrack:
		switch t.track {
		case trackEnabled:
			t.track = trackDisabled
		case trackDisabled:
			t.track = trackEnabled
		}
	case actToggleTrackCurrent:
		switch t.track {
		case trackCurrent:
			t.track = trackDisabled
		case trackDisabled:
			t.track = trackCurrent
		}
	case actTrackCurrent:
		if t.track == trackDisabled {
			t.track = trackCurrent
		}
	case actUntrackCurrent:
		if t.track == trackCurrent {
			t.track = trackDisabled
		}
	case actToggleHeader:
		t.headerVisible = !t.headerVisible
		t.screen.Invalidate()
	case actShowHeader:
		t.headerVisible = true
		t.screen.Invalidate()
	case actHideHeader:
		t.headerVisible = false
		t.screen.Invalidate()
	case actToggleWrap:
		t.wrap = !t.wrap
	case actToggleMultiLine:
		t.multiLine = !t.multiLine
	case actToggleHscroll:
		t.hscroll = !t.hscroll
	case actToggleRaw:
		t.raw = !t.raw
	case actEnableRaw:
		t.raw = true
	case actDisableRaw:
		t.raw = false
	case actShowInput:
		t.inputless = false
		t.screen.Invalidate()
	case actHideInput:
		t.inputless = true
		t.screen.Invalidate()
	case actToggleInput:
		t.inputless = !t.inputless
		t.screen.Invalidate()
	case actSearch, actTransformSearch, actBgTransformSearch:
		arg := a.a
		if a.t != actSearch {
			arg = t.captureCommand(a.a, true)
		}
		t.inputOverride = &[]rune{}
		*t.inputOverride = []rune(arg)
		t.searchOverride(arg)
	case actExclude:
		if item := t.currentItem(); item != nil {
			t.denylist = append(t.denylist, item.Index())
			t.deselectItem(item)
			t.rematch(t.readerDone())
		}
	case actExcludeMulti:
		if len(t.selected) > 0 {
			for _, sel := range t.sortSelected() {
				t.denylist = append(t.denylist, sel.item.Index())
			}
			t.selected = make(map[int32]selectedItem)
			t.version++
		} else if item := t.currentItem(); item != nil {
			t.denylist = append(t.denylist, item.Index())
		}
		t.rematch(t.readerDone())
	case actPrevSelected, actNextSelected:
		if len(t.selected) > 0 {
			total := t.merger.Length()
			for i := 1; i < total; i++ {
				y := (t.cy + i) % total
				if t.layout == layoutDefault && a.t == actPrevSelected ||
					t.layout != layoutDefault && a.t == actNextSelected {
					y = (t.cy - i + total) % total
				}
				if _, found := t.selected[t.merger.Get(y).item.Index()]; found {
					t.vset(y)
					break
				}
			}
		}
	case actReload, actReloadSync:
		t.reload(a.a, a.t == actReloadSync)
	case actUnbind, actRebind, actToggleBind:
		keys, _ := parseKeyChords(a.a, "")
		for key := range keys {
			switch a.t {
			case actUnbind:
				if _, ok := t.keymap[key]; ok {
					if t.keymapOrg == nil {
						t.keymapOrg = make(map[Event][]*action)
					}
					t.keymapOrg[key] = t.keymap[key]
					delete(t.keymap, key)
				}
			case actRebind:
				if acts, ok := t.keymapOrg[key]; ok {
					t.keymap[key] = acts
				}
			case actToggleBind:
				if _, ok := t.keymap[key]; ok {
					if t.keymapOrg == nil {
						t.keymapOrg = make(map[Event][]*action)
					}
					t.keymapOrg[key] = t.keymap[key]
					delete(t.keymap, key)
				} else if acts, ok := t.keymapOrg[key]; ok {
					t.keymap[key] = acts
				}
			}
		}
	case actTrigger:
		keys, _ := parseKeyChords(a.a, "")
		for key := range keys {
			if acts, ok := t.keymap[key]; ok {
				t.executeActions(acts, key)
			}
		}
	case actTransform, actBgTransform:
		out := t.captureCommand(a.a, false)
		if acts, err := parseSingleActionList(strings.TrimSpace(out)); err == nil {
			t.executeActions(acts, event)
		}
	case actBgCancel:
	}

	if !t.done {
		if string(t.input) != string(prevInput) {
			queryChanged = true
			t.inputOverride = nil
		}
		if queryChanged {
			t.queryChanged()
		}
		if beof {
			if acts, ok := t.keymap[BackwardEOF.AsEvent()]; ok {
				t.executeActions(acts, BackwardEOF.AsEvent())
			}
		}
		if t.cy != prevCy || t.currentIndex() != t.lastFocus {
			t.afterListChange()
		}
	}
	return true
}

func (t *Terminal) searchOverride(query string) {
	// Run the search with the given query without changing the input
	pattern := t.patternBuilder([]rune(query))
	if t.nthChanged {
		pattern.nth = t.nthCurrent
	}
	t.pattern = pattern
	snapshot, count, _ := t.chunkList.Snapshot(t.opts.Tail)
	t.count = count
	t.revision++
	t.merger = matchItems(snapshot, pattern, t.sort, t.opts.Tac, t.revision, t.slab)
	t.resultEventPending = true
	t.afterListChange()
}

func (t *Terminal) doAcceptOrPrintQuery() {
	t.screen.Close(t.clearOnExit)
	t.ttyState.restore()
	t.closed = true
	if t.printQueueQuery {
		if t.printQuery {
			t.printer(string(t.input))
		}
		if len(t.expect) > 0 {
			t.printer(t.pressed)
		}
		for _, s := range t.printQueue {
			t.printer(s)
		}
		t.printer(string(t.input))
		t.exit(exitOk)
		return
	}
	if t.output() {
		t.exit(exitOk)
	} else {
		t.exit(exitNoMatch)
	}
}

func (t *Terminal) previewOptsRotate(arg string) {
	options := strings.Split(arg, "|")
	t.previewRotation = (t.previewRotation + 1) % len(options)
	// Start from the initial options and apply
	newOpts := t.initialPreviewOpts
	newOpts.command = t.previewOpts.command
	parsePreviewWindowImpl(&newOpts, options[t.previewRotation])
	t.previewOpts = newOpts
	t.activePreviewOpts = &t.previewOpts
	if !t.previewOpts.hidden {
		t.previewPending = true
	}
}

// captureCommand runs the command and returns its output (first line if firstLineOnly)
func (t *Terminal) captureCommand(template string, firstLineOnly bool) string {
	list := t.previewList()
	command, tempFiles := t.replacePlaceholder(template, false, string(t.input), list)
	defer cleanTemporaryFiles(tempFiles)
	cmd := t.executor.ExecCommand(command, false)
	cmd.Env = t.environ()
	out, _ := cmd.Output()
	str := string(out)
	if firstLineOnly {
		str = strings.TrimRight(firstLine(str), "\r\n")
	} else {
		str = strings.TrimRight(str, "\r\n")
	}
	return str
}

// executeCommand runs execute/execute-silent
func (t *Terminal) executeCommand(template string, forcePlus bool, background bool, capture bool, firstLineOnly bool) string {
	list := t.previewList()
	command, tempFiles := t.replacePlaceholder(template, forcePlus, string(t.input), list)
	defer cleanTemporaryFiles(tempFiles)
	cmd := t.executor.ExecCommand(command, false)
	cmd.Env = t.environ()
	if !background {
		// Pause the UI
		t.screen.Close(true)
		t.ttyState.restore()
		cmd.Stdin = t.tty
		cmd.Stdout = t.tty
		cmd.Stderr = t.tty
		cmd.Run()
		t.ttyState.makeRaw()
		t.screen.Init(t.mouse)
		t.screen.Invalidate()
		return ""
	}
	devnull, _ := os.Open(os.DevNull)
	if devnull != nil {
		cmd.Stdin = devnull
		defer devnull.Close()
	}
	cmd.Run()
	return ""
}

// reload restarts the reader with the given command
func (t *Terminal) reload(template string, sync bool) {
	list := t.previewList()
	command, tempFiles := t.replacePlaceholder(template, false, string(t.input), list)
	t.previewTempFiles = append(t.previewTempFiles, tempFiles...)
	env := t.environ()
	// Reset the list
	t.chunkList.Clear()
	t.headerMutex.Lock()
	*t.headerPtr = (*t.headerPtr)[:0]
	t.headerMutex.Unlock()
	t.denylist = nil
	t.selected = make(map[int32]selectedItem)
	t.cy = 0
	t.offset = 0
	t.startReader(nil, command, env)
	t.rematch(false)
	if sync {
		// Wait for completion
		for !t.readerDone() {
			select {
			case <-t.readerChan:
			case <-time.After(20 * time.Millisecond):
			}
		}
		t.reading = false
		t.rematch(true)
	}
}

func (t *Terminal) UpdateProgress(p float32) {
	t.progress = int(p * 100)
}

func runeIsPrintable(r rune) bool { return unicode.IsPrint(r) }

func (t *Terminal) debug(format string, a ...interface{}) {
	f, _ := os.OpenFile("/tmp/fzfclone-debug.log", os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
	if f != nil {
		fmt.Fprintf(f, format+"\n", a...)
		f.Close()
	}
}
