	case actTrackCurrent:
		if t.track == trackDisabled {
			t.track = trackCurrent
		}
	case actUntrackCurrent:
		if t.track == trackCurrent {
			t.track = trackDisabled
		}
	case actToggleHeader:
		t.headerVisible = !t.headerVisible
		t.screen.Invalidate()
	case actShowHeader:
		t.headerVisible = true
		t.screen.Invalidate()
	case actHideHeader:
		t.headerVisible = false
		t.screen.Invalidate()
	case actToggleWrap:
		t.wrap = !t.wrap
	case actToggleMultiLine:
		t.multiLine = !t.multiLine
	case actToggleHscroll:
		t.hscroll = !t.hscroll
	case actToggleRaw:
		t.raw = !t.raw
	case actEnableRaw:
		t.raw = true
	case actDisableRaw:
		t.raw = false
	case actShowInput:
		t.inputless = false
		t.screen.Invalidate()
	case actHideInput:
		t.inputless = true
		t.screen.Invalidate()
	case actToggleInput:
		t.inputless = !t.inputless
		t.screen.Invalidate()
