		}
		t.inputOverride = &[]rune{}
		*t.inputOverride = []rune(arg)
		t.searchOverride(arg)
	case actExclude:
		if item := t.currentItem(); item != nil {
			t.denylist = append(t.denylist, item.Index())
			t.deselectItem(item)
			t.rematch(t.readerDone())
		}
	case actExcludeMulti:
		if len(t.selected) > 0 {
			for _, sel := range t.sortSelected() {
				t.denylist = append(t.denylist, sel.item.Index())
			}
			t.selected = make(map[int32]selectedItem)
			t.version++
		} else if item := t.currentItem(); item != nil {
			t.denylist = append(t.denylist, item.Index())
		}
		t.rematch(t.readerDone())
	case actPrevSelected, actNextSelected:
		if len(t.selected) > 0 {
			total := t.merger.Length()
			for i := 1; i < total; i++ {
				y := (t.cy + i) % total
				if t.layout == layoutDefault && a.t == actPrevSelected ||
					t.layout != layoutDefault && a.t == actNextSelected {
					y = (t.cy - i + total) % total
				}
				if _, found := t.selected[t.merger.Get(y).item.Index()]; found {
					t.vset(y)
