					}
					t.keymapOrg[key] = t.keymap[key]
					delete(t.keymap, key)
				}
			case actRebind:
				if acts, ok := t.keymapOrg[key]; ok {
					t.keymap[key] = acts
				}
			case actToggleBind:
				if _, ok := t.keymap[key]; ok {
					if t.keymapOrg == nil {
						t.keymapOrg = make(map[Event][]*action)
					}
					t.keymapOrg[key] = t.keymap[key]
					delete(t.keymap, key)
