			t.afterListChange()
		}
	}
	return true
}

func (t *Terminal) searchOverride(query string) {
	// Run the search with the given query without changing the input
	pattern := t.patternBuilder([]rune(query))
	if t.nthChanged {
		pattern.nth = t.nthCurrent
	}
	t.pattern = pattern
	snapshot, count, _ := t.chunkList.Snapshot(t.opts.Tail)
	t.count = count
	t.revision++
	t.merger = matchItems(snapshot, pattern, t.sort, t.opts.Tac, t.revision, t.slab)
	t.resultEventPending = true
	t.afterListChange()
}

func (t *Terminal) doAcceptOrPrintQuery() {
	t.screen.Close(t.clearOnExit)
	t.ttyState.restore()
	t.closed = true
	if t.printQueueQuery {
		if t.printQuery {
			t.printer(string(t.input))
		}
		if len(t.expect) > 0 {
			t.printer(t.pressed)
		}
		for _, s := range t.printQueue {
			t.printer(s)
		}
		t.printer(string(t.input))
		t.exit(exitOk)
		return
	}
	if t.output() {
		t.exit(exitOk)
	} else {
		t.exit(exitNoMatch)
	}
}

func (t *Terminal) previewOptsRotate(arg string) {
	options := strings.Split(arg, "|")
	t.previewRotation = (t.previewRotation + 1) % len(options)
	// Start from the initial options and apply
	newOpts := t.initialPreviewOpts
	newOpts.command = t.previewOpts.command
	parsePreviewWindowImpl(&newOpts, options[t.previewRotation])
	t.previewOpts = newOpts
	t.activePreviewOpts = &t.previewOpts
	if !t.previewOpts.hidden {
		t.previewPending = true
	}
}

// captureCommand runs the command and returns its output (first line if firstLineOnly)
func (t *Terminal) captureCommand(template string, firstLineOnly bool) string {
	list := t.previewList()
	command, tempFiles := t.replacePlaceholder(template, false, string(t.input), list)
	defer cleanTemporaryFiles(tempFiles)
	cmd := t.executor.ExecCommand(command, false)
	cmd.Env = t.environ()
	out, _ := cmd.Output()
	str := string(out)
	if firstLineOnly {
		str = strings.TrimRight(firstLine(str), "\r\n")
	} else {
		str = strings.TrimRight(str, "\r\n")
	}
	return str
}

// executeCommand runs execute/execute-silent
func (t *Terminal) executeCommand(template string, forcePlus bool, background bool, capture bool, firstLineOnly bool) string {
	list := t.previewList()
	command, tempFiles := t.replacePlaceholder(template, forcePlus, string(t.input), list)
	defer cleanTemporaryFiles(tempFiles)
	cmd := t.executor.ExecCommand(command, false)
	cmd.Env = t.environ()
	if !background {
		// Pause the UI
		t.screen.Close(true)
		t.ttyState.restore()
		cmd.Stdin = t.tty
		cmd.Stdout = t.tty
		cmd.Stderr = t.tty
		cmd.Run()
		t.ttyState.makeRaw()
		t.screen.Init(t.mouse)
		t.screen.Invalidate()
		return ""
	}
	devnull, _ := os.Open(os.DevNull)
	if devnull != nil {
		cmd.Stdin = devnull
		defer devnull.Close()
	}
	cmd.Run()
	return ""
}

// reload restarts the reader with the given command
func (t *Terminal) reload(template string, sync bool) {
	list := t.previewList()
	command, tempFiles := t.replacePlaceholder(template, false, string(t.input), list)
	t.previewTempFiles = append(t.previewTempFiles, tempFiles...)
	env := t.environ()
	// Reset the list
	t.chunkList.Clear()
	t.headerMutex.Lock()
	*t.headerPtr = (*t.headerPtr)[:0]
	t.headerMutex.Unlock()
	t.denylist = nil
	t.selected = make(map[int32]selectedItem)
	t.cy = 0
	t.offset = 0
	t.startReader(nil, command, env)
	t.rematch(false)
	if sync {
		// Wait for completion
		for !t.readerDone() {
			select {
			case <-t.readerChan:
			case <-time.After(20 * time.Millisecond):
			}
		}
		t.reading = false
		t.rematch(true)
	}
}

func (t *Terminal) UpdateProgress(p float32) {
	t.progress = int(p * 100)
}

func runeIsPrintable(r rune) bool { return unicode.IsPrint(r) }

func (t *Terminal) debug(format string, a ...interface{}) {
	f, _ := os.OpenFile("/tmp/fzfclone-debug.log", os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
	if f != nil {
		fmt.Fprintf(f, format+"\n", a...)
		f.Close()
	}
}
