package main

import (
	"encoding/json"
	"fmt"
	"io"
	"net"
	"net/http"
	"os"
	"strconv"
	"strings"
)

type serverRequest struct {
	actions []*action
	done    chan bool
}

// startServer starts the HTTP server for --listen
func (t *Terminal) startServer() error {
	addr := t.listenAddr
	if addr == nil {
		return nil
	}
	var listener net.Listener
	var err error
	if addr.path != "" {
		os.Remove(addr.path)
		listener, err = net.Listen("unix", addr.path)
		if err != nil {
			return err
		}
		t.listenSock = addr.path
	} else {
		listener, err = net.Listen("tcp", fmt.Sprintf("%s:%d", addr.host, addr.port))
		if err != nil {
			return err
		}
		t.listenPort = listener.Addr().(*net.TCPAddr).Port
	}
	apiKey := os.Getenv("FZF_API_KEY")
	if !addr.IsLocal() && addr.path == "" && apiKey == "" {
		listener.Close()
		return errorf("FZF_API_KEY is required to allow remote access")
	}
	mux := http.NewServeMux()
	mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		if apiKey != "" && r.Header.Get("x-api-key") != apiKey {
			w.WriteHeader(http.StatusUnauthorized)
			w.Write([]byte("invalid api key\n"))
			return
		}
		switch r.Method {
		case http.MethodGet:
			limit := 100
			offset := 0
			if v := r.URL.Query().Get("limit"); v != "" {
				limit, _ = strconv.Atoi(v)
			}
			if v := r.URL.Query().Get("offset"); v != "" {
				offset, _ = strconv.Atoi(v)
			}
			resp := make(chan []byte, 1)
			t.serverChan <- serverRequest{actions: nil, done: nil, getState: func() []byte {
				return t.stateJSON(limit, offset)
			}, resp: resp}
			data := <-resp
			w.Header().Set("Content-Type", "application/json")
			w.Write(data)
		case http.MethodPost:
			body, _ := io.ReadAll(r.Body)
			str := strings.TrimSpace(string(body))
			actions, err := parseSingleActionList(str)
			if err != nil {
				w.WriteHeader(http.StatusBadRequest)
				w.Write([]byte(err.Error() + "\n"))
				return
			}
			if !t.unsafe {
				for _, a := range actions {
					switch a.t {
					case actExecute, actExecuteSilent, actExecuteMulti, actReload, actReloadSync, actBecome,
						actPreview, actChangePreview, actTransform, actBgTransform,
						actTransformBorderLabel, actTransformGhost, actTransformHeader, actTransformFooter, actTransformHeaderLabel,
						actTransformFooterLabel, actTransformInputLabel, actTransformListLabel, actTransformNth, actTransformPointer,
						actTransformPreviewLabel, actTransformPrompt, actTransformQuery, actTransformSearch:
						w.WriteHeader(http.StatusBadRequest)
						w.Write([]byte("remote execution is not allowed\n"))
						return
					}
				}
			}
			done := make(chan bool, 1)
			t.serverChan <- serverRequest{actions: actions, done: done}
			<-done
			w.WriteHeader(http.StatusOK)
		default:
			w.WriteHeader(http.StatusMethodNotAllowed)
		}
	})
	go http.Serve(listener, mux)
	return nil
}

func (t *Terminal) stateJSON(limit, offset int) []byte {
	type matchJSON struct {
		Index int32 `json:"index"`
		Text  string `json:"text"`
	}
	type stateJSON struct {
		Reading    bool        `json:"reading"`
		Query      string      `json:"query"`
		Position   int         `json:"position"`
		Sort       bool        `json:"sort"`
		TotalCount int         `json:"totalCount"`
		MatchCount int         `json:"matchCount"`
		Current    *matchJSON  `json:"current"`
		Matches    []matchJSON `json:"matches"`
		Selected   []matchJSON `json:"selected"`
	}
	st := stateJSON{
		Reading:    t.reading,
		Query:      string(t.input),
		Position:   t.cy,
		Sort:       t.sort,
		TotalCount: t.count,
		MatchCount: t.merger.Length(),
		Matches:    []matchJSON{},
		Selected:   []matchJSON{},
	}
	if cur := t.currentItem(); cur != nil {
		st.Current = &matchJSON{cur.Index(), cur.text.ToString()}
	}
	for i := offset; i < t.merger.Length() && i < offset+limit; i++ {
		item := t.merger.Get(i).item
		st.Matches = append(st.Matches, matchJSON{item.Index(), item.text.ToString()})
	}
	for _, sel := range t.sortSelected() {
		st.Selected = append(st.Selected, matchJSON{sel.item.Index(), sel.item.text.ToString()})
	}
	data, _ := json.Marshal(st)
	return data
}
